window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s8-60","number":60,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"لماذا حُدد المدد بـ﴿ألف من الملائكة﴾؟","answer":"تحديد الألف يطمئن المؤمنين بعدد محسوس يناسب حاجتهم يوم بدر، مع بقاء النصر من عند الله لا بكثرة العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص624–627.","url":""}]},{"id":"s8-61","number":61,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"لماذا وصف الملائكة بـ﴿مردفين﴾؟","answer":"﴿مردفين﴾ تدل على مجيء الملائكة متتابعين يردف بعضهم بعضًا، أو مردَفين بغيرهم، وفي الحالين تصوير لتوالي المدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص626–629.","url":""}]},{"id":"s8-62","number":62,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"لماذا جاء المدد في الأنفال بـ﴿ألف من الملائكة مردفين﴾، وفي آل عمران بثلاثة آلاف ثم خمسة آلاف؟","answer":"ألف الأنفال وعد بدر المنجز عند الاستغاثة، أما الثلاثة والخمسة في آل عمران فمدد مشروط بالصبر والتقوى وبحسب تجدد البشارة؛ فلا تعارض بين المقامين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص697–705، تحت آل عمران 124–126.","url":""}]},{"id":"s8-63","number":63,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"لماذا وصف الملائكة في الأنفال بـ﴿مردفين﴾، وفي آل عمران بـ﴿مسوّمين﴾؟","answer":"﴿مردفين﴾ في الأنفال تلائم بيان تتابع المدد، و﴿مسومين﴾ في آل عمران تلائم وصف علامتهم وهيئتهم؛ فكل موضع أبرز جهة يقتضيها سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص697–705، تحت آل عمران 124–126.","url":""}]},{"id":"s8-64","number":64,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"لماذا نفى الغاية القتالية المباشرة فقال: ﴿وما جعله الله إلا بشرى﴾؟","answer":"قصر جعل المدد على البشرى والطمأنينة؛ لينفي استقلال الملائكة بإيجاد النصر، ويقرر أن النصر كله من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص630–633.","url":""}]},{"id":"s8-65","number":65,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتطمئن به قلوبكم﴾، مع أن البشرى موجهة إليهم جميعًا؟","answer":"أُسند الاطمئنان إلى القلوب لأنها محل الخوف والسكينة، فدل على أمن داخلي يعم الجماعة من أصل شعورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص632–635.","url":""}]},{"id":"s8-66","number":66,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"ما سرّ تقديم ﴿به﴾ في ﴿ولتطمئن به قلوبكم﴾؟","answer":"قُدّم ﴿به﴾ للعناية بسبب الطمأنينة، ولربطها بالمدد المذكور مع التأكيد أن أثره نفسي لا أنه مصدر النصر استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص634–636.","url":""}]},{"id":"s8-67","number":67,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"لماذا اعترض بقوله: ﴿وما النصر إلا من عند الله﴾ وسط الحديث عن الملائكة؟","answer":"اعترض بنفي النصر إلا من عند الله لئلا يتعلق القلب بالملائكة أو العدد، فهما بشرى وسبب، أما موجد النصر فهو الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص635–638.","url":""}]},{"id":"s8-68","number":68,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿من عند الله﴾ لا «من الله» فقط؟","answer":"﴿من عند الله﴾ أدل على صدور النصر من جهة قدرته وتدبيره الخاص، لا على مجرد نسبة الفعل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص637–639.","url":""}]},{"id":"s8-69","number":69,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"ما مناسبة الختم بـ﴿إن الله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ لا يغلبه غالب وهو القادر على النصر، و﴿حكيم﴾ يضع النصر وأسبابه في مواضعها؛ فالختام جامع للقدرة والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص639–641.","url":""}]},{"id":"s8-70","number":70,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى في آل عمران: ﴿بشرى لكم﴾، وحذف ﴿لكم﴾ في الأنفال فقال: ﴿إلا بشرى﴾؟","answer":"ذُكرت ﴿لكم﴾ في آل عمران لتجدد توجيه البشرى إليهم في سياق الوعد، وحذفت في الأنفال لاكتفاء السياق بضمائرهم في ﴿ممدكم﴾ و﴿قلوبكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص705–706، تحت آل عمران 126.","url":""}]},{"id":"s8-71","number":71,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى في الأنفال: ﴿ولتطمئن به قلوبكم﴾، وفي آل عمران: ﴿ولتطمئن قلوبكم به﴾؟","answer":"قُدّم ﴿به﴾ في الأنفال لقرب ذكر المدد والعناية بكونه سبب الطمأنينة، وأُخر في آل عمران لأن العناية هناك بطمأنينة القلوب المخاطبة عقب ﴿بشرى لكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص706–707، تحت آل عمران 126.","url":""}]},{"id":"s8-72","number":72,"surah":8,"verses":[10],"verseLabel":"الأنفال: 10","question":"لماذا ختم آية الأنفال بـ﴿إن الله عزيز حكيم﴾، وختم نظيرتها في آل عمران بـ﴿العزيز الحكيم﴾؟","answer":"جاء ﴿إن الله عزيز حكيم﴾ في الأنفال جملة تعليلية مستقلة بعد تقرير انفراد الله بالنصر، وأما ﴿العزيز الحكيم﴾ في آل عمران فتابع لاسم الله السابق ووصف له.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص707–708، تحت آل عمران 126.","url":""}]},{"id":"s8-73","number":73,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"لماذا جعل النعاس نفسه يغشى المؤمنين: ﴿يغشيكم النعاس﴾؟","answer":"أُسند الإغشاء إلى الله والنعاس مفعوله؛ لتصوير إحاطة النعاس بهم بتقديره، حتى عمهم ستره وأزال قلقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص642–645.","url":""}]},{"id":"s8-74","number":74,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"لماذا وصف النعاس بأنه ﴿أمنة منه﴾؟","answer":"النعاس ﴿أمنة منه﴾ لأنه علامة زوال الخوف في موطن الحرب، ومنحة من الله سكّن بها نفوسهم وقواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص644–647.","url":""}]},{"id":"s8-75","number":75,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿وينزل عليكم من السماء ماء﴾ مع أن إنزال الماء معلوم المصدر؟","answer":"ذكر ﴿من السماء﴾ يثبت جهة الإنزال ويعظم المنة؛ فقد جاء الماء من فوق في وقت حاجتهم وفي أرض لا ماء فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص646–649.","url":""}]},{"id":"s8-76","number":76,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"لماذا جمع للماء أربع وظائف: التطهير، وإذهاب الرجز، وربط القلوب، وتثبيت الأقدام؟","answer":"جمع الماء مصالح الظاهر والباطن: طهارة الأبدان، وإزالة وسوسة الشيطان، وتقوية القلوب، وتماسك الرمل تحت الأقدام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص648–653.","url":""}]},{"id":"s8-77","number":77,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"لماذا عبّر عن وسوسة الشيطان بـ﴿رجز الشيطان﴾؟","answer":"أضيف الرجز إلى الشيطان لأنه وسوسته وتخويفه وتكديره الذي أراد به إضعافهم، فطهرهم الله منه بالماء واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص650–653.","url":""}]},{"id":"s8-78","number":78,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"ما الصورة في ﴿وليربط على قلوبكم﴾؟","answer":"في ﴿يربط على قلوبكم﴾ استعارة لتثبيت القلوب ومنعها من الاضطراب، كأن عليها رباطًا يشدها فلا تتفلت من الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص652–655.","url":""}]},{"id":"s8-79","number":79,"surah":8,"verses":[11],"verseLabel":"الأنفال: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿ويثبت به الأقدام﴾، فجعل الماء مثبتًا للأقدام؟","answer":"كان المطر يلبد الرمل فيثبت عليه المشي، فجعل الماء سببًا حسيًا لثبات الأقدام، مع ما أورثه من ثبات معنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص654–656.","url":""}]},{"id":"s8-80","number":80,"surah":8,"verses":[12],"verseLabel":"الأنفال: 12","question":"ما سرّ التعبير في قوله تعالى للملائكة: ﴿أني معكم﴾ قبل أمرهم بتثبيت المؤمنين؟","answer":"بدأ بإعلام الملائكة بمعيته؛ تثبيتًا لهم وبيانًا أن ما يفعلونه مؤيد بعون الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص657–660.","url":""}]},{"id":"s8-81","number":81,"surah":8,"verses":[12],"verseLabel":"الأنفال: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿فثبتوا الذين آمنوا﴾، دون أن يقال: قاتلوا معهم؟","answer":"أمرهم بتثبيت المؤمنين لأن وظيفتهم في المقام تقوية القلوب بالبشارة والمعونة، أما حقيقة النصر والقتل فمن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص659–661.","url":""}]},{"id":"s8-82","number":82,"surah":8,"verses":[12],"verseLabel":"الأنفال: 12","question":"لماذا عبّر بالمستقبل: ﴿سألقي في قلوب الذين كفروا الرعب﴾؟","answer":"السين في ﴿سألقي﴾ تعد بإلقاء الرعب عقب تثبيت المؤمنين، فتقابل بين الأثرين وتستحضر قرب وقوعهما في المعركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص660–663.","url":""}]},{"id":"s8-83","number":83,"surah":8,"verses":[12],"verseLabel":"الأنفال: 12","question":"ما الصورة في ﴿ألقي في قلوب الذين كفروا الرعب﴾؟","answer":"صُوّر الرعب شيئًا يلقى في القلوب فيستقر فيها ويملؤها، وهو تجسيم لقوة أثره واستيلائه على باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص661–664.","url":""}]},{"id":"s8-84","number":84,"surah":8,"verses":[12],"verseLabel":"الأنفال: 12","question":"لماذا خُصّ الضرب بـ﴿فوق الأعناق﴾ و﴿كل بنان﴾؟","answer":"فوق الأعناق موضع الإجهاز وقطع الرؤوس، والبنان أطراف الأعضاء التي بها حمل السلاح والدفاع؛ فضربهما يعطل الحياة أو القدرة على القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص664–668.","url":""}]},{"id":"s8-85","number":85,"surah":8,"verses":[13],"verseLabel":"الأنفال: 13","question":"لماذا عُبر عن عداوتهم بـ﴿شاقوا الله ورسوله﴾؟","answer":"المشاقة اتخاذ شق مقابل لشق آخر؛ فصورت مخالفتهم لله ورسوله كوقوفهم في جانب معادٍ منفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص669–672.","url":""}]},{"id":"s8-86","number":86,"surah":8,"verses":[13],"verseLabel":"الأنفال: 13","question":"لماذا أعاد الشرط نفسه: ﴿ومن يشاقق الله ورسوله﴾ بعد تقرير فعلهم؟","answer":"أُعيد الشرط لتعميم الحكم بعد وصف الواقعة؛ فما نزل بهم ليس خاصًا بهم، بل سنة في كل من يشاقق الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص672–675.","url":""}]},{"id":"s8-87","number":87,"surah":8,"verses":[13],"verseLabel":"الأنفال: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿شديد العقاب﴾ لا «شديد العذاب»؟","answer":"العقاب جزاء على الجرم ومؤاخذة به، وهو أنسب لسياق المشاقة والإجرام من لفظ العذاب الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص675–678.","url":""}]},{"id":"s8-88","number":88,"surah":8,"verses":[13],"verseLabel":"الأنفال: 13","question":"ما مناسبة إظهار اسم الله في جواب الشرط؟","answer":"أُظهر اسم الله في ﴿فإن الله شديد العقاب﴾ لتربية المهابة وتقرير أن شدة العقاب ثابتة له، ولئلا يضعف المعنى بضمير يعود على المذكورين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص678–681.","url":""}]},{"id":"s8-89","number":89,"surah":8,"verses":[14],"verseLabel":"الأنفال: 14","question":"لماذا أُشير إلى العقاب بقوله: ﴿ذلكم فذوقوه﴾؟","answer":"اسم الإشارة يحضر العقاب المشاهد يوم بدر ويعظمه، ثم فرعت عليه صيغة الذوق التي تواجههم بما نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص682–684.","url":""}]},{"id":"s8-90","number":90,"surah":8,"verses":[14],"verseLabel":"الأنفال: 14","question":"لماذا استعير الذوق للعذاب؟","answer":"استعير الذوق لإدراك العذاب؛ لأنه إحساس مباشر يجده صاحبه، وفيه تصوير لشدة مباشرته وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص684–686.","url":""}]},{"id":"s8-91","number":91,"surah":8,"verses":[14],"verseLabel":"الأنفال: 14","question":"لماذا انتقل من الخطاب في ﴿فذوقوه﴾ إلى الغيبة في ﴿وأن للكافرين عذاب النار﴾؟","answer":"واجههم أولًا بعذاب الدنيا الواقع: ﴿فذوقوه﴾، ثم عمم الحكم باسم ﴿الكافرين﴾ في عذاب الآخرة؛ فانتقل من الحاضرين إلى جنسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص686–688.","url":""}]},{"id":"s8-92","number":92,"surah":8,"verses":[15],"verseLabel":"الأنفال: 15","question":"لماذا ناداهم بوصف الإيمان قبل النهي عن الفرار؟","answer":"النداء بوصف الإيمان يستنهض مقتضاه في الثبات والطاعة، ويشعر بأن الفرار لا يليق بمن تحقق بهذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص689–692.","url":""}]},{"id":"s8-93","number":93,"surah":8,"verses":[15],"verseLabel":"الأنفال: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا لقيتم الذين كفروا زحفًا﴾، فجعل «زحفًا» حالًا؟","answer":"﴿زحفًا﴾ حال تصور الجيشين متقاربين يزحف بعضهما إلى بعض في جماعة، وهو الموطن الذي يحرم فيه التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص691–694.","url":""}]},{"id":"s8-94","number":94,"surah":8,"verses":[15],"verseLabel":"الأنفال: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تولوهم الأدبار﴾، دون أن يقال: لا تهربوا؟","answer":"﴿لا تولوهم الأدبار﴾ كناية مصورة عن الفرار؛ إذ تعرض هيئة المنهزم الذي يجعل ظهره لعدوه، وهي أبلغ في التقبيح من «لا تهربوا».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص693–696.","url":""}]},{"id":"s8-95","number":95,"surah":8,"verses":[16],"verseLabel":"الأنفال: 16","question":"لماذا استثنى ﴿متحرفًا لقتال أو متحيزًا إلى فئة﴾ من التولي؟","answer":"التحرف خطة داخل القتال، والتحيز انتقال إلى جماعة يستمد بها المقاتل؛ فكلاهما حركة لمصلحة القتال لا فرارًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص696–699.","url":""}]},{"id":"s8-96","number":96,"surah":8,"verses":[16],"verseLabel":"الأنفال: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد باء بغضب من الله﴾؟","answer":"﴿باء بغضب﴾ تفيد رجع متحملًا للغضب ملازمًا له، فكأنه عاد بحمل ثقيل استحقه بفراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص698–700.","url":""}]},{"id":"s8-97","number":97,"surah":8,"verses":[16],"verseLabel":"الأنفال: 16","question":"لماذا ختم بـ﴿وبئس المصير﴾ بعد ذكر المأوى؟","answer":"ذُكر المأوى في ﴿مأواه جهنم﴾ ثم ذُمّت جهة الرجوع بـ﴿وبئس المصير﴾؛ فجمع بيان المكان وتقبيح العاقبة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص700–701.","url":""}]},{"id":"s8-98","number":98,"surah":8,"verses":[17],"verseLabel":"الأنفال: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿فلم تقتلوهم ولكن الله قتلهم﴾ مع أن المؤمنين باشروا القتل؟","answer":"نُفي استقلال المؤمنين بالقتل وأثبت لله لأنه هو الذي أقدرهم وأمدهم وألقى الرعب؛ فالمباشرة منهم، والتقدير والتأثير الحاسم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص702–705.","url":""}]},{"id":"s8-99","number":99,"surah":8,"verses":[17],"verseLabel":"الأنفال: 17","question":"لماذا انتقل من الجمع في القتل إلى خطاب النبي منفردًا في الرمي؟","answer":"جُمع خطاب القتل لاشتراك المؤمنين فيه، وأُفرد الرمي لاختصاص النبي ﷺ بمباشرته يوم بدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص704–707.","url":""}]},{"id":"s8-100","number":100,"surah":8,"verses":[17],"verseLabel":"الأنفال: 17","question":"لماذا كرر: ﴿وما رميت إذ رميت﴾، فأثبت الرمي ونفاه في جملة واحدة؟","answer":"أثبت الرمي للنبي ﷺ من جهة المباشرة، ونفى عنه بلوغ أثره الخارق، ثم أثبته لله من جهة الإيصال والتأثير؛ فلا تناقض لاختلاف الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص706–709.","url":""}]},{"id":"s8-101","number":101,"surah":8,"verses":[17],"verseLabel":"الأنفال: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وليبلي المؤمنين منه بلاء حسنًا﴾، وسمّى النصر بلاء؟","answer":"البلاء في أصل معناه الاختبار، ويكون بالخير كما يكون بالشر؛ فسُمّي النصر والغنيمة بلاءً حسنًا لأنهما نعمة واختبار يظهر به شكر المؤمنين وحسن طاعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص709–712.","url":""}]},{"id":"s8-102","number":102,"surah":8,"verses":[17],"verseLabel":"الأنفال: 17","question":"ما مناسبة الختم بـ﴿إن الله سميع عليم﴾؟","answer":"ناسب ﴿سميع عليم﴾ ما في الموقف من دعاء المؤمنين وأقوالهم ونياتهم؛ فهو سميع لاستغاثتهم، عليم بإيمانهم واستعدادهم للابتلاء الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص712–716.","url":""}]},{"id":"s8-103","number":103,"surah":8,"verses":[18],"verseLabel":"الأنفال: 18","question":"لماذا افتتحت الآية باسم الإشارة: ﴿ذلكم﴾؟","answer":"يشير ﴿ذلكم﴾ إلى ما تقدم من القتل والرمي والنصر والبلاء الحسن، فيجمعه ويحضره أمام المخاطبين تمهيدًا لبيان أنه من تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص717–719.","url":""}]},{"id":"s8-104","number":104,"surah":8,"verses":[18],"verseLabel":"الأنفال: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿موهن كيد الكافرين﴾، دون أن يقال: مبطل كيدهم؟","answer":"الوهن إضعاف الشيء بعد قوته؛ فالتعبير يصور كيدهم باقياً في الظاهر لكن الله يسلبه القوة والتأثير حتى ينهار، وهو أدق من مجرد إبطاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص719–721.","url":""}]},{"id":"s8-105","number":105,"surah":8,"verses":[18],"verseLabel":"الأنفال: 18","question":"لماذا أظهر ﴿الكافرين﴾، ولم يقل: كيدهم؟","answer":"أُظهر وصف ﴿الكافرين﴾ بدل الضمير لبيان أن كفرهم علة توهين كيدهم، ولتعميم السنة في كل كيد يصدر عن أهل الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص721–723.","url":""}]},{"id":"s8-106","number":106,"surah":8,"verses":[19],"verseLabel":"الأنفال: 19","question":"لماذا عبّر عن دعائهم بالحكم بـ﴿إن تستفتحوا﴾؟","answer":"الاستفتاح طلب الفتح، أي الحكم والفصل بالنصر؛ وقد دعا المشركون أن ينصر الله أهدى الطائفتين، فجاء اللفظ من جنس طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص724–728.","url":""}]},{"id":"s8-107","number":107,"surah":8,"verses":[19],"verseLabel":"الأنفال: 19","question":"ما سرّ التعبير التهكمي في قوله تعالى للمشركين: ﴿فقد جاءكم الفتح﴾، مع أن ما جاءهم كان الهزيمة؟","answer":"في ﴿فقد جاءكم الفتح﴾ تهكم بالمشركين؛ فقد طلبوا الحكم فجاءهم الفصل الذي تمنوه، لكنه ظهر به بطلانهم وكانت نتيجته هزيمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص728–731.","url":""}]},{"id":"s8-108","number":108,"surah":8,"verses":[19],"verseLabel":"الأنفال: 19","question":"لماذا تكرر الشرط في ﴿وإن تنتهوا فهو خير لكم وإن تعودوا نعد﴾؟","answer":"الشرط الأول يفتح لهم باب الانتهاء وما فيه من خير، والثاني يحذرهم من العودة إلى القتال بعودة العقوبة؛ فلكل شرط جهة وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص731–734.","url":""}]},{"id":"s8-109","number":109,"surah":8,"verses":[19],"verseLabel":"الأنفال: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿ولن تغني عنكم فئتكم شيئًا ولو كثرت﴾؟","answer":"نُفي عن فئتهم كل إغناء بـ﴿لن﴾ و﴿شيئًا﴾، ثم أُلغي أثر كثرتها؛ فاجتمع تأكيد النفي والعموم لقطع اغترارهم بالعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص733–735.","url":""}]},{"id":"s8-110","number":110,"surah":8,"verses":[19],"verseLabel":"الأنفال: 19","question":"ما مناسبة الختم بـ﴿وأن الله مع المؤمنين﴾؟","answer":"معية الله للمؤمنين هي علة نصرهم وعدم إغناء فئة الكافرين؛ فهي معية تأييد وحفظ، وبها ترجح الفئة المؤمنة وإن قلت.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص735–736.","url":""}]},{"id":"s8-111","number":111,"surah":8,"verses":[20],"verseLabel":"الأنفال: 20","question":"لماذا تكرر الأمر بطاعة الله ورسوله بعد وروده في أول السورة؟","answer":"تكرر الأمر بالطاعة هنا بعد عرض وقائع النصر؛ لينقلهم من مشاهدة التأييد إلى واجب الثبات على الأمر، ويحذرهم من التولي عند سماعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص737–739.","url":""}]},{"id":"s8-112","number":112,"surah":8,"verses":[20],"verseLabel":"الأنفال: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تولوا عنه﴾ فأفرد الضمير بعد ذكر الله والرسول؟","answer":"يعود الضمير في ﴿عنه﴾ إلى الرسول ﷺ؛ لأن التولي عنه عند تبليغه هو تولٍّ عن أمر الله، وقد أفرد لتعيين جهة السماع والتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص739–742.","url":""}]},{"id":"s8-113","number":113,"surah":8,"verses":[20],"verseLabel":"الأنفال: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنتم تسمعون﴾، دون أن يقال: وأنتم تعلمون؟","answer":"السماع هو الباب المباشر لتلقي أمر الرسول في هذا المقام، والمراد سماع القبول والإجابة؛ فهو أخص من مجرد العلم الذي قد لا يصحبه امتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص742–745.","url":""}]},{"id":"s8-114","number":114,"surah":8,"verses":[21],"verseLabel":"الأنفال: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون﴾؟","answer":"النهي يشبه حال من يدّعي السماع بلسانه ثم لا يقبل ولا يعمل؛ فالغرض التحذير من أن يكون سماع المؤمنين صوتًا بلا استجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص746–748.","url":""}]},{"id":"s8-115","number":115,"surah":8,"verses":[21],"verseLabel":"الأنفال: 21","question":"لماذا نفى السماع عنهم بعد إثبات قولهم: ﴿سمعنا﴾؟","answer":"أثبتوا لأنفسهم سماع الأذن بقولهم ﴿سمعنا﴾، ونُفي عنهم سماع التدبر والقبول؛ فلا تعارض لاختلاف حقيقة السماع في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص748–750.","url":""}]},{"id":"s8-116","number":116,"surah":8,"verses":[22],"verseLabel":"الأنفال: 22","question":"لماذا سمّى الكافرين ﴿شر الدواب﴾ مع أنهم بشر؟","answer":"سُمّوا شر الدواب لأنهم عطلوا السمع والنطق والعقل التي ميز بها الإنسان، فصار الحيوان الجاري على فطرته خيرًا ممن أبطل أدوات الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص751–753.","url":""}]},{"id":"s8-117","number":117,"surah":8,"verses":[22],"verseLabel":"الأنفال: 22","question":"لماذا جمع بين ﴿الصم البكم﴾ ثم قال: ﴿الذين لا يعقلون﴾؟","answer":"الصمم يصور امتناعهم عن تلقي الحق، والبكم امتناعهم عن النطق به، ثم كشف ﴿لا يعقلون﴾ أصل الداء: تعطيل العقل الذي ينتفع بالمسموع ويهدي القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص753–755.","url":""}]},{"id":"s8-118","number":118,"surah":8,"verses":[22],"verseLabel":"الأنفال: 22","question":"ما دلالة تعريف ﴿الدواب﴾ و﴿الصم البكم﴾ في قوله تعالى: ﴿إن شر الدواب عند الله الصم البكم﴾؟","answer":"تعريف ﴿الدواب﴾ للاستغراق في الجنس الذي يدب على الأرض، أما ﴿الصم البكم﴾ فخبران معرفان بـ«أل» يحددان شر هذا الجنس؛ ففرض التنكير في السؤال غير دقيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص755–757.","url":""}]},{"id":"s8-119","number":119,"surah":8,"verses":[23],"verseLabel":"الأنفال: 23","question":"كيف يجتمع قوله: ﴿ولو علم الله فيهم خيرًا لأسمعهم﴾ مع أنهم كانوا يسمعون القرآن؟","answer":"المثبت لهم سماع الصوت، والمنفي سماع القبول والفهم النافع؛ فلو علم الله في استعدادهم خيرًا لوهبهم إسماعًا يثمر هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص758–761.","url":""}]},{"id":"s8-120","number":120,"surah":8,"verses":[23],"verseLabel":"الأنفال: 23","question":"لماذا كرر الإِسماع: ﴿ولو أسمعهم لتولوا﴾ بعد نفي الخير؟","answer":"الأول ﴿لأسمعهم﴾ إسماع تفهيم وقبول لو وجد فيهم خير، والثاني فرض إسماعهم مع فساد استعدادهم؛ ونتيجته أنهم يتولون مصرين على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص761–764.","url":""}]},{"id":"s8-121","number":121,"surah":8,"verses":[23],"verseLabel":"الأنفال: 23","question":"لماذا ختم بـ﴿وهم معرضون﴾ بعد فعل التولي؟","answer":"التولي قد يقع لسبب عارض، أما ﴿وهم معرضون﴾ فيثبت أن الإعراض صفة راسخة فيهم؛ فجمع بين الفعل الظاهر والدافع الباطن الملازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص764–766.","url":""}]},{"id":"s8-122","number":122,"surah":8,"verses":[24],"verseLabel":"الأنفال: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿استجيبوا لله وللرسول﴾، دون أن يقال: أطيعوا كما سبق؟","answer":"الاستجابة قبول الدعوة بسرعة وانقياد، وهي أنسب لذكر داعٍ يدعوهم إلى ما يحييهم؛ أما الطاعة فأعم في امتثال الأوامر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص767–770.","url":""}]},{"id":"s8-123","number":123,"surah":8,"verses":[24],"verseLabel":"الأنفال: 24","question":"لماذا أفرد الضمير في ﴿إذا دعاكم﴾ بعد ذكر الله والرسول؟","answer":"الضمير في ﴿دعاكم﴾ للرسول ﷺ؛ لأنه الذي يباشر الدعوة، ودعوته إلى وحي الله دعوة لله، ولذلك سبقت الاستجابة لهما معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص769–772.","url":""}]},{"id":"s8-124","number":124,"surah":8,"verses":[24],"verseLabel":"الأنفال: 24","question":"لماذا وصف الوحي والتكليف بأنه ﴿لما يحييكم﴾؟","answer":"شُبه الوحي والإيمان بالحياة؛ لأنهما يخرجان العقل والقلب من موت الجهل والكفر، ويصلحان حياة الفرد والجماعة في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص771–774.","url":""}]},{"id":"s8-125","number":125,"surah":8,"verses":[24],"verseLabel":"الأنفال: 24","question":"ما الصورة في قوله: ﴿أن الله يحول بين المرء وقلبه﴾؟","answer":"التعبير يقرر تمام سلطان الله على القلب؛ فهو أقرب إلى الإنسان من إرادته، يقلب قلبه ويمنعه مما يشاء، فيحث على المبادرة إلى الاستجابة قبل الحيلولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص774–778.","url":""}]},{"id":"s8-126","number":126,"surah":8,"verses":[24],"verseLabel":"الأنفال: 24","question":"لماذا اختير لفظ ﴿المرء﴾ لا «الإنسان»؟","answer":"﴿المرء﴾ يدل على الشخص من حيث ذاته وشخصيته المكلفة، وهو أنسب بالمقابلة الدقيقة بين الإنسان وقلبه من الاسم العام ﴿الإنسان﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–779.","url":""}]},{"id":"s8-127","number":127,"surah":8,"verses":[24],"verseLabel":"الأنفال: 24","question":"لماذا ختم بـ﴿وأنه إليه تحشرون﴾؟","answer":"ذكر الحشر يؤكد وجوب المبادرة إلى الاستجابة؛ فإلى الله مرجعهم وحسابهم، ولا مهرب ممن يملك القلوب والمصير جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص779–781.","url":""}]},{"id":"s8-128","number":128,"surah":8,"verses":[25],"verseLabel":"الأنفال: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة﴾، مع أن الجزاء فردي؟","answer":"الفتنة العامة قد تنشأ من سكوت الجماعة عن الظلم، فإذا نزلت آثارها لم تقف عند المباشرين؛ أما الجزاء الأخروي فكل نفس مؤاخذة بعملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص782–785.","url":""}]},{"id":"s8-129","number":129,"surah":8,"verses":[25],"verseLabel":"الأنفال: 25","question":"لماذا جيء بنون التوكيد في ﴿لا تصيبن﴾؟","answer":"نون التوكيد تشدد التحذير من وقوع فتنة متعدية، وتصور إصابتها المحققة إذا تُرك الظلم بلا إنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص784–787.","url":""}]},{"id":"s8-130","number":130,"surah":8,"verses":[25],"verseLabel":"الأنفال: 25","question":"لماذا خُتمت بـ﴿واعلموا أن الله شديد العقاب﴾؟","answer":"ناسب ﴿شديد العقاب﴾ التحذير من فتنة عامة؛ ليعلموا أن ترك أسبابها والتهاون في دفع الظلم يعرضهم لعقاب شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص787–789.","url":""}]},{"id":"s8-131","number":131,"surah":8,"verses":[26],"verseLabel":"الأنفال: 26","question":"لماذا أمرهم بتذكر حال الضعف: ﴿واذكروا إذ أنتم قليل﴾ عقب التحذير من الفتنة؟","answer":"ذُكّروا بضعفهم السابق ليحذروا التنازع الذي يردهم إلى أسبابه، وليشكروا نعمة الإيواء والنصر والرزق فلا يخونوا مقتضى الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص790–793.","url":""}]},{"id":"s8-132","number":132,"surah":8,"verses":[26],"verseLabel":"الأنفال: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿مستضعفون في الأرض﴾، دون أن يقال: ضعفاء؟","answer":"﴿مستضعفون﴾ تدل على أن غيرهم كان يتعمد إضعافهم وقهرهم، لا أنهم ضعفاء في ذواتهم؛ ولذلك هي أدق من «ضعفاء».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص792–795.","url":""}]},{"id":"s8-133","number":133,"surah":8,"verses":[26],"verseLabel":"الأنفال: 26","question":"لماذا عبّر بـ﴿يتخطفكم الناس﴾؟","answer":"الخطف أخذ سريع مباغت؛ وصيغة ﴿يتخطفكم﴾ تصور تكرر تربص الناس بهم وسرعة استلابهم لولا حفظ الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص794–797.","url":""}]},{"id":"s8-134","number":134,"surah":8,"verses":[26],"verseLabel":"الأنفال: 26","question":"لماذا حُذف متعلق الإيواء في ﴿فآواكم﴾، فلم يقل: إلى المدينة؟","answer":"حُذف متعلق الإيواء لتتسع المنة لكل ما آواهم الله إليه من المدينة والأمن وجماعة الأنصار، ولأن المقصود نفس الانتقال من الخوف إلى المأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص797–802.","url":""}]},{"id":"s8-135","number":135,"surah":8,"verses":[26],"verseLabel":"الأنفال: 26","question":"لماذا رتّب: ﴿فآواكم وأيدكم بنصره ورزقكم من الطيبات﴾؟","answer":"بدأ بالإيواء لأنه أمن المكان، ثم التأييد بالنصر لأنه أمن من العدو، ثم الرزق لأنه تمام استقرار الحياة؛ فترتيب النعم جارٍ من دفع الخوف إلى كمال العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص800–804.","url":""}]},{"id":"s8-136","number":136,"surah":8,"verses":[27],"verseLabel":"الأنفال: 27","question":"لماذا سمّى مخالفة أمر الله ورسوله ﴿خيانة﴾؟","answer":"الخيانة نقض العهد في السر وإنقاص الحق؛ فمخالفة أمر الله ورسوله بعد الالتزام بالإيمان نقض للأمانة التي حملها المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص10–13.","url":""}]},{"id":"s8-137","number":137,"surah":8,"verses":[27],"verseLabel":"الأنفال: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وتخونوا أماناتكم﴾، فعطف الخيانة على الخيانة؟","answer":"الخيانة الأولى تتعلق بحق الله ورسوله في الطاعة، والثانية بحقوق الأمانات المتعددة بين الناس؛ وعطفها يبين تلازم الحقين مع اختلاف متعلقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص13–16.","url":""}]},{"id":"s8-138","number":138,"surah":8,"verses":[27],"verseLabel":"الأنفال: 27","question":"لماذا جمع ﴿أماناتكم﴾ ولم يفردها؟","answer":"جُمعت الأمانات لتعدد ما يؤتمن عليه الإنسان من دين وتكاليف وأسرار وأموال وحقوق، ولكثرة أصحابها ومتعلقاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص16–19.","url":""}]},{"id":"s8-139","number":139,"surah":8,"verses":[27],"verseLabel":"الأنفال: 27","question":"لماذا ختم بـ﴿وأنتم تعلمون﴾؟","answer":"﴿وأنتم تعلمون﴾ يقيد النهي بالخيانة المتعمدة؛ فالعلم بالعهد وبكون الفعل خيانة يزيد قبحه ومسؤوليته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص19–21.","url":""}]},{"id":"s8-140","number":140,"surah":8,"verses":[28],"verseLabel":"الأنفال: 28","question":"لماذا سمّى الأموال والأولاد ﴿فتنة﴾ مع أنهما نعمة؟","answer":"الفتنة هي الاختبار الذي يكشف موقف الإنسان؛ فالمال والولد نعمة في ذاتهما، وقد يصيران سببًا للانشغال عن الطاعة أو الوقوع في الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص22–25.","url":""}]},{"id":"s8-141","number":141,"surah":8,"verses":[28],"verseLabel":"الأنفال: 28","question":"ما سرّ تقديم الأموال على الأولاد؟","answer":"قُدمت الأموال لأنها أعم تعلقًا بالمصالح وأشد مباشرة لأسباب الخيانة والإنفاق والنزاع في سياق السورة، ولأن الافتتان بها يتكرر في حياة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص24–27.","url":""}]},{"id":"s8-142","number":142,"surah":8,"verses":[28],"verseLabel":"الأنفال: 28","question":"لماذا قابل الفتنة بقوله: ﴿وأن الله عنده أجر عظيم﴾؟","answer":"قوبل نفع المال والولد العاجل بالأجر العظيم عند الله؛ ليختار المؤمن الباقي الأعظم، فلا تحمله محبتهما على الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص27–29.","url":""}]},{"id":"s8-143","number":143,"surah":8,"verses":[29],"verseLabel":"الأنفال: 29","question":"لماذا كرر شرط التقوى بعد قوله في أول السورة: ﴿فاتقوا الله﴾؟","answer":"الأمر الأول بالتقوى جاء عقب النزاع في الأنفال، وهنا جُعلت التقوى شرطًا لمنحة الفرقان والتكفير والمغفرة؛ فتكرر لاختلاف المقام والثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص30–32.","url":""}]},{"id":"s8-144","number":144,"surah":8,"verses":[29],"verseLabel":"الأنفال: 29","question":"لماذا سمّى البصيرة الفاصلة ﴿فرقانًا﴾؟","answer":"الفرقان ما يفرق به بين الحق والباطل والهدى والضلال؛ فسمّيت البصيرة والنصرة فرقانًا لما تمنحه التقوى من تمييز وفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص32–35.","url":""}]},{"id":"s8-145","number":145,"surah":8,"verses":[29],"verseLabel":"الأنفال: 29","question":"لماذا جمع بين تكفير السيئات والمغفرة؟","answer":"تكفير السيئات سترها ومحو أثرها، والمغفرة وقاية العبد من المؤاخذة بها؛ فالجمع يفيد إزالة الذنب وآثاره وإتمام العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص35–38.","url":""}]},{"id":"s8-146","number":146,"surah":8,"verses":[29],"verseLabel":"الأنفال: 29","question":"ما مناسبة الختم بـ﴿والله ذو الفضل العظيم﴾؟","answer":"خُتم بذي الفضل العظيم لأن الفرقان والتكفير والمغفرة عطايا زائدة من فضل الله، لا ثمناً تستقل التقوى باستحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص38–39.","url":""}]},{"id":"s8-147","number":147,"surah":8,"verses":[30],"verseLabel":"الأنفال: 30","question":"لماذا عُبر عن مؤامرة قريش بالمضارع: ﴿وإذ يمكر بك﴾؟","answer":"المضارع ﴿يمكر﴾ يستحضر المؤامرة الماضية كأنها حاضرة، ويصور تتابع تدبيرهم وتنوع حيلهم حول النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص40–43.","url":""}]},{"id":"s8-148","number":148,"surah":8,"verses":[30],"verseLabel":"الأنفال: 30","question":"لماذا رتبت خياراتهم: ﴿ليثبتوك أو يقتلوك أو يخرجوك﴾؟","answer":"رتبت خياراتهم من الحبس الذي يمنع الدعوة، إلى القتل الذي يزيل صاحبها، إلى الإخراج الذي يبعده؛ وهي وجوه مكرهم المتداولة في المشورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص43–47.","url":""}]},{"id":"s8-149","number":149,"surah":8,"verses":[30],"verseLabel":"الأنفال: 30","question":"لماذا كرر ﴿ويمكرون ويمكر الله﴾؟","answer":"تكرار ﴿يمكرون ويمكر الله﴾ للمشاكلة والمقابلة؛ فتدبيرهم خفي لإبطال الحق، وتدبير الله يبطل كيدهم من حيث لا يشعرون، وليس الفعلان متماثلين في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص47–50.","url":""}]},{"id":"s8-150","number":150,"surah":8,"verses":[30],"verseLabel":"الأنفال: 30","question":"لماذا خُتم بـ﴿والله خير الماكرين﴾؟","answer":"﴿خير الماكرين﴾ تقرر أن تدبير الله غالب محكم يحيط بحيلهم ويردها عليهم، فناسبت ختام مشهد المؤامرة وإفشالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص50–52.","url":""}]},{"id":"s8-151","number":151,"surah":8,"verses":[31],"verseLabel":"الأنفال: 31","question":"ما دلالة قولهم: ﴿قد سمعنا﴾، ولم يقولوا: فهمنا؟","answer":"قولهم ﴿قد سمعنا﴾ ادعاء إحاطة بما تلي عليهم واستهانة به؛ أرادوا أن يصوروه شيئًا مألوفًا لا جديد فيه، لا أن يثبتوا فهمًا صحيحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص53–56.","url":""}]},{"id":"s8-152","number":152,"surah":8,"verses":[31],"verseLabel":"الأنفال: 31","question":"لماذا عبّروا عن القرآن بـ﴿أساطير الأولين﴾؟","answer":"الأساطير ما سطر من أخبار الأولين التي لا حقيقة لها في زعمهم؛ فوصفوا القرآن بها طعنًا في الوحي وفرارًا من حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص56–61.","url":""}]},{"id":"s8-153","number":153,"surah":8,"verses":[31],"verseLabel":"الأنفال: 31","question":"ما دلالة قولهم: ﴿لو نشاء لقلنا مثل هذا﴾ ولم يأتوا بمثله؟","answer":"علقوا الإتيان بالمثل على مشيئتهم ليزعموا القدرة مع ترك الفعل، لكن عجزهم العملي فضح الدعوى؛ فلم يأتوا بمثله مع قيام التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص61–65.","url":""}]},{"id":"s8-154","number":154,"surah":8,"verses":[32],"verseLabel":"الأنفال: 32","question":"ما دلالة قولهم: ﴿إن كان هذا هو الحق﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يفيد القصر في دعواهم: إن كان هذا القرآن هو الحق وحده؛ وجاء كلامهم على سبيل المكابرة والتشكيك لا طلب اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص66–69.","url":""}]},{"id":"s8-155","number":155,"surah":8,"verses":[32],"verseLabel":"الأنفال: 32","question":"لماذا طلبوا نزول الحجارة بدل أن يسألوا الهداية إن كان حقًا؟","answer":"طلبوا العذاب بدل الهداية مبالغة في الجحود والثقة بباطلهم؛ فقدموا المكابرة والتحدي على طلب النجاة لو ظهر الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص69–73.","url":""}]},{"id":"s8-156","number":156,"surah":8,"verses":[32],"verseLabel":"الأنفال: 32","question":"ما دلالة قولهم: ﴿فأمطر علينا حجارة من السماء﴾؟","answer":"خصوا الحجارة النازلة من السماء لأنها صورة للعذاب المستأصل المشهود في أخبار الأمم، وللمبالغة في تعجيل العقوبة التي تحدوا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص73–77.","url":""}]},{"id":"s8-157","number":157,"surah":8,"verses":[33],"verseLabel":"الأنفال: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليعذبهم وأنت فيهم﴾ بصيغة الجحود المؤكد؟","answer":"صيغة ﴿ما كان الله ليعذبهم﴾ أبلغ في النفي من «لا يعذبهم»؛ فهي تنفي ملاءمة العذاب لسنة الله ورسوله ﷺ بين أظهرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص78–82.","url":""}]},{"id":"s8-158","number":158,"surah":8,"verses":[33],"verseLabel":"الأنفال: 33","question":"لماذا انتقل من وجود النبي إلى الاستغفار: ﴿وما كان الله معذبهم وهم يستغفرون﴾؟","answer":"كان وجود الرسول ﷺ أمانًا مؤقتًا في حياته بينهم، والاستغفار أمانًا متجددًا يبقى بابه للأمة؛ فانتقل من المانع الخاص إلى السبب العام المستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص82–85.","url":""}]},{"id":"s8-159","number":159,"surah":8,"verses":[33],"verseLabel":"الأنفال: 33","question":"لماذا جاءت الأولى ﴿ليعذبهم﴾ والثانية ﴿معذبهم﴾؟","answer":"الفعل ﴿ليعذبهم﴾ مع لام الجحود يناسب نفي وقوع العذاب في حال وجود الرسول، واسم الفاعل ﴿معذبهم﴾ يصور ثبات انتفاء وصف التعذيب حال استغفارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص85–87.","url":""}]},{"id":"s8-160","number":160,"surah":8,"verses":[34],"verseLabel":"الأنفال: 34","question":"لماذا استدرك بقوله: ﴿وما لهم ألا يعذبهم الله﴾ بعد نفي العذاب؟","answer":"نفي العذاب مقيد بوجود الرسول والاستغفار، أما استحقاقهم له فثابت بسبب صدهم؛ فالاستدراك يفرق بين تأخير العذاب وانتفاء موجبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص88–92.","url":""}]},{"id":"s8-161","number":161,"surah":8,"verses":[34],"verseLabel":"الأنفال: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يصدون عن المسجد الحرام﴾ بالمضارع؟","answer":"المضارع ﴿يصدون﴾ يصور استمرارهم وتجدد منعهم الناس من المسجد الحرام، فكان الجرم قائمًا لا حادثة منقطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص92–96.","url":""}]},{"id":"s8-162","number":162,"surah":8,"verses":[34],"verseLabel":"الأنفال: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كانوا أولياءه﴾ ثم حصر الولاية في المتقين؟","answer":"نُفيت ولايتهم للبيت رغم دعواهم، ثم قُصرت ولايته على المتقين؛ لأن الولاية حقها الحفظ والتعظيم والطاعة، لا الصد والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص96–101.","url":""}]},{"id":"s8-163","number":163,"surah":8,"verses":[35],"verseLabel":"الأنفال: 35","question":"لماذا سمّى صفيرهم وتصفيقهم عند البيت ﴿صلاة﴾؟","answer":"سُمّي مكاؤهم وتصديتهم صلاة على سبيل التهكم أو بحسب زعمهم؛ إذ جعلوا الصفير والتصفيق بدل العبادة، فاشتد ذم فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص102–105.","url":""}]},{"id":"s8-164","number":164,"surah":8,"verses":[35],"verseLabel":"الأنفال: 35","question":"لماذا اختير ﴿مكاء وتصدية﴾ دون التصريح بالصفير والتصفيق؟","answer":"اختير الاسمان اللذان يسمّيان فعليهم في لغتهم لتجسيد هيئة عبادتهم الباطلة وإظهار خوائها، بدل الاكتفاء بوصف شارح لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص105–108.","url":""}]},{"id":"s8-165","number":165,"surah":8,"verses":[35],"verseLabel":"الأنفال: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا العذاب بما كنتم تكفرون﴾؟","answer":"الفاء تربط العذاب بكفرهم على التعقيب والسببية، و﴿ذوقوا﴾ تصور مباشرته لهم وتوبخهم، والمضارع ﴿تكفرون﴾ يصور تجدد كفرهم واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص108–111.","url":""}]},{"id":"s8-166","number":166,"surah":8,"verses":[39],"verseLabel":"الأنفال: 35؛ الأعراف: 39","question":"ما سرّ التعبير في قوله تعالى في الأنفال: ﴿بما كنتم تكفرون﴾، وفي الأعراف: ﴿بما كنتم تكسبون﴾؟","answer":"خصت الأنفال الكفر لأنه سبب العذاب الأبرز في هذا المقام، وجاء ﴿تكسبون﴾ في الأعراف لأن السياق جمع الكفر والإضلال والاستكبار؛ فناسبه اللفظ الأوسع لتعدد الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص110–111؛ ابن عاشور، التحرير والتنوير، 9/340.","url":""}]},{"id":"s8-167","number":167,"surah":8,"verses":[36,37],"verseLabel":"الأنفال: 36–37","question":"لماذا يكرر القرآن ﴿ينفقون أموالهم﴾ مع أن الإنفاق غالبًا في المال؟","answer":"ذُكر ﴿أموالهم﴾ لبيان أنهم يبذلون أعز ما يملكون باختيارهم في الصد عن سبيل الله، وللتنصيص على محل الإنفاق وتقبيح صرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص112–116.","url":""}]},{"id":"s8-168","number":168,"surah":8,"verses":[36,37],"verseLabel":"الأنفال: 36–37","question":"لماذا تحولت النفقة إلى ﴿حسرة عليهم﴾؟","answer":"تصير النفقة نفسها حسرة حين تذهب الأموال ولا تتحقق غايتهم، ثم يرونها سببًا لهزيمتهم وعقابهم؛ فتنقلب وسيلة القوة إلى ندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص116–122.","url":""}]},{"id":"s8-169","number":169,"surah":8,"verses":[36,37],"verseLabel":"الأنفال: 36–37","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم يغلبون﴾ بعد ﴿فستكون عليهم حسرة﴾؟","answer":"﴿ثم﴾ تفيد أن الحسرة لا تنهي العاقبة؛ فبعد فشل النفقة وتأخر النتيجة تأتي الهزيمة، وفي التراخي زيادة تهويل وانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص122–128.","url":""}]},{"id":"s8-170","number":170,"surah":8,"verses":[36,37],"verseLabel":"الأنفال: 36–37","question":"ما الصورة في قوله تعالى: ﴿ويجعل الخبيث بعضه على بعض فيركمه جميعًا﴾؟","answer":"يصور التعبير جمع الخبيث بعضه فوق بعض وتراكمه حتى يصير كتلة واحدة ملقاة في جهنم؛ وفي ذلك تصوير لاجتماع أهله وأموالهم الخبيثة في مصير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص128–134.","url":""}]},{"id":"s8-171","number":171,"surah":8,"verses":[38],"verseLabel":"الأنفال: 38","question":"لماذا وُجه خطاب الكافرين بصيغة الغائب: ﴿قل للذين كفروا إن ينتهوا﴾؟","answer":"جاءوا بصيغة الغائب تحقيرًا وإبعادًا لهم عن مقام الخطاب المباشر، وجعل الرسول ﷺ واسطة في تبليغ عرض المغفرة والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص136–141.","url":""}]},{"id":"s8-172","number":172,"surah":8,"verses":[38],"verseLabel":"الأنفال: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر لهم ما قد سلف﴾، ولم يعدد جرائمهم؟","answer":"﴿ما قد سلف﴾ تطوي جميع جرائمهم الماضية في عبارة جامعة؛ لتقرير سعة المغفرة إذا انتهوا، دون استحضار تفاصيل تقنطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص141–145.","url":""}]},{"id":"s8-173","number":173,"surah":8,"verses":[38],"verseLabel":"الأنفال: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد مضت سنة الأولين﴾ بدل التصريح بالعذاب؟","answer":"﴿سنة الأولين﴾ تحيل إلى قانون معلوم من هلاك المكذبين، فتغني عن تفصيل الوعيد وتجعله مؤيدًا بشواهد التاريخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص145–148.","url":""}]},{"id":"s8-174","number":174,"surah":8,"verses":[39,40],"verseLabel":"الأنفال: 39–40","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى لا تكون فتنة ويكون الدين كله لله﴾؟","answer":"غاية القتال إزالة الفتنة التي تصد عن الإيمان وإخلاص الدين لله؛ فالتعبير يحدد مقصد القتال الديني، لا إكراه القلوب على الاعتقاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص149–155.","url":""}]},{"id":"s8-175","number":175,"surah":8,"verses":[39,40],"verseLabel":"الأنفال: 39–40","question":"لماذا أفرد ﴿الدين﴾ ووصفه بـ﴿كله﴾؟","answer":"أُفرد ﴿الدين﴾ لأنه الملة والطاعة بوصفهما حقيقة واحدة، وأكد بـ﴿كله﴾ لنفي أن يبقى شيء من سلطان العبادة لغير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص155–160.","url":""}]},{"id":"s8-176","number":176,"surah":8,"verses":[39,40],"verseLabel":"الأنفال: 39–40","question":"لماذا ختم حال انتهائهم بـ﴿فإن الله بما يعملون بصير﴾؟","answer":"﴿بصير﴾ يناسب انتهاءهم الذي قد يخفى صدقه؛ فالله يرى أعمالهم وبواطنها، ويجازيهم على حقيقة ما يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص160–164.","url":""}]},{"id":"s8-177","number":177,"surah":8,"verses":[39,40],"verseLabel":"الأنفال: 39–40","question":"ما مناسبة قوله تعالى عند توليهم: ﴿فاعلموا أن الله مولاكم﴾؟","answer":"عند توليهم ثُبّت المؤمنون بأن الله مولاهم؛ فهو متولي نصرهم وتدبيرهم، فلا يضرهم إعراض العدو ما دام الله ناصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص164–167.","url":""}]},{"id":"s8-178","number":178,"surah":8,"verses":[41],"verseLabel":"الأنفال: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿واعلموا أنما غنمتم من شيء﴾، فجمع «ما» و«من شيء»؟","answer":"﴿ما﴾ تعم كل ما غنم، و﴿من شيء﴾ تؤكد هذا العموم حتى أدنى شيء؛ فلا يخرج من حكم الخمس قليل ولا كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص168–173.","url":""}]},{"id":"s8-179","number":179,"surah":8,"verses":[41],"verseLabel":"الأنفال: 41","question":"لماذا أعاد ﴿لله﴾ في الخمس مع أن المال كله لله؟","answer":"ذُكر ﴿لله﴾ افتتاحًا للتقسيم لإظهار أن الخمس محكوم بأمره ومصرفه، لا لأن لله سهمًا ينتفع به؛ فالمال كله له ملكًا وهذا تخصيص حكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص173–178.","url":""}]},{"id":"s8-180","number":180,"surah":8,"verses":[41],"verseLabel":"الأنفال: 41","question":"لماذا وصف يوم بدر بـ﴿يوم الفرقان يوم التقى الجمعان﴾؟","answer":"سمي بدر يوم الفرقان لأنه فصل بين الحق والباطل بالنصر، وفسره ﴿يوم التقى الجمعان﴾ بتعيين الواقعة التي ظهر فيها ذلك الفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص178–184.","url":""}]},{"id":"s8-181","number":181,"surah":8,"verses":[41],"verseLabel":"الأنفال: 41","question":"ما مناسبة الختم بـ﴿والله على كل شيء قدير﴾؟","answer":"القدرة الإلهية هي التي دبرت اللقاء والنصر وقسمة الغنيمة على غير توقع البشر؛ فختم الآية يرد الأمر كله إلى قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص184–192.","url":""}]},{"id":"s8-182","number":182,"surah":8,"verses":[42],"verseLabel":"الأنفال: 42","question":"لماذا كرر لفظ ﴿العدوة﴾ في ﴿العدوة الدنيا... العدوة القصوى﴾؟","answer":"أُعيدت ﴿العدوة﴾ مع كل وصف لتثبيت طرفي المشهد وتوضيح تقابلهما: المؤمنون في القريبة والمشركون في البعيدة، دون لبس في مرجع الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص193–197.","url":""}]},{"id":"s8-183","number":183,"surah":8,"verses":[42],"verseLabel":"الأنفال: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿والركب أسفل منكم﴾ بدل «العير»؟","answer":"﴿الركب﴾ يصور جماعة العير الراكبة المتحركة، وهو أنسب بالمشهد المكاني من اسم المال نفسه؛ و﴿أسفل﴾ يحدد موضعها من الجيشين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص197–200.","url":""}]},{"id":"s8-184","number":184,"surah":8,"verses":[42],"verseLabel":"الأنفال: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو تواعدتم لاختلفتم في الميعاد﴾؟","answer":"لو كان اللقاء عن موعد سابق لاختلف الفريقان في زمانه أو مكانه لما في النفوس من رهبة وعدم استعداد؛ لكن الله جمعهم بغير تواعد ليقضي أمرًا مقدرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص200–204.","url":""}]},{"id":"s8-185","number":185,"surah":8,"verses":[42],"verseLabel":"الأنفال: 42","question":"لماذا تكرر ﴿ليهلك من هلك عن بينة ويحيا من حي عن بينة﴾؟","answer":"قوبل الهلاك بالحياة لتصوير أثر البينة: من اختار الكفر بعد ظهورها فكأنه هلك، ومن آمن بها فقد حيي؛ وتكرار الصلة يثبت قيام الحجة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص204–206.","url":""}]},{"id":"s8-186","number":186,"surah":8,"verses":[43,44],"verseLabel":"الأنفال: 43–44","question":"لماذا أراهم الله للنبي في المنام ﴿قليلًا﴾؟","answer":"أُريهم النبي ﷺ قليلًا تثبيتًا للمؤمنين حتى يقدموا ولا يفشلوا، فجاءت الرؤيا صادقة من جهة ضعف قوة العدو وعاقبته لا مجرد عدده الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص207–212.","url":""}]},{"id":"s8-187","number":187,"surah":8,"verses":[43,44],"verseLabel":"الأنفال: 43–44","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو أراكهم كثيرًا لفشلتم ولتنازعتم﴾ مع شجاعة الصحابة؟","answer":"الآية تبين الطبيعة البشرية عند رؤية الكثرة المفاجئة؛ فإراءتهم كثيرًا كانت قد تفضي إلى الوهن واختلاف الرأي، وحفظهم الله من سببه مع ثبوت شجاعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص212–217.","url":""}]},{"id":"s8-188","number":188,"surah":8,"verses":[43,44],"verseLabel":"الأنفال: 43–44","question":"لماذا قلّل كل فريق في عين الآخر عند اللقاء؟","answer":"قلل المؤمنين في أعين المشركين ليقدموا فلا ينسحبوا، وقلل المشركين في أعين المؤمنين ليثبتوا؛ وبذلك تم اللقاء الذي قضاه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص217–222.","url":""}]},{"id":"s8-189","number":189,"surah":8,"verses":[43,44],"verseLabel":"الأنفال: 43–44","question":"لماذا ختم المشهد بـ﴿وإلى الله ترجع الأمور﴾؟","answer":"الخاتمة تكشف أن تدبير الرؤيا وتقليل الفريقين وإنفاذ اللقاء كلها أمور مردها إلى الله، فلا تستقل بها الأسباب الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص222–225.","url":""}]},{"id":"s8-190","number":190,"surah":8,"verses":[44],"verseLabel":"الأنفال: 44","question":"كيف يُجمع بين قوله تعالى في الأنفال: ﴿ويقللكم في أعينهم﴾، وقوله في آل عمران: ﴿يرونهم مثليهم رأي العين﴾؟","answer":"كان التقليل في أول اللقاء ليقدم الفريقان، ثم أُري المشركون المؤمنين مثليهم عند اشتداد القتال فداخلهم الرعب؛ فهما مرحلتان مختلفتان لا تعارض بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص607–609، تحت آل عمران 13.","url":""}]},{"id":"s8-191","number":191,"surah":8,"verses":[45],"verseLabel":"الأنفال: 45","question":"لماذا جمع بين الثبات وكثرة ذكر الله عند لقاء العدو؟","answer":"الثبات عمل الجوارح، وذكر الله قوة القلب؛ فجمعهما لأن ثبات الموقف لا يدوم إلا باستمداد اليقين والعون من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص226–229.","url":""}]},{"id":"s8-192","number":192,"surah":8,"verses":[45],"verseLabel":"الأنفال: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿اذكروا الله كثيرًا﴾ في أشد مواطن الانشغال؟","answer":"في شدة القتال يكثر الاضطراب والغفلة؛ فأُمروا بكثرة الذكر ليظل القلب متعلقًا بالله، مستمدًا منه الثبات والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص229–233.","url":""}]},{"id":"s8-193","number":193,"surah":8,"verses":[46,47],"verseLabel":"الأنفال: 46–47","question":"لماذا أعاد الأمر بالطاعة ثم نهى عن التنازع؟","answer":"أعيدت الطاعة هنا في أحكام مواجهة العدو، ثم خُص التنازع بالنهي لأنه أقرب أسباب الفشل وذهاب القوة في هذا الموطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص234–239.","url":""}]},{"id":"s8-194","number":194,"surah":8,"verses":[46,47],"verseLabel":"الأنفال: 46–47","question":"ما الصورة في ﴿فتفشلوا وتذهب ريحكم﴾؟","answer":"الريح كناية عن القوة والغلبة والهيبة؛ فالتنازع يبدد شوكة الجماعة واندفاعها كما تسكن الريح التي تدفع السفينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص239–244.","url":""}]},{"id":"s8-195","number":195,"surah":8,"verses":[46,47],"verseLabel":"الأنفال: 46–47","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكونوا كالذين خرجوا من ديارهم بطرًا ورئاء الناس﴾؟","answer":"جمع الوصف علل خروج المشركين: البطر الذي يحمل على الطغيان، والرياء الذي يطلب منزلة الناس، والصد الذي يقاوم سبيل الله؛ وهو نقيض إخلاص المؤمنين وثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص244–250.","url":""}]},{"id":"s8-196","number":196,"surah":8,"verses":[46,47],"verseLabel":"الأنفال: 46–47","question":"ما مناسبة الختم بـ﴿والله بما يعملون محيط﴾؟","answer":"الإحاطة أوسع من العلم المجرد؛ فهي تصور أن أعمالهم لا يفوت منها شيء قدرةً وعلمًا وجزاءً، فناسبت تهديد الخارجين بطرًا ورياءً وصدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص250–256.","url":""}]},{"id":"s8-197","number":197,"surah":8,"verses":[48],"verseLabel":"الأنفال: 48","question":"ما دلالة قول الشيطان: ﴿لا غالب لكم اليوم من الناس﴾؟","answer":"قال ذلك ليغريهم بالقتال ويؤمنهم من الخوف، فقيد نفي الغالب بـ﴿من الناس﴾ لأنه رأى أسبابًا بشرية فقط وغاب عنهم مدد الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص257–262.","url":""}]},{"id":"s8-198","number":198,"surah":8,"verses":[48],"verseLabel":"الأنفال: 48","question":"ما الصورة في ﴿فلما تراءت الفئتان نكص على عقبيه﴾؟","answer":"﴿نكص على عقبيه﴾ يصور رجوعًا سريعًا مذعورًا إلى الخلف بعد التقدم، فكأن حركته انقلبت على أثر رؤية الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص262–267.","url":""}]},{"id":"s8-199","number":199,"surah":8,"verses":[48],"verseLabel":"الأنفال: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أرى ما لا ترون﴾؟","answer":"أبهم ما يراه تهويلًا له؛ والمراد ما عاينه من الملائكة وأسباب التأييد التي لم يرها المشركون، فاتخذها ذريعة للتبرؤ والهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص267–273.","url":""}]},{"id":"s8-200","number":200,"surah":8,"verses":[49],"verseLabel":"الأنفال: 49","question":"لماذا وصف المنافقون المؤمنين بقولهم: ﴿غر هؤلاء دينهم﴾؟","answer":"نسبوا إقدام المؤمنين إلى غرور الدين لأنهم قاسوا الموقف بالعدد والعدة، ولم يدركوا حقيقة التوكل ووعد الله؛ فكشف قولهم مرض قلوبهم وقصور نظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص274–279.","url":""}]},{"id":"s8-201","number":201,"surah":8,"verses":[49],"verseLabel":"الأنفال: 49","question":"لماذا عقب بقوله: ﴿ومن يتوكل على الله فإن الله عزيز حكيم﴾؟","answer":"جاءت الجملة ردًا على زعم المنافقين أن الدين غر المؤمنين؛ فبيّنت أن اعتمادهم ليس غرورًا، بل توكل على عزيز لا يُغلب وحكيم يضع النصر في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص279–285.","url":""}]},{"id":"s8-202","number":202,"surah":8,"verses":[50,51],"verseLabel":"الأنفال: 50–51","question":"ما سرّ التعبير في قوله تعالى: ﴿يضربون وجوههم وأدبارهم﴾؟","answer":"جمع ضرب الوجوه والأدبار لإحاطة العذاب بهم من أمامهم وخلفهم، ولإذلالهم في الموضعين: الوجوه موضع الكرامة، والأدبار موضع الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص286–291.","url":""}]},{"id":"s8-203","number":203,"surah":8,"verses":[50,51],"verseLabel":"الأنفال: 50–51","question":"ما دلالة قولها: الملائكة: ﴿وذوقوا عذاب الحريق﴾؟","answer":"قول الملائكة ﴿ذوقوا﴾ توبيخ وتهديد يصور مباشرة العذاب وإحساسهم به، و﴿الحريق﴾ يخص عذاب النار الشديد الذي ينتظرهم بعد عذاب النزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص291–296.","url":""}]},{"id":"s8-204","number":204,"surah":8,"verses":[50,51],"verseLabel":"الأنفال: 50–51","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بما قدمت أيديكم﴾ مع أن الذنوب تصدر عن جوارح متعددة؟","answer":"نُسب التقديم إلى الأيدي لأنها أكثر الجوارح مباشرة للأعمال واكتسابًا لها، فغلبت في التعبير عن كل ما قدمه الإنسان من ذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص296–301.","url":""}]},{"id":"s8-205","number":205,"surah":8,"verses":[50,51],"verseLabel":"الأنفال: 50–51","question":"لماذا نفى الظلم بصيغة المبالغة: ﴿ليس بظلام للعبيد﴾؟","answer":"﴿ظلام﴾ على صيغة المبالغة تنفي أدنى ظلم مع كثرة العبيد وكثرة ما يجازون عليه؛ فلو وقع ظلم في واحد لتكرر بتكررهم، تعالى الله عن ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص299–301.","url":""}]},{"id":"s8-206","number":206,"surah":8,"verses":[52],"verseLabel":"الأنفال: 52","question":"لماذا شبه حالهم بـ﴿كدأب آل فرعون والذين من قبلهم﴾؟","answer":"شُبهت عادتهم بعادة آل فرعون ومن قبلهم في الكفر والتكذيب، لتقرير سنة واحدة: تمكين يتبعه أخذ بسبب الذنب حين يصر أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص302–306.","url":""}]},{"id":"s8-207","number":207,"surah":8,"verses":[52],"verseLabel":"الأنفال: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فأخذهم الله بذنوبهم﴾؟","answer":"الأخذ يدل على القبض بقوة وعدم الإفلات، وإسناده إلى الله يقرر أن العقوبة جاءت بذنوبهم عن قدرة وعدل لا مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص306–311.","url":""}]},{"id":"s8-208","number":208,"surah":8,"verses":[52,54],"verseLabel":"الأنفال: 52، 54","question":"ما سرّ اختلاف التعبير بين قوله تعالى أولًا: ﴿كفروا بآيات الله﴾، وقوله بعد آيتين: ﴿كذبوا بآيات ربهم﴾؟","answer":"ذُكر الكفر في الأولى لأنها تصف أصل جحودهم بالله وآياته، وذُكر التكذيب في الثانية لأنه موقفهم من آيات ربهم ورسله؛ فانتقل من الأصل الاعتقادي إلى صورة ظهوره في رد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص592–594، تحت آل عمران 11.","url":""}]},{"id":"s8-209","number":209,"surah":8,"verses":[52,54],"verseLabel":"الأنفال: 52، 54","question":"ما سرّ التعبير في قوله تعالى في الأولى: ﴿فأخذهم الله بذنوبهم﴾، وفي الثانية: ﴿فأهلكناهم بذنوبهم﴾؟","answer":"﴿فأخذهم الله﴾ أعم في العقوبة التي نالت الأمم، أما ﴿فأهلكناهم﴾ فصرحت بنهايتها، ثم خُص آل فرعون بالإغراق لبيان كيفية هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص593–594، تحت آل عمران 11.","url":""}]},{"id":"s8-210","number":210,"surah":8,"verses":[53],"verseLabel":"الأنفال: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿لم يك مغيرًا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم﴾؟","answer":"تقرر الآية سنة العدل: لا يسلب الله قومًا نعمة أنعمها عليهم حتى يبدلوا ما في نفوسهم من إيمان وشكر وطاعة إلى كفر وجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص312–316.","url":""}]},{"id":"s8-211","number":211,"surah":8,"verses":[53],"verseLabel":"الأنفال: 53","question":"لماذا حذف النون من ﴿يك﴾؟","answer":"حُذفت نون ﴿يكن﴾ لكثرة الاستعمال مع الجزم وسكون النون ووقوعها بين الكاف والميم، فكان الحذف تخفيفًا لا تغييرًا للمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص316–320.","url":""}]},{"id":"s8-212","number":212,"surah":8,"verses":[53],"verseLabel":"الأنفال: 53","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأنفال: ﴿ذلك بأن الله لم يك مغيرًا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم﴾، وقوله تعالى في الرعد: ﴿إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم﴾؟","answer":"آية الأنفال خاصة بتغيير نعمة سابقة إلى نقمة بسبب تغير أهلها، لذلك صرحت بـ﴿نعمة أنعمها﴾ وبالماضي ﴿لم يك﴾؛ وآية الرعد قاعدة عامة في أن الله لا يغير حال قوم، خيرًا أو شرًا، حتى يغيروا ما بأنفسهم.","sources":[{"label":"موسوعة القرآن، تفاسير الأنفال: 53 والرعد: 11، https://quranpedia.net/tafsir/al-anfal/53 وhttps://quranpedia.net/tafsir/ar-rad/11.","url":""}]},{"id":"s8-213","number":213,"surah":8,"verses":[54],"verseLabel":"الأنفال: 54","question":"لماذا كرر تشبيههم بآل فرعون بعد وروده في الآية 52؟","answer":"الأول يشبه حال مشركي بدر بآل فرعون في الكفر وما ترتب عليه من الأخذ، والثاني يعيد التشبيه عند تفصيل التكذيب والإهلاك والإغراق؛ فلكل موضع جهة جديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص321–326.","url":""}]},{"id":"s8-214","number":214,"surah":8,"verses":[54],"verseLabel":"الأنفال: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وكل كانوا ظالمين﴾؟","answer":"التنوين في ﴿كل﴾ عوض عن المضاف إليه؛ أي كل من مشركي بدر وآل فرعون ومن قبلهم، و﴿كانوا ظالمين﴾ تجمعهم في علة الهلاك مع اختلاف صوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص326–334.","url":""}]},{"id":"s8-215","number":215,"surah":8,"verses":[54],"verseLabel":"الأنفال: 54","question":"لماذا زاد في الموضع الثاني: ﴿وأغرقنا آل فرعون﴾، ولم يذكر الإغراق في الموضع الأول؟","answer":"الموضع الأول أجمل الأخذ بذنوبهم، أما الثاني فمقام تفصيل الهلاك؛ لذلك زاد إغراق آل فرعون ليعرض صورة مخصوصة من سنة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص592–594، تحت آل عمران 11.","url":""}]},{"id":"s8-216","number":216,"surah":8,"verses":[55],"verseLabel":"الأنفال: 55","question":"لماذا أعاد وصفهم بـ﴿شر الدواب﴾ كما في الآية 22؟","answer":"الأولى فيمن عطل السمع والعقل عمومًا، والثانية في ناقضي العهود خاصة؛ فتكرر وصف ﴿شر الدواب﴾ لأن الصنفين أبطلا خصائص الإنسان، مع تخصيص كل سياق بجرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص335–339.","url":""}]},{"id":"s8-217","number":217,"surah":8,"verses":[55],"verseLabel":"الأنفال: 55","question":"لماذا ختم بـ﴿فهم لا يؤمنون﴾ بالمضارع؟","answer":"المضارع ﴿لا يؤمنون﴾ يدل على استمرار انتفاء الإيمان وتجدد أسبابه فيهم، لا على موقف ماضٍ انقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص339–342.","url":""}]},{"id":"s8-218","number":218,"surah":8,"verses":[56],"verseLabel":"الأنفال: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين عاهدت منهم﴾ بـ«من»؟","answer":"﴿من﴾ تفيد أن المعاهدة نشأت من جهتهم أو وصلت إليهم، وفيها معنى أخذ العهد منهم؛ فليست زائدة بلا دلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص343–346.","url":""}]},{"id":"s8-219","number":219,"surah":8,"verses":[56],"verseLabel":"الأنفال: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿ينقضون عهدهم في كل مرة﴾؟","answer":"﴿في كل مرة﴾ تكشف أن النقض عادة متكررة عقب تجديد العهد، لا زلة واحدة، ولذلك استحقوا تشديد المعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص346–350.","url":""}]},{"id":"s8-220","number":220,"surah":8,"verses":[57],"verseLabel":"الأنفال: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿فإما تثقفنهم في الحرب﴾، دون أن يقال: تجدهم؟","answer":"الثقف إدراك الشيء بحذق وتمكن بعد طلب، فهو أنسب بالظفر بالناقضين في ظرف الحرب من مجرد الوجود الذي تفيده «تجدهم».","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص351–355.","url":""}]},{"id":"s8-221","number":221,"surah":8,"verses":[57],"verseLabel":"الأنفال: 57","question":"ما الصورة في ﴿فشرد بهم من خلفهم﴾؟","answer":"المعنى: أوقع بهم من النكال ما يفرق ويخيف من وراءهم؛ فجعلهم وسيلة لتشريد غيرهم وردع كل من يفكر في النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص355–357.","url":""}]},{"id":"s8-222","number":222,"surah":8,"verses":[58],"verseLabel":"الأنفال: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿فانبذ إليهم على سواء﴾؟","answer":"النبذ إلقاء العهد وطرحه إليهم علنًا، و﴿على سواء﴾ تعني استواء الطرفين في العلم بانتهائه؛ فلا يبدأ قتال مع بقاء توهم الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص358–362.","url":""}]},{"id":"s8-223","number":223,"surah":8,"verses":[58],"verseLabel":"الأنفال: 58","question":"لماذا ختم بـ﴿إن الله لا يحب الخائنين﴾؟","answer":"الخاتمة تعلل وجوب إعلان نبذ العهد؛ فمباغتة المعاهدين من غير إعلام خيانة، والله لا يحب الخائنين ولو كانت الخيانة مع عدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص362–366.","url":""}]},{"id":"s8-224","number":224,"surah":8,"verses":[59],"verseLabel":"الأنفال: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحسبن الذين كفروا سبقوا﴾؟","answer":"النهي موجه إلى النبي ﷺ أو إلى كل مخاطب ألا يظن الكافرون أنهم أفلتوا وسبقوا قدرة الله؛ فحذف أحد المفعولين أو جاء الأسلوب على قراءة الخطاب لإبراز بطلان ظن النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص367–369.","url":""}]},{"id":"s8-225","number":225,"surah":8,"verses":[59],"verseLabel":"الأنفال: 59","question":"لماذا ختم بـ﴿إنهم لا يعجزون﴾؟","answer":"﴿لا يعجزون﴾ تقطع توهم سبقهم؛ فهم لا يفوتون قدرة الله ولا يمنعونه من إدراكهم وإن أفلتوا مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص369–371.","url":""}]},{"id":"s8-226","number":226,"surah":8,"verses":[60],"verseLabel":"الأنفال: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعدوا لهم ما استطعتم من قوة﴾، فأجمل القوة؟","answer":"أُجملت القوة لتشمل كل ما تتجدد به القدرة على الردع والقتال في كل عصر، وقُيدت بـ﴿ما استطعتم﴾ لربط التكليف بالطاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص372–376.","url":""}]},{"id":"s8-227","number":227,"surah":8,"verses":[60],"verseLabel":"الأنفال: 60","question":"لماذا خصّ ﴿رباط الخيل﴾ بعد عموم القوة؟","answer":"ذُكر رباط الخيل بعد عموم القوة لعظم أثره في زمن التنزيل وظهور منزلته في الاستعداد السريع والحراسة والقتال؛ فهو تخصيص لأبرز أفراد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص376–379.","url":""}]},{"id":"s8-228","number":228,"surah":8,"verses":[60],"verseLabel":"الأنفال: 60","question":"لماذا عبّر بـ﴿ترهبون به﴾ لا «تقتلون»؟","answer":"الإرهاب هنا إلقاء الخوف الرادع في العدو؛ فمقصود الإعداد منع العدوان وكسر إرادة الهجوم قبل وقوع القتل، وهو أبلغ أثرًا وأقل كلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص379–382.","url":""}]},{"id":"s8-229","number":229,"surah":8,"verses":[60],"verseLabel":"الأنفال: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿وآخرين من دونهم لا تعلمونهم الله يعلمهم﴾؟","answer":"أبهم الآخرون لأنهم خفيون على المؤمنين أو لم يدخلوا في دائرة معرفتهم، ثم قابل جهلهم بعلم الله المحيط ليبين أن الإعداد يردع العدو المعروف والمجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص382–384.","url":""}]},{"id":"s8-230","number":230,"surah":8,"verses":[60,61],"verseLabel":"الأنفال: 60–61","question":"كيف يأمر القرآن بإعداد القوة لإرهاب العدو، ثم يأمر في الآية التالية مباشرة بقبول السلم إذا جنحوا له؟","answer":"لا تعارض؛ فإعداد القوة غايته ردع العدوان وحماية الجماعة، فإذا مال العدو إلى السلم المعتبر قُبل منه. الاستعداد يمنع استغلال السلام ضعفًا، والسلم يوقف القتال عند زوال سببه.","sources":[{"label":"تفاسير الأنفال: 60–61، https://quran.com/al-anfal/60-61.","url":""}]},{"id":"s8-231","number":231,"surah":8,"verses":[61],"verseLabel":"الأنفال: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن جنحوا للسلم فاجنح لها﴾؟","answer":"الجنوح هو الميل، فكرر الفعل للمشاكلة: إن مالوا ميلًا ظاهرًا إلى السلم فمل إليها، وفي الصورة انتقال متوازن من جانب الحرب إلى جانب الصلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص385–389.","url":""}]},{"id":"s8-232","number":232,"surah":8,"verses":[61],"verseLabel":"الأنفال: 61","question":"لماذا أُنّث الضمير في ﴿فاجنح لها﴾؟","answer":"أُنث الضمير لأنه يعود إلى ﴿السلم﴾ باعتبار معنى المسالمة أو المصالحة المؤنث، وهي لغة فصيحة في اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص389–392.","url":""}]},{"id":"s8-233","number":233,"surah":8,"verses":[61],"verseLabel":"الأنفال: 61","question":"لماذا ختم بـ﴿إنه هو السميع العليم﴾؟","answer":"﴿السميع﴾ يناسب ما يعلنونه من عرض السلم وما يدار من قول، و﴿العليم﴾ يحيط بما يخفونه من صدق أو خداع؛ وضمير الفصل يقوي انفراده بكمال الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص392–395.","url":""}]},{"id":"s8-234","number":234,"surah":8,"verses":[62,63],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يريدوا أن يخدعوك فإن حسبك الله﴾؟","answer":"جواب احتمال الخداع لم يكن رفض السلم، بل ﴿فإن حسبك الله﴾؛ أي الله كافيك شرهم، فاقبل الظاهر وتوكل على من يعلم الباطن ويحفظك.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص396–400.","url":""}]},{"id":"s8-235","number":235,"surah":8,"verses":[62,63],"verseLabel":"الأنفال: 62–63","question":"لماذا جمع بين التأييد بالنصر وبالمؤمنين؟","answer":"النصر تأييد مباشر من الله، والمؤمنون سبب بشري جمعهم حول النبي ﷺ؛ فضم المصدر الأعلى إلى الوسيلة الظاهرة التي سخّرها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص400–404.","url":""}]},{"id":"s8-236","number":236,"surah":8,"verses":[62,63],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿وألف بين قلوبهم﴾، دون أن يقال: جمعهم؟","answer":"التأليف إيجاد الألفة والمحبة بعد التفرق والعداوة، وهو أعمق من جمع الأجساد في مكان واحد؛ إذ يتعلق بوحدة القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص404–408.","url":""}]},{"id":"s8-237","number":237,"surah":8,"verses":[62,63],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿لو أنفقت ما في الأرض جميعًا ما ألفت بين قلوبهم﴾؟","answer":"الشرط يصور عجز كل مال الأرض عن صنع الألفة الحقيقية بين قلوب متعادية، فيظهر أن اجتماعهم آية من تدبير الله لا ثمرة شراء أو مصلحة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص408–413.","url":""}]},{"id":"s8-238","number":238,"surah":8,"verses":[64,65,66],"verseLabel":"الأنفال: 64–66","question":"ما سرّ التعبير في قوله تعالى: ﴿يا أيها النبي حسبك الله ومن اتبعك﴾؟","answer":"المعنى أن الله كافيك وكافي من اتبعك من المؤمنين، أو أن الله والمؤمنين حسبك على جهة أن الله أصل الكفاية وهم من أسبابها؛ والسياق يثبت للنبي ﷺ الطمأنينة بالجماعة المؤمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص414–419.","url":""}]},{"id":"s8-239","number":239,"surah":8,"verses":[64,65,66],"verseLabel":"الأنفال: 64–66","question":"ما سرّ التعبير في قوله تعالى: ﴿حرض المؤمنين على القتال﴾ لا «أمرهم»؟","answer":"التحريض حث شديد يزيل الفتور ويبعث الهمة، وهو أنسب بمشقة القتال ومواجهة الخطر من مجرد الأمر الذي قد يدل على طلب الفعل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص419–423.","url":""}]},{"id":"s8-240","number":240,"surah":8,"verses":[64,65,66],"verseLabel":"الأنفال: 64–66","question":"لماذا كان الواحد يغلب عشرة ثم خُفف إلى اثنين؟","answer":"كان التكليف الأول مناسبًا لقوة اليقين والصبر في الصفوة الأولى، فلما علم الله فيهم ضعفًا خفف النسبة إلى واحد أمام اثنين؛ تخفيف رحمة لا إبطالًا لأصل الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص423–429.","url":""}]},{"id":"s8-241","number":241,"surah":8,"verses":[64,65,66],"verseLabel":"الأنفال: 64–66","question":"لماذا علل تفوق المؤمنين بأن الكافرين ﴿قوم لا يفقهون﴾؟","answer":"الفقه فهم نافذ يقدّر حقائق الأمور وعواقبها؛ والكافرون يقاتلون بلا بصيرة بالغاية ولا رجاء فيما عند الله، أما المؤمن فيضاعف فهمه وصبره قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص429–438.","url":""}]},{"id":"s8-242","number":242,"surah":8,"verses":[67,68,69],"verseLabel":"الأنفال: 67–69","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾؟","answer":"صيغة ﴿ما كان لنبي﴾ تنفي ملاءمة اتخاذ الأسرى قبل الإثخان لسنة النبوة؛ لأن تثبيت سلطان الحق وكسر قوة العدو مقدم في بداية المواجهة على منفعة الفداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص439–445.","url":""}]},{"id":"s8-243","number":243,"surah":8,"verses":[67,68,69],"verseLabel":"الأنفال: 67–69","question":"لماذا قابل ﴿عرض الدنيا﴾ بـ﴿والله يريد الآخرة﴾؟","answer":"﴿عرض الدنيا﴾ شيء زائل قريب يُنال من الفداء، وقوبل بالآخرة الباقية التي يريد الله لهم ثوابها وإعزاز الدين الموصل إليها؛ فظهر تفاوت الإرادتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص445–450.","url":""}]},{"id":"s8-244","number":244,"surah":8,"verses":[67,68,69],"verseLabel":"الأنفال: 67–69","question":"ما سرّ تقديم المال في ﴿فيما أخذتم﴾ ثم أذن بقوله: ﴿فكلوا مما غنمتم حلالًا طيبًا﴾؟","answer":"عاتبهم على الفداء الذي أخذوه قبل تمام الإثخان، ثم أباح لهم ما صار غنيمة بحكم الله؛ ففرق بين استعجال المال قبل استقرار الحكم وبين الحلال الطيب بعد الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص450–457.","url":""}]},{"id":"s8-245","number":245,"surah":8,"verses":[67],"verseLabel":"الأنفال: 67","question":"كيف يُجمع بين قوله تعالى في الأنفال: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾، وقوله في سورة محمد: ﴿فإما منًّا بعد وإما فداء﴾؟","answer":"آية الأنفال تعالج أول بدر حين كان المسلمون قليلين ولم يثبت سلطانهم، فكان الإثخان مقدمًا؛ وبعد كثرة المسلمين واشتداد سلطانهم جاءت آية محمد فخيرت بعد إحكام الأسر بين المن والفداء.","sources":[{"label":"الطبري، جامع البيان، تفسير الأنفال: 67، الأثر 16286، https://quran.com/al-anfal/67/tafsirs/ar-tafsir-al-tabari.","url":""}]},{"id":"s8-246","number":246,"surah":8,"verses":[70],"verseLabel":"الأنفال: 70","question":"لماذا خاطب الأسرى بقوله: ﴿يا أيها النبي قل لمن في أيديكم من الأسرى﴾؟","answer":"نادى النبي ﷺ تشريفًا له وتثبيتًا لوظيفته في تبليغ الأسرى، ووصفهم بـ﴿من في أيديكم﴾ يصور تمكن المسلمين منهم مع فتح باب الرجاء لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص458–463.","url":""}]},{"id":"s8-247","number":247,"surah":8,"verses":[70],"verseLabel":"الأنفال: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿إن يعلم الله في قلوبكم خيرًا يؤتكم خيرًا مما أخذ منكم﴾؟","answer":"جعل الخير المعلوم في القلوب شرطًا للوعد، لأن حقيقة الإيمان لا يعلمها إلا الله؛ وجاء ﴿خيرًا مما أخذ منكم﴾ وعدًا بتعويض يفوق الفداء المأخوذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص463–469.","url":""}]},{"id":"s8-248","number":248,"surah":8,"verses":[70],"verseLabel":"الأنفال: 70","question":"لماذا جمع بين التعويض والمغفرة؟","answer":"التعويض يجبر خسارة الدنيا، والمغفرة تزيل تبعة الماضي وتحقق خير الآخرة؛ فجمع لهم النفع العاجل والنجاة الآجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص469–476.","url":""}]},{"id":"s8-249","number":249,"surah":8,"verses":[71],"verseLabel":"الأنفال: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد خانوا الله من قبل فأمكن منهم﴾؟","answer":"خيانة الله من قبل هي كفرهم ونقضهم ما تقتضيه الفطرة والعهد؛ ولذلك أمكن المؤمنين منهم بالأسر، ففي تاريخهم ما يهوّن احتمال خيانتهم الجديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص477–481.","url":""}]},{"id":"s8-250","number":250,"surah":8,"verses":[71],"verseLabel":"الأنفال: 71","question":"لماذا حذف مفعول ﴿فأمكن منهم﴾؟","answer":"حُذف مفعول ﴿أمكن﴾ ليتسع المعنى لكل وجوه التمكين منهم: أسرًا وقتلًا وغلبة، ولأن السياق يدل على تمكين المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص481–487.","url":""}]},{"id":"s8-251","number":251,"surah":8,"verses":[71],"verseLabel":"الأنفال: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد خانوا الله من قبل فأمكن منهم﴾، دون أن يقال على سبيل المقابلة: «فخانهم»؟","answer":"لم يقل «فخانهم» لأن الخيانة نقص مذموم لا تنسب إلى الله؛ بل عاقب خيانتهم بالعدل فقال ﴿فأمكن منهم﴾، وهو منزه عن مقابلة السيئة بمثل وصفها القبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص719، تحت النساء 105.","url":""}]},{"id":"s8-252","number":252,"surah":8,"verses":[72],"verseLabel":"الأنفال: 72","question":"لماذا جمع بين الهجرة والجهاد بالمال والنفس؟","answer":"الهجرة مفارقة موطن الكفر ونصرة الجماعة، والجهاد بالمال والنفس بذل وسائل النصرة كلها؛ فاجتمعت التضحية بالمكان والمال والحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص488–495.","url":""}]},{"id":"s8-253","number":253,"surah":8,"verses":[72],"verseLabel":"الأنفال: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك بعضهم أولياء بعض﴾؟","answer":"﴿بعضهم أولياء بعض﴾ تقرر ولاية متبادلة بين المهاجرين والأنصار تشمل النصرة والتعاون وما كان من أحكام الجماعة، فجعلتهم كتلة متكافلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص495–501.","url":""}]},{"id":"s8-254","number":254,"surah":8,"verses":[72],"verseLabel":"الأنفال: 72","question":"لماذا نفى الولاية عن المؤمنين الذين لم يهاجروا مع بقاء إيمانهم؟","answer":"المنفي هو تمام ولاية النصرة والأحكام المرتبطة بدار الهجرة، لا أصل الموالاة الإيمانية؛ لأنهم لم ينضموا بعد إلى جماعة الدولة القادرة على حمايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص501–507.","url":""}]},{"id":"s8-255","number":255,"surah":8,"verses":[72],"verseLabel":"الأنفال: 72","question":"لماذا استثنى النصرة عند وجود ميثاق مع قوم آخرين؟","answer":"الميثاق يمنع نصرة تفضي إلى نقض عهد قائم؛ فحفظ العهود واجب، وتُطلب نصرة المؤمنين بوسيلة لا توقع الجماعة في الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص507–511.","url":""}]},{"id":"s8-256","number":256,"surah":8,"verses":[20],"verseLabel":"الأنفال: 72؛ التوبة: 20","question":"ما سرّ التعبير في قوله تعالى في الأنفال: ﴿وجاهدوا بأموالهم وأنفسهم في سبيل الله﴾، وفي التوبة: ﴿وجاهدوا في سبيل الله بأموالهم وأنفسهم﴾؟","answer":"قُدّم ﴿بأموالهم وأنفسهم﴾ في الأنفال لأن سياقها سبق فيه الفداء والغنيمة وعرض الدنيا، وقُدّم ﴿في سبيل الله﴾ في التوبة لأن ذكر الجهاد سبق فيها وتكرر؛ فكل تقديم يراعي محور سياقه.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص132–133؛ والنص الرقمي المحقق: https://islamweb.net/ar/library/content/224/9/.","url":""}]},{"id":"s8-257","number":257,"surah":8,"verses":[74,75],"verseLabel":"الأنفال: 72؛ الأنفال: 74–75","question":"لماذا ذكرت الآية 72 الجهاد كاملًا: ﴿بأموالهم وأنفسهم في سبيل الله﴾، ثم حذفت الأموال والأنفس في الآية 74، وحذفت معها ﴿في سبيل الله﴾ في الآية 75؟","answer":"ذُكر في الآية 72 الجهاد كامل القيود لأنه أول ورود هذا الوصف، ثم حُذف ﴿بأموالهم وأنفسهم﴾ في الآية 74 اكتفاء بالأول، وحُذف معها ﴿في سبيل الله﴾ في الآية 75 اكتفاء بما تقدم مرتين.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص133؛ والنص الرقمي المحقق: https://islamweb.net/ar/library/content/224/9/.","url":""}]},{"id":"s8-258","number":258,"surah":8,"verses":[73],"verseLabel":"الأنفال: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين كفروا بعضهم أولياء بعض﴾ في مقابلة ولاية المؤمنين؟","answer":"كما يتناصر المؤمنون، يتناصر الكافرون بحكم اجتماعهم على الكفر والمصلحة؛ فالمقابلة تحذر المؤمنين من ترك ولايتهم التي تحفظ جماعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص512–516.","url":""}]},{"id":"s8-259","number":259,"surah":8,"verses":[73],"verseLabel":"الأنفال: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا تفعلوه تكن فتنة في الأرض وفساد كبير﴾، وأبهم الفعل؟","answer":"أُبهم الفعل في ﴿إلا تفعلوه﴾ ليشمل ما سبق من الولاية والنصرة والتعاون وحفظ نظام الجماعة؛ وترك ذلك يتيح فتنة المؤمنين وفساد الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص516–520.","url":""}]},{"id":"s8-260","number":260,"surah":8,"verses":[74],"verseLabel":"الأنفال: 74","question":"لماذا أعاد وصف المهاجرين والأنصار ثم قال: ﴿أولئك هم المؤمنون حقًا﴾؟","answer":"أعيد وصفهم بعد تفصيل أحكام الولاية تثبيتًا لفضل الهجرة والنصرة والجهاد، ثم أكد بـ﴿أولئك هم المؤمنون حقًا﴾ أن أعمالهم حققت دعوى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص521–526.","url":""}]},{"id":"s8-261","number":261,"surah":8,"verses":[74],"verseLabel":"الأنفال: 74","question":"لماذا ختم جزاءهم بـ﴿مغفرة ورزق كريم﴾ كما في الآية 4؟","answer":"كرر الجزاء نفسه لاتحاد الصفات الجامعة للإيمان في الموضعين، فالمغفرة تزيل التقصير والرزق الكريم يتم النعمة؛ وزاد السياق هنا بيان ثبوت الإيمان بعد الهجرة والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص526–534.","url":""}]},{"id":"s8-262","number":262,"surah":8,"verses":[75],"verseLabel":"الأنفال: 75","question":"لماذا أُلحق المتأخرون في الهجرة بقوله: ﴿فأولئك منكم﴾؟","answer":"أُلحق اللاحقون لأن صدق هجرتهم وجهادهم أدخلهم في جماعة المؤمنين وأحكامها، فـ﴿منكم﴾ تمنحهم تمام الانتماء ولا تجعل سبق الزمن حاجزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص535–539.","url":""}]},{"id":"s8-263","number":263,"surah":8,"verses":[75],"verseLabel":"الأنفال: 75","question":"ما سرّ تقديم أولو الأرحام في الحكم بعد تقرير أخوة الإيمان؟","answer":"أخوة الإيمان أصل الولاية والنصرة، أما أولو الأرحام فأولى في الحكم الخاص بالميراث وسائر الحقوق التي خصها الشرع بالقرابة؛ فلا تعارض لاختلاف المجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص539–543.","url":""}]},{"id":"s8-264","number":264,"surah":8,"verses":[75],"verseLabel":"الأنفال: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿في كتاب الله﴾؟","answer":"﴿في كتاب الله﴾ تثبت أن أولوية الأرحام حكم مكتوب مقرر في شرع الله وعلمه، لا ترتيبًا ناشئًا من عرف الناس أو مصالحهم المؤقتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص543–547.","url":""}]},{"id":"s8-265","number":265,"surah":8,"verses":[75],"verseLabel":"الأنفال: 75","question":"لماذا ختمت السورة بـ﴿إن الله بكل شيء عليم﴾؟","answer":"خُتمت السورة بالعلم المحيط لأنه أساس دقة أحكام الأنفال والعهود والولاية والمواريث؛ فالله يعلم المصالح والنيات والصلات، ويضع لكل منها حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص547–559.","url":""}]},{"id":"s9-1","number":1,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا بدأت سورة التوبة من غير بسملة، بخلاف سائر سور القرآن؟","answer":"لم تُكتب البسملة بين الأنفال والتوبة اتباعًا لما استقر عليه المصحف، وتناسب ذلك مع افتتاح السورة بالبراءة ورفع الأمان عن ناقضي العهود؛ فليس المقام مقام استهلال بالرحمة والأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص558–559.","url":""}]},{"id":"s9-2","number":2,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا افتتحت السورة بكلمة واحدة نكرة: ﴿براءة﴾؟","answer":"افتتحت بـ﴿براءة﴾ لتجعل معنى قطع العهد عنوانًا للسورة وأول ما يقرع السمع، ونُكرت للتفخيم: براءة عظيمة الشأن ذات أحكام عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص559–561.","url":""}]},{"id":"s9-3","number":3,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿براءة﴾، دون أن يقال: «تبرؤ» أو «نقض عهد»؟","answer":"البراءة تدل على الخلاص والانقطاع من العهد والتبعة، فهي أصرح في زوال رابطة الأمان من لفظ «تبرؤ»، وأوسع من مجرد «نقض عهد»؛ لأنها إعلان لحكم وما يترتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص560–564.","url":""}]},{"id":"s9-4","number":4,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا رُفعت ﴿براءة﴾، مع إمكان أن يقال: «هذه براءة»؟","answer":"رُفعت ﴿براءة﴾ على الابتداء وخبرها ﴿من الله ورسوله﴾، أو على أنها خبر لمبتدأ محذوف؛ وفي الوجهين جاءت جملة مستقلة قوية كعنوان معلن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص560–562.","url":""}]},{"id":"s9-5","number":5,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا نُسبت البراءة إلى الله ورسوله معًا: ﴿براءة من الله ورسوله﴾؟","answer":"البراءة حكم صادر من الله، والرسول ﷺ مبلغه والمنفذ له؛ فنسبت إليهما مع اختلاف الجهة، لا على معنى تساوي المصدرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562–565.","url":""}]},{"id":"s9-6","number":6,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿من الله ورسوله﴾، ولم يكرر حرف الجر فيقول: «من الله ومن رسوله»؟","answer":"جمعهما حرف جر واحد لأن البراءة الصادرة حكم واحد، ولإظهار اتصال تبليغ الرسول بأمر الله، مع بقاء الله مصدر الحكم ورسوله مبلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص565–566.","url":""}]},{"id":"s9-7","number":7,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا اختير حرف الابتداء ﴿من﴾ في ﴿براءة من الله﴾؟","answer":"﴿من﴾ لابتداء الغاية؛ أي إن منشأ هذا الحكم ومصدر صدوره من عند الله ورسوله، فليست البراءة رأيًا بشريًا أو تصرفًا منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص566–568.","url":""}]},{"id":"s9-8","number":8,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا عُبر عن المعاهدة بالماضي: ﴿عاهدتم﴾؟","answer":"الماضي ﴿عاهدتم﴾ يقرر وقوع العهد وثبوته قبل إعلان البراءة، فيبني الحكم على عقد سبق وجوده لا على احتمال مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص567–568.","url":""}]},{"id":"s9-9","number":9,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿عاهدتم من المشركين﴾، فأدخل ﴿من﴾ على المشركين؟","answer":"﴿من﴾ بيانية تبين جنس من وقع العهد معهم، أو تبعيضية لأن الحكم لا يتناول كل مشرك على صورة واحدة؛ فقد استُثني الموفون بعهودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص567–569.","url":""}]},{"id":"s9-10","number":10,"surah":9,"verses":[1],"verseLabel":"التوبة: 1","question":"لماذا نسب المعاهدة إلى المسلمين: ﴿عاهدتم﴾، مع أن النبي ﷺ هو الذي عقدها؟","answer":"أُسندت المعاهدة إلى جماعة المسلمين لأن آثارها والتزامها تعمهم، وإن تولى النبي ﷺ عقدها نيابة عن الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568–569.","url":""}]},{"id":"s9-11","number":11,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا انتقل من الخبر ﴿براءة﴾ إلى الأمر: ﴿فسيحوا في الأرض﴾؟","answer":"الفاء تفريع؛ فلما أُعلنت البراءة ترتب عليها منح المخالفين مهلة يسيرون فيها آمنين قبل نفاذ الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص569–571.","url":""}]},{"id":"s9-12","number":12,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيحوا﴾، دون أن يقال: «فسيروا» أو «اذهبوا»؟","answer":"السياحة هي السير الممتد في سعة وأمن وتصرّف، فناسبت المهلة الممنوحة لهم، وهي أوسع دلالة من مجرد الذهاب أو السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص570–578.","url":""}]},{"id":"s9-13","number":13,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا قيد السياحة بقوله: ﴿في الأرض﴾؟","answer":"ذُكرت الأرض لإطلاق حركتهم في جهاتها خلال المهلة، ولتأكيد أن السياحة حقيقية لا مجاز عن مجرد الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص571–572.","url":""}]},{"id":"s9-14","number":14,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا حُددت المهلة بـ﴿أربعة أشهر﴾؟","answer":"الأشهر الأربعة أجل كافٍ يبلغ فيه الإعلان الآفاق، ويراجع فيه المشركون موقفهم، وتنتهي بعده حجتهم في طلب مهلة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص572–573.","url":""}]},{"id":"s9-15","number":15,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا جاءت ﴿أربعة أشهر﴾ نكرة؟","answer":"نُكرت ﴿أربعة أشهر﴾ لأنها مدة محسوبة من وقت الإعلان لا أسماء أشهر معينة بأعيانها لكل المخاطبين، وللعناية بمقدارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص572–574.","url":""}]},{"id":"s9-16","number":16,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿واعلموا أنكم غير معجزي الله﴾، دون أن يقال: «لن تعجزوا الله»؟","answer":"الجملة الاسمية بـ﴿غير معجزي﴾ تثبت دوام عجزهم عن الإفلات من قدرة الله، بخلاف صيغة فعل مستقبل قد يتوهم منها تعلق النفي بزمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص573–575.","url":""}]},{"id":"s9-17","number":17,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا اختير وصف ﴿غير معجزي الله﴾ بدل «مغلوبون»؟","answer":"﴿غير معجزي الله﴾ ينفي قدرتهم على السبق والإفلات، وهو أدق من «مغلوبون»؛ فقد يتأخر أخذهم لكنهم لا يعجزون الله بحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص574–576.","url":""}]},{"id":"s9-18","number":18,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا انتقل من خطاب المشركين إلى الغيبة في قوله: ﴿وأن الله مخزي الكافرين﴾؟","answer":"انتقل من مواجهتهم في ﴿أنكم﴾ إلى وصف جنسهم بـ﴿الكافرين﴾؛ ليجعل الخزي سنة عامة في كل من ثبت على الكفر، لا خبرًا خاصًا بالحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص575–577.","url":""}]},{"id":"s9-19","number":19,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿مخزي الكافرين﴾ بصيغة اسم الفاعل؟","answer":"اسم الفاعل ﴿مخزي﴾ يفيد ثبوت الخزي وتحققه واستمراره، فكأن وقوعه وصف قائم لا مجرد فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص574–576.","url":""}]},{"id":"s9-20","number":20,"surah":9,"verses":[2],"verseLabel":"التوبة: 2","question":"لماذا وصفهم في الخاتمة بالكافرين بعد تسميتهم أولًا بالمشركين؟","answer":"ذكر الكفر لأنه الأصل الجامع للشرك ونقض العهد والتولي، وليربط الخزي بوصفهم العقدي الذي أصروا عليه بعد الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص575–577.","url":""}]},{"id":"s9-21","number":21,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا أعاد إعلان البراءة في قوله: ﴿وأذان من الله ورسوله﴾ بعد قوله في الآية الأولى: ﴿براءة من الله ورسوله﴾؟","answer":"البراءة في الآية الأولى نفس الحكم، و﴿أذان﴾ هنا إعلان ذلك الحكم وتبليغه إلى الناس في يوم مشهود؛ فالثانية ليست إعادة للأولى بل إشهار لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص578–580.","url":""}]},{"id":"s9-22","number":22,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿أذان﴾، دون أن يقال: «إعلام»؟","answer":"الأذان إعلام مرتفع يبلغ الأسماع ويشيع، فناسب الإعلان العام في الحج أكثر من لفظ «إعلام» الذي لا يفيد قوة النداء وانتشاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص579–581.","url":""}]},{"id":"s9-23","number":23,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا جاءت ﴿أذان﴾ نكرة كما جاءت ﴿براءة﴾ نكرة؟","answer":"نُكر ﴿أذان﴾ للتعظيم كما نكرت ﴿براءة﴾؛ فالإعلان عظيم بمصدره ومضمونه وعموم من يبلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص579–581.","url":""}]},{"id":"s9-24","number":24,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى الناس﴾، مع أن البراءة متعلقة بالمشركين؟","answer":"وُجه الأذان إلى الناس جميعًا لأن أحكام العهود والحج والأمان تمس المجتمع كله، وليشهد المؤمن والمشرك الإعلان فلا تبقى جهالة أو شبهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص580–581.","url":""}]},{"id":"s9-25","number":25,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا وصف يوم الحج بأنه ﴿الأكبر﴾؟","answer":"هو يوم النحر؛ لاجتماع معظم أعمال الحج والناس فيه، ووصف بالأكبر تمييزًا له من العمرة التي سميت الحج الأصغر، وتعظيمًا لشأن الإعلان الواقع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص581–582.","url":""}]},{"id":"s9-26","number":26,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا أعيد ذكر الله ورسوله في ﴿أن الله بريء من المشركين ورسوله﴾؟","answer":"أعيد الاسمان لأن المقام تحول من صدور البراءة إلى التصريح بمضمون الأذان، فكان إظهارهما أبلغ في تثبيت مصدر الحكم ومبلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص582–584.","url":""}]},{"id":"s9-27","number":27,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿أن الله بريء من المشركين ورسوله﴾، دون أن يقال: «أن الله ورسوله بريئان»؟","answer":"أفرد ﴿بريء﴾ مع اسم الله ثم عطف ﴿ورسوله﴾ جملةً مستقلة في المعنى؛ صيانةً للمقام من تسوية غير لائقة، وإبرازًا لأن براءة الرسول تابعة لبراءة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص582–584.","url":""}]},{"id":"s9-28","number":28,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا رُفع ﴿ورسوله﴾ بعد قوله: ﴿من المشركين﴾، مع احتمال التباس السامع؟","answer":"رُفع ﴿ورسوله﴾ لأنه معطوف على محل اسم الجلالة أو مبتدأ خبره محذوف تقديره «بريء»، فلا يجوز جره عطفًا على المشركين؛ والرفع يمنع المعنى الفاسد عند تمام التركيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص582–584.","url":""}]},{"id":"s9-29","number":29,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا جاء بعد إعلان البراءة مباشرة: ﴿فإن تبتم فهو خير لكم﴾؟","answer":"فتح باب التوبة عقب البراءة يبين أن المقصود إنهاء الشرك ونقض العهد لا التشفي، وأن الرجوع إلى الحق يبدل الحكم ويحقق النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص583–584.","url":""}]},{"id":"s9-30","number":30,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فهو خير لكم﴾، ولم يصرح بما في التوبة من النجاة والمغفرة؟","answer":"﴿خير لكم﴾ عبارة جامعة لكل خير التوبة في الدنيا والآخرة، وترك التفصيل يطلق الذهن لاستحضار أنواع النجاة والمغفرة والأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص583–585.","url":""}]},{"id":"s9-31","number":31,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"لماذا قابل التوبة بقوله: ﴿وإن توليتم فاعلموا أنكم غير معجزي الله﴾؟","answer":"قوبلت التوبة بالتولي لإظهار الطريقين وعاقبتيهما: الرجوع خير، والإعراض لا يحقق نجاة؛ لأنهم لا يفوتون قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص584–585.","url":""}]},{"id":"s9-32","number":32,"surah":9,"verses":[3],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿وبشر الذين كفروا بعذاب أليم﴾، واستعمل البشارة في العذاب؟","answer":"استعملت البشارة تهكمًا؛ فالبشارة في أصلها خبر يغير البشرة، ثم شاع استعمالها في الخير، فقلبت هنا إلى وعيد يزيدهم تحسرًا بعذاب أليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص584–585.","url":""}]},{"id":"s9-33","number":33,"surah":9,"verses":[4],"verseLabel":"التوبة: 4","question":"لماذا استثنى من البراءة المشركين الذين لم ينقصوا المسلمين شيئًا ولم يظاهروا عليهم أحدًا؟","answer":"استُثني الموفون لأن البراءة من الناقضين لا تبيح خيانة من حفظ عهده؛ فالعدل يوجب إتمام مدته لمن لم ينقص ولم يعن عدوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص593–596.","url":""}]},{"id":"s9-34","number":34,"surah":9,"verses":[4],"verseLabel":"التوبة: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لم ينقصوكم شيئًا﴾، ونكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم كل نقص، قليلًا أو كثيرًا، فتؤكد كمال وفائهم وعدم إخلالهم بأي حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص594–597.","url":""}]},{"id":"s9-35","number":35,"surah":9,"verses":[4],"verseLabel":"التوبة: 4","question":"لماذا عبّر عن إعانة العدو بقوله: ﴿ولم يظاهروا عليكم أحدًا﴾؟","answer":"المظاهرة المعاونة؛ وأصلها أن يجعل المعين نفسه ظهرًا يقوي صاحبه، فالتعبير يصور اتحادهم مع العدو في القوة والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص596–598.","url":""}]},{"id":"s9-36","number":36,"surah":9,"verses":[4],"verseLabel":"التوبة: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتموا إليهم عهدهم﴾، دون أن يقال: «فاحفظوا عهدهم»؟","answer":"الإتمام إيصال العهد إلى نهاية مدته كاملًا غير منقوص، وهو أدق من «الحفظ» الذي قد يدل على مجرد عدم النقض دون استيفاء الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص598–600.","url":""}]},{"id":"s9-37","number":37,"surah":9,"verses":[4],"verseLabel":"التوبة: 4","question":"لماذا أضاف العهد إليهم: ﴿عهدهم﴾، مع أنه عهد بين طرفين؟","answer":"أضيف العهد إليهم للعناية بحقهم الثابت به، وللتنبيه إلى أن الوفاء يصل إليهم كاملًا وإن كان الالتزام متبادلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص599–600.","url":""}]},{"id":"s9-38","number":38,"surah":9,"verses":[4],"verseLabel":"التوبة: 4","question":"لماذا ختم الأمر بالوفاء بقوله: ﴿إن الله يحب المتقين﴾؟","answer":"ختم بمحبة المتقين لأن الوفاء للمعاهد المخالف مع القدرة عليه من التقوى؛ فالخاتمة تعلل الإتمام وتجعله طاعة لله لا مجرد مصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص600–601.","url":""}]},{"id":"s9-39","number":39,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"لماذا علّق الأمر بقتال المشركين على انسلاخ الأشهر الحرم؟","answer":"عُلّق القتال بانتهاء المهلة صيانة للأمان الذي مُنح لهم، فلا يبدأ الحكم قبل تمام الأجل وبلوغ الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص602–605.","url":""}]},{"id":"s9-40","number":40,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿انسلخ الأشهر الحرم﴾، فشبّه الزمن بشيء ينسلخ؟","answer":"صُوّر انقضاء الأشهر بانسلاخ الجلد عن الجسد؛ للدلالة على خروجها جزءًا بعد جزء حتى تزول كلها ولا يبقى منها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص603–606.","url":""}]},{"id":"s9-41","number":41,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"لماذا جاءت الأوامر متتابعة: ﴿فاقتلوا... وخذوهم واحصروهم واقعدوا لهم﴾؟","answer":"تتابع الأوامر لاستيعاب أحوال المواجهة بحسب ما يقتضيه القتال: مباشرة، وأسرًا، ومنعًا، وترصدًا؛ فلا يفسر فعل واحد جميع صورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص606–610.","url":""}]},{"id":"s9-42","number":42,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿حيث وجدتموهم﴾ مع وجود استثناءات العهود والأمان في السياق؟","answer":"العموم مقيد بالسياق: فهو في المشركين الناقضين بعد انقضاء مهلتهم، لا أهل العهد المستقيم ولا طالب الأمان المذكور في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص607–611.","url":""}]},{"id":"s9-43","number":43,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿وخذوهم﴾ بعد ذكر القتل؟","answer":"ذُكر الأخذ بعد القتل ليشمل الأسر والقبض على من لم يقع عليه القتل؛ فليس الأمر مقصورًا على صورة واحدة من المعاملة الحربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص609–611.","url":""}]},{"id":"s9-44","number":44,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"ما الصورة في قوله: ﴿واقعدوا لهم كل مرصد﴾؟","answer":"صوّرهم مترقبين في طرق العدو ومداخله، حتى كأن كل موضع ترصد قد صار مجلسًا ثابتًا لهم يمنع الحركة المعادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص610–612.","url":""}]},{"id":"s9-45","number":45,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿كل مرصد﴾، فنصب المرصد، دون أن يقال: «في كل مرصد»؟","answer":"نُصب ﴿كل مرصد﴾ على الظرفية بتضمين المرصد معنى المكان، فدل على استيعاب مواقع الترصد مباشرة، وجاء أوجز من ذكر حرف الجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص611–613.","url":""}]},{"id":"s9-46","number":46,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"لماذا فتح باب النجاة بعد هذه الشدة بقوله: ﴿فإن تابوا وأقاموا الصلاة وآتوا الزكاة فخلوا سبيلهم﴾؟","answer":"فتح النجاة يؤكد أن شدة الأوامر متعلقة ببقاء الحرب والشرك، فإذا ظهرت التوبة بشعائر الإسلام زال موجب القتال وصينت الدماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص612–614.","url":""}]},{"id":"s9-47","number":47,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"لماذا عبّر عن تركهم بقوله: ﴿فخلوا سبيلهم﴾؟","answer":"تخلية السبيل كناية عن رفع كل تعرض ومنع، كأن طريقهم كان محبوسًا فأطلق؛ وهي أوسع من مجرد «اتركوهم».","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص613–614.","url":""}]},{"id":"s9-48","number":48,"surah":9,"verses":[5],"verseLabel":"التوبة: 5","question":"لماذا ختمت آية القتال بـ﴿إن الله غفور رحيم﴾؟","answer":"ناسب ﴿غفور رحيم﴾ قبول التوبة بعد الكفر والعداء؛ فالمغفرة تمحو الماضي والرحمة تفتح لهم حياة جديدة بين المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص614–615.","url":""}]},{"id":"s9-49","number":49,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن أحد من المشركين استجارك﴾، فأفرد ﴿أحد﴾ بعد الحكم العام؟","answer":"إفراد ﴿أحد﴾ يقرر حماية كل فرد من المشركين يطلب الأمان، ولو كان واحدًا من الجماعة المحكوم عليها بالقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص615–617.","url":""}]},{"id":"s9-50","number":50,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"لماذا تقدّم ﴿أحد﴾ على فعله في قوله: ﴿وإن أحد من المشركين استجارك﴾؟","answer":"ارتفع ﴿أحد﴾ بفعل مقدر يفسره ﴿استجارك﴾؛ وتقديمه يبرز العناية بشخص المستجير ويمنع توهم أن الحكم لا يكون إلا لجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص616–618.","url":""}]},{"id":"s9-51","number":51,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿فأجره﴾، ولم يكتف بالنهي عن قتله؟","answer":"﴿فأجره﴾ أمر إيجابي بمنحه الحماية، وهو أبلغ من مجرد عدم قتله؛ إذ يوجب صونه وتمكينه من سماع الحق في أمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص618–620.","url":""}]},{"id":"s9-52","number":52,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"لماذا جُعلت غاية الأمان أن ﴿يسمع كلام الله﴾؟","answer":"جُعل سماع كلام الله غاية الأمان ليعرف حقيقة الدعوة من مصدرها قبل الحكم عليها، فتقام الحجة في جو خالٍ من الإكراه والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص619–621.","url":""}]},{"id":"s9-53","number":53,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿كلام الله﴾، دون أن يقال: «القرآن»؟","answer":"﴿كلام الله﴾ يبرز مصدر القرآن وشرفه وحجيته؛ فالمستجير لا يسمع كلام بشر بل الوحي الذي دُعي إلى الإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص620–621.","url":""}]},{"id":"s9-54","number":54,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"ما مناسبة قوله تعالى بعد إسماع المستجير القرآن: ﴿ثم أبلغه مأمنه﴾؟","answer":"إبلاغه مأمنه وفاء بالأمان حتى بعد سماع القرآن؛ فلا يترك عرضة للقتل في طريق العودة، سواء آمن أم اختار الانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص621–623.","url":""}]},{"id":"s9-55","number":55,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"لماذا لم يُلزم المستجير بالإسلام بعد سماع كلام الله؟","answer":"لأن وظيفة الدعوة البلاغ وإقامة الحجة، والإيمان لا يصح بالإكراه؛ فإذا لم يؤمن بقي له حق الأمان حتى يبلغ مأمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص622–624.","url":""}]},{"id":"s9-56","number":56,"surah":9,"verses":[6],"verseLabel":"التوبة: 6","question":"لماذا علّل حمايته بقوله: ﴿ذلك بأنهم قوم لا يعلمون﴾؟","answer":"جهلهم بحقيقة الإسلام هو سبب إتاحة السماع والبيان لهم، لا سببًا لسفك دمهم؛ فالحماية تمنحهم فرصة العلم قبل المؤاخذة على موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص623–625.","url":""}]},{"id":"s9-57","number":57,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"لماذا بدأ بالاستفهام: ﴿كيف يكون للمشركين عهد عند الله وعند رسوله﴾؟","answer":"الاستفهام إنكاري يستبعد ثبوت عهد عام لمن ظهرت خيانتهم، ويمهد لاستثناء من استقام على عهده؛ فلا ينفي كل عهد بلا تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص625–629.","url":""}]},{"id":"s9-58","number":58,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"لماذا كرر ﴿عند﴾ في ﴿عند الله وعند رسوله﴾؟","answer":"كرر ﴿عند﴾ لتمييز جهتي العهد: حكمه عند الله وتنفيذه عند رسوله، ولتعظيم ثبوته إذا صح في كلتا الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص628–631.","url":""}]},{"id":"s9-59","number":59,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"لماذا استثنى مرة أخرى أهل العهد عند المسجد الحرام؟","answer":"أعيد الاستثناء لأن السياق بعد الإنكار العام يحتاج إلى إخراج الموفين صراحة، لئلا يحمل ذم الناقضين على نقض عهد المستقيمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص630–633.","url":""}]},{"id":"s9-60","number":60,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"لماذا جعل وفاء المسلمين تابعًا لاستقامتهم: ﴿فما استقاموا لكم فاستقيموا لهم﴾؟","answer":"جعل الوفاء مقابل وفائهم تحقيقًا للعدل؛ فمدة استقامتهم هي مدة لزوم الاستقامة لهم، فإذا نقضوا زال موجب استمرار العهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص632–636.","url":""}]},{"id":"s9-61","number":61,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿استقاموا لكم﴾ لا «استقاموا معكم»؟","answer":"اللام في ﴿لكم﴾ تفيد توجيه الاستقامة لمصلحتهم والوفاء بحقهم، فهي أدق في تصوير التزامهم تجاه المسلمين من «معكم» التي تفيد المصاحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص635–638.","url":""}]},{"id":"s9-62","number":62,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"لماذا تكررت مادة الاستقامة في الشرط والجواب؟","answer":"تكررت المادة للمشاكلة والمقابلة العادلة: استقامة تقابلها استقامة من جنسها، فيتطابق الشرط والجزاء لفظًا ومعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص637–639.","url":""}]},{"id":"s9-63","number":63,"surah":9,"verses":[7],"verseLabel":"التوبة: 7","question":"لماذا ختم مرة أخرى بـ﴿إن الله يحب المتقين﴾؟","answer":"كرر الختم لأن الوفاء في هذا الموضع أيضًا امتحان للتقوى، ولتأكيد أن الاستقامة للمعاهدين محبوبة لله وليست ضعفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص639–641.","url":""}]},{"id":"s9-64","number":64,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"لماذا أعاد الاستفهام بكلمة واحدة: ﴿كيف﴾؟","answer":"أعادت ﴿كيف﴾ وحدها إنكار إمكان بقاء العهد، ثم فصلت علة الإنكار: أنهم إن يظفروا لا يراعوا قرابة ولا عهدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص641–643.","url":""}]},{"id":"s9-65","number":65,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يظهروا عليكم﴾، دون أن يقال: «وإن ينتصروا»؟","answer":"الظهور هو العلو والغلبة والتمكن، وهو أوسع من مجرد الانتصار في واقعة؛ إذ يصور صيرورتهم فوق المسلمين قادرين عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص642–645.","url":""}]},{"id":"s9-66","number":66,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"لماذا جمع بين ﴿إلًّا ولا ذمة﴾؟","answer":"﴿الإل﴾ يشمل القرابة أو العهد والحلف، و﴿الذمة﴾ حرمة الأمان والالتزام؛ فالجمع ينفي مراعاتهم للرابطة الطبيعية والحق التعاقدي معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص644–648.","url":""}]},{"id":"s9-67","number":67,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿يرضونكم بأفواههم وتأبى قلوبهم﴾؟","answer":"الصورة تقابل بين ظاهر الكلام وباطن الاعتقاد: أفواه تنطق بما يرضي، وقلوب ترفض الوفاء؛ فتفضح التناقض والنفاق في معاملتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص648–651.","url":""}]},{"id":"s9-68","number":68,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"لماذا نسب الرضا إلى الأفواه والإباء إلى القلوب؟","answer":"نُسب الإرضاء للأفواه لأنه قول سطحي لا يجاوز اللسان، ونُسب الإباء للقلوب لأنها محل النية والعزم الحقيقي؛ فظهر انفصال القول عن الضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص650–653.","url":""}]},{"id":"s9-69","number":69,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"لماذا عبّر عن رفض القلوب بـ﴿تأبى﴾ لا «تكره»؟","answer":"الإباء امتناع شديد ناشئ عن أنفة وعزم، وهو أقوى من الكراهة التي قد تبقى شعورًا دون رفض عملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص652–654.","url":""}]},{"id":"s9-70","number":70,"surah":9,"verses":[8],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وأكثرهم فاسقون﴾، ولم يعمم الفسق عليهم جميعًا؟","answer":"قال ﴿أكثرهم﴾ احترازًا وإنصافًا؛ لأن الحكم الغالب لا يستلزم أن كل فرد بلغ الدرجة نفسها، وفيهم من قد يفي أو يرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص653–656.","url":""}]},{"id":"s9-71","number":71,"surah":9,"verses":[9],"verseLabel":"التوبة: 9","question":"لماذا صوّر استبدالهم بآيات الله بقوله: ﴿اشتروا بآيات الله ثمنًا قليلًا﴾؟","answer":"استعير الشراء لاستبدالهم آيات الله ومقتضاها بمصلحة عاجلة؛ فصوروا كتاجر باع النفيس الباقي بثمن حقير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص657–660.","url":""}]},{"id":"s9-72","number":72,"surah":9,"verses":[9],"verseLabel":"التوبة: 9","question":"لماذا وصف الثمن بـ﴿قليلًا﴾ مهما عظم في أعينهم؟","answer":"كل عرض دنيوي قليل إذا قيس بآيات الله وثوابها، ولو عظم في أعينهم؛ فالقلة نسبية إلى ما تركوه وإلى سرعة زواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص659–661.","url":""}]},{"id":"s9-73","number":73,"surah":9,"verses":[9],"verseLabel":"التوبة: 9","question":"لماذا فرّع على البيع قوله: ﴿فصدوا عن سبيله﴾؟","answer":"الفاء تبين نتيجة صفقتهم: لما آثروا الثمن القليل لم يكتفوا بالضلال، بل صدوا أنفسهم وغيرهم عن سبيل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص661–663.","url":""}]},{"id":"s9-74","number":74,"surah":9,"verses":[9],"verseLabel":"التوبة: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿سبيله﴾ بالإفراد؟","answer":"أُفرد السبيل لأن طريق الحق الموصل إلى الله واحد في أصله، بخلاف سبل الباطل المتفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص662–664.","url":""}]},{"id":"s9-75","number":75,"surah":9,"verses":[9],"verseLabel":"التوبة: 9","question":"لماذا ختم بـ﴿إنهم ساء ما كانوا يعملون﴾، ولم يقل: «ساء عملهم»؟","answer":"﴿ما كانوا يعملون﴾ تجعل الذم واقعًا على جنس عملهم المتجدد المستمر، لا على عمل مفرد، وتبرز رسوخ السوء في عادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص664–667.","url":""}]},{"id":"s9-76","number":76,"surah":9,"verses":[10],"verseLabel":"التوبة: 10","question":"لماذا كرر: ﴿لا يرقبون في مؤمن إلًّا ولا ذمة﴾ بعد وروده في الآية 8؟","answer":"الموضع الأول يعلل استبعاد عهدهم عند التمكن، والثاني يقرر الصفة نفسها في حق كل مؤمن ويمهد للحكم عليهم بالاعتداء؛ فزاد السياق الثاني تقريرًا وتعميمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص667–670.","url":""}]},{"id":"s9-77","number":77,"surah":9,"verses":[10],"verseLabel":"التوبة: 10","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿في مؤمن﴾، وقال قبلها: ﴿فيكم﴾؟","answer":"﴿فيكم﴾ تخاطب جماعة المسلمين في مقام بيان موقف العدو منهم، أما ﴿في مؤمن﴾ فتجعل الوصف الإيماني نفسه سببًا لعداوتهم، وتشمل كل فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص668–671.","url":""}]},{"id":"s9-78","number":78,"surah":9,"verses":[10],"verseLabel":"التوبة: 10","question":"لماذا أفرد ﴿مؤمن﴾ مع أن الحديث عن جماعة؟","answer":"أُفرد ﴿مؤمن﴾ في سياق النفي ليعم كل مؤمن واحدًا واحدًا؛ فهم لا يراعون الحرمة في أي فرد متصف بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص670–672.","url":""}]},{"id":"s9-79","number":79,"surah":9,"verses":[10],"verseLabel":"التوبة: 10","question":"لماذا ختم بقوله: ﴿وأولئك هم المعتدون﴾؟","answer":"اسم الإشارة وضمير الفصل يحصران الاعتداء فيهم ويثبتانه لهم بسبب تكرر النقض وعدم مراعاة إل ولا ذمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص671–674.","url":""}]},{"id":"s9-80","number":80,"surah":9,"verses":[11],"verseLabel":"التوبة: 11","question":"لماذا كرر شروط التوبة والصلاة والزكاة بعد ذكرها في الآية 5؟","answer":"في الآية الخامسة كانت الشروط سببًا لتخلية سبيلهم ووقف القتال، وهنا هي أساس دخولهم في أخوة الدين؛ فتكرر اللفظ واختلف الأثر المبني عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص674–677.","url":""}]},{"id":"s9-81","number":81,"surah":9,"verses":[11],"verseLabel":"التوبة: 11","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فإخوانكم في الدين﴾، وقال في الآية 5: ﴿فخلوا سبيلهم﴾؟","answer":"﴿فخلوا سبيلهم﴾ يبين زوال حكم القتال، أما ﴿فإخوانكم في الدين﴾ فيرتقي بهم إلى العضوية الكاملة في جماعة المؤمنين؛ فالثاني أبلغ في بيان أثر التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص676–680.","url":""}]},{"id":"s9-82","number":82,"surah":9,"verses":[11],"verseLabel":"التوبة: 11","question":"لماذا أضاف الأخوة إلى ﴿الدين﴾؟","answer":"أضيفت الأخوة إلى الدين لتحديد أساسها الجديد: العقيدة الجامعة، لا النسب أو الحلف، ولتقرير ما يترتب عليها من حقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص678–680.","url":""}]},{"id":"s9-83","number":83,"surah":9,"verses":[11],"verseLabel":"التوبة: 11","question":"لماذا ختم بـ﴿ونفصل الآيات لقوم يعلمون﴾؟","answer":"تفصيل الآيات يناسب تشعب أحكام العهد والتوبة والقتال، وخص به قوم يعلمون لأنهم الذين يتدبرون الفروق ويعملون بمقتضاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص680–684.","url":""}]},{"id":"s9-84","number":84,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن نكثوا أيمانهم﴾، فشبّه نقض العهد بنكث الحبل؟","answer":"النكث في الأصل حل فتل الحبل، فاستعير لنقض الأيمان بعد إحكامها؛ إذ يصير العهد المحكم كحبل فُكّت قواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص684–687.","url":""}]},{"id":"s9-85","number":85,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد عهدهم﴾ مع أن النكث لا يكون إلا بعد العهد؟","answer":"﴿من بعد عهدهم﴾ تؤكد شناعة النكث؛ فقد وقع بعد ميثاق ثابت مخصوص، لا قبل انعقاده أو عن جهل بوجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص686–688.","url":""}]},{"id":"s9-86","number":86,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"لماذا جمع بين نكث الأيمان والطعن في الدين؟","answer":"نكث الأيمان عدوان عملي على الجماعة، والطعن في الدين عدوان قولي على عقيدتها؛ فجمعا خيانة العهد ومحاربة أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص688–690.","url":""}]},{"id":"s9-87","number":87,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"لماذا عبّر عن الإساءة إلى الدين بـ﴿طعنوا في دينكم﴾؟","answer":"الطعن حقيقته الضرب بآلة نافذة، فاستعير للقدح الشديد في الدين؛ لما يحدثه من أذى ومحاولة تمزيق حرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص689–691.","url":""}]},{"id":"s9-88","number":88,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"لماذا سماهم ﴿أئمة الكفر﴾؟","answer":"سُموا أئمة الكفر لأنهم قادته الذين يبدؤون بالنكث والطعن ويحرضون أتباعهم؛ فقتالهم يوقف مصدر العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص691–694.","url":""}]},{"id":"s9-89","number":89,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿إنهم لا أيمان لهم﴾ بعد ذكر أيمانهم التي نكثوها؟","answer":"أثبتت لهم أيمان من حيث صدورها، ثم نفاها من حيث الاعتداد والوفاء؛ فالأيمان المنقوضة كأنها لا وجود لها، ويحتمل أن ﴿أيمان﴾ هنا بمعنى أمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص693–697.","url":""}]},{"id":"s9-90","number":90,"surah":9,"verses":[12],"verseLabel":"التوبة: 12","question":"لماذا خُتم القتال بقوله: ﴿لعلهم ينتهون﴾؟","answer":"غاية القتال أن ينتهوا عن النكث والطعن والعدوان، لا أن يكون القتل مطلوبًا لذاته؛ و﴿لعل﴾ تفتح إمكان رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص697–700.","url":""}]},{"id":"s9-91","number":91,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"لماذا افتتحت الآية بالتحضيض: ﴿ألا تقاتلون قومًا﴾؟","answer":"﴿ألا﴾ للتحضيض الشديد؛ تستنكر التردد في قتال قوم اجتمعت منهم أسباب القتال، وتحرك همة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص700–702.","url":""}]},{"id":"s9-92","number":92,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"لماذا سُردت جرائمهم: نكث الأيمان، والهم بإخراج الرسول، والبدء بالقتال؟","answer":"سرد الجرائم يبني الحجة من ثلاث جهات: نقض الحق، والعدوان على الرسول، والبدء بالحرب؛ فلا يبقى للتردد مسوغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص702–705.","url":""}]},{"id":"s9-93","number":93,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿هموا بإخراج الرسول﴾، دون أن يقال: «هموا بإخراج محمد»؟","answer":"اختير وصف ﴿الرسول﴾ لأن همهم بإخراجه جريمة متعلقة برسالته ودعوته، لا خصومة مع شخصه أو اسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص704–706.","url":""}]},{"id":"s9-94","number":94,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"ما سرّ تقديم الضمير في ﴿وهم بدءوكم أول مرة﴾؟","answer":"تقديم ﴿هم﴾ يفيد التوكيد والقصر: هم الذين بدأوا المسلمين، لا المسلمون؛ فيدفع شبهة كون القتال عدوانًا ابتدائيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص706–708.","url":""}]},{"id":"s9-95","number":95,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿أول مرة﴾ مع أن البدء لا يكون إلا أولًا؟","answer":"﴿أول مرة﴾ تعين واقعة البدء الأولى التي ترتبت عليها الوقائع التالية، وتؤكد أنهم أصحاب المبادأة منذ أصل النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707–709.","url":""}]},{"id":"s9-96","number":96,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"لماذا انتقل فجأة إلى السؤال: ﴿أتخشونهم﴾؟","answer":"انتقل إلى ﴿أتخشونهم﴾ لكشف علة التردد بعد ثبوت موجبات القتال؛ فالذي قد يبقى ليس نقص الحجة بل خوف الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص708–710.","url":""}]},{"id":"s9-97","number":97,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فالله أحق أن تخشوه﴾، فجاء باسم التفضيل؟","answer":"اسم التفضيل يقرر أن الخشية إن وقعت فالله أحق بها من العدو، وينقل النفس من موازنة القوى الظاهرة إلى حق الله المطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص709–711.","url":""}]},{"id":"s9-98","number":98,"surah":9,"verses":[13],"verseLabel":"التوبة: 13","question":"لماذا ختم بقوله: ﴿إن كنتم مؤمنين﴾؟","answer":"التعليق بالإيمان يستنهض مقتضاه؛ فالإيمان الحق يجعل خشية الله مقدمة ويمنع التخاذل عن أمره، وليس المراد نفي أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص710–712.","url":""}]},{"id":"s9-99","number":99,"surah":9,"verses":[14],"verseLabel":"التوبة: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿قاتلوهم يعذبهم الله بأيديكم﴾، فنسب الفعل إلى المؤمنين والعذاب إلى الله؟","answer":"المؤمنون يباشرون القتال بأيديهم، والله يجعله عذابًا مستحقًا وينفذ به حكمه؛ فنسبت المباشرة إليهم والتقدير والجزاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص712–715.","url":""}]},{"id":"s9-100","number":100,"surah":9,"verses":[14],"verseLabel":"التوبة: 14","question":"لماذا اختير ﴿يعذبهم﴾ لا «يهزمهم»؟","answer":"اختير ﴿يعذبهم﴾ لأن الهزيمة تصف النتيجة العسكرية فقط، أما التعذيب فيجعل ما ينزل بهم جزاءً على كفرهم وعدوانهم، ويشمل القتل والأسر والذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص714–716.","url":""}]},{"id":"s9-101","number":101,"surah":9,"verses":[14],"verseLabel":"التوبة: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿بأيديكم﴾ مع أن القتال يكون بآلات وسلاح؟","answer":"نسب الفعل إلى الأيدي لأنها آلة المباشرة في القتال وحمل السلاح، فذكرها كناية عن مباشرة المؤمنين أسباب العذاب بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص715–717.","url":""}]},{"id":"s9-102","number":102,"surah":9,"verses":[14],"verseLabel":"التوبة: 14","question":"لماذا جمع أربعة آثار للقتال: تعذيبهم، وإخزاؤهم، ونصر المؤمنين، وشفاء الصدور؟","answer":"جمعت الآثار استيفاءً لوجهي الجزاء: ما يصيب العدو من عذاب وخزي، وما يناله المؤمنون من نصر وشفاء؛ فظهر أثر القتال في الخارج والنفس معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص716–720.","url":""}]},{"id":"s9-103","number":103,"surah":9,"verses":[14],"verseLabel":"التوبة: 14","question":"لماذا عبّر عن إزالة الألم بقوله: ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"شُبه زوال ألم المؤمنين وغيظهم بشفاء المريض؛ لأن أذى المشركين استقر في صدورهم كالداء، فجاء النصر علاجًا يزيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص719–722.","url":""}]},{"id":"s9-104","number":104,"surah":9,"verses":[14],"verseLabel":"التوبة: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿قوم مؤمنين﴾، دون أن يقال: «صدوركم»؟","answer":"جيء بـ﴿قوم مؤمنين﴾ لتشريفهم بوصف الإيمان، ولتعميم الشفاء في كل من آذاه المشركون من المؤمنين، لا المخاطبين الحاضرين وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص721–723.","url":""}]},{"id":"s9-105","number":105,"surah":9,"verses":[15],"verseLabel":"التوبة: 15","question":"لماذا أفرد ذهاب الغيظ في آية مستقلة بعد شفاء الصدور؟","answer":"أُفرد ذهاب الغيظ لأنه أثر زائد بعد الشفاء: فالشفاء إزالة ألم الصدر، وذهاب الغيظ إزالة حرارة الغضب؛ واستقلال الآية يبرز تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص723–725.","url":""}]},{"id":"s9-106","number":106,"surah":9,"verses":[15],"verseLabel":"التوبة: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿غيظ قلوبهم﴾ بعد قوله: ﴿صدور قوم مؤمنين﴾؟","answer":"الصدور وعاء المشاعر وآثار الأذى، والقلوب محل الغيظ نفسه؛ فانتقل من الموضع الأوسع إلى مركز الشعور الباطن عند بيان زواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص724–726.","url":""}]},{"id":"s9-107","number":107,"surah":9,"verses":[15],"verseLabel":"التوبة: 15","question":"لماذا جاء بعد القتال قوله: ﴿ويتوب الله على من يشاء﴾؟","answer":"ذكر التوبة بعد القتال يبين أن الباب لا يغلق على العدو؛ فقد يهديه ما يرى من نصر الحق وعدله، فيتحول من محارب إلى مؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص725–727.","url":""}]},{"id":"s9-108","number":108,"surah":9,"verses":[15],"verseLabel":"التوبة: 15","question":"لماذا عُلقت التوبة بالمشيئة؟","answer":"عُلقت بالمشيئة لأن هداية القلوب وتوفيقها للتوبة بيد الله، وهو يعلم من يصلح لها؛ فلا يلزم من وقوع القتال توبة كل أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص726–728.","url":""}]},{"id":"s9-109","number":109,"surah":9,"verses":[15],"verseLabel":"التوبة: 15","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بمن يستحق الهداية وبما في القلوب، و﴿حكيم﴾ في النصر والتعذيب والتوبة؛ فكل حكم موضوع في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص727–728.","url":""}]},{"id":"s9-110","number":110,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿أم حسبتم أن تتركوا﴾ بعد أوامر القتال؟","answer":"﴿أم حسبتم﴾ تنكر ظن أن يتركوا بلا اختبار بعد أمر القتال؛ فالدعوى لا تكفي حتى يظهر صدق الجهاد والولاء بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص729–732.","url":""}]},{"id":"s9-111","number":111,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما يعلم الله الذين جاهدوا منكم﴾ مع أن الله يعلمهم قبل الجهاد؟","answer":"ليس المراد حدوث علم بعد جهل، بل ظهور المعلوم في عالم العمل ليتميز المجاهد المخلص وتقوم عليه الحجة ويترتب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص731–734.","url":""}]},{"id":"s9-112","number":112,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"لماذا اختيرت ﴿لما﴾ بدل «لم»؟","answer":"﴿لما﴾ تنفي وقوع العلم المتعلق بظهور العمل إلى زمن الكلام مع توقع وقوعه بعد الاختبار، بخلاف ﴿لم﴾ التي لا تتضمن هذا التوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص733–735.","url":""}]},{"id":"s9-113","number":113,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"لماذا جمع بين الجهاد وعدم اتخاذ الوليجة؟","answer":"الجهاد يختبر العمل الظاهر، وترك الوليجة يختبر الولاء الباطن؛ فجمعهما لاستكمال صدق المؤمن في فعله وسره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص735–737.","url":""}]},{"id":"s9-114","number":114,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"ما الصورة في قوله: ﴿ولم يتخذوا... وليجة﴾؟","answer":"الوليجة من يدخل في باطن الأمر والسر؛ وفي اللفظ صورة لبطانة تتغلغل داخل الجماعة، فالنهي عن اتخاذ بطانة ولاؤها خارج الله ورسوله والمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص736–738.","url":""}]},{"id":"s9-115","number":115,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"لماذا فصّل: ﴿من دون الله ولا رسوله ولا المؤمنين﴾؟","answer":"فصل الجهات الثلاث لتعظيم حق الله، وحق رسوله، وحق جماعة المؤمنين، ولنفي كل وليجة تتجاوز أيًا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص737–739.","url":""}]},{"id":"s9-116","number":116,"surah":9,"verses":[16],"verseLabel":"التوبة: 16","question":"لماذا ختم بـ﴿والله خبير بما تعملون﴾ لا «عليم»؟","answer":"الخبير هو العالم بدقائق الأمور وبواطنها، وهو أنسب بموضع اختبار الوليجة والنيات المستترة من الاسم الأعم ﴿عليم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص739–740.","url":""}]},{"id":"s9-117","number":117,"surah":9,"verses":[17],"verseLabel":"التوبة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان للمشركين أن يعمروا مساجد الله﴾، دون أن يقال: «لا يعمر المشركون»؟","answer":"صيغة ﴿ما كان لهم أن﴾ تنفي استحقاقهم وصلاحيتهم للعمارة، لا مجرد وقوع الفعل؛ فالشرك يناقض عمارة مسجد بني لعبادة الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص740–743.","url":""}]},{"id":"s9-118","number":118,"surah":9,"verses":[17],"verseLabel":"التوبة: 17","question":"كيف يعمر المشركون المسجد وهم الذين بنوه وخدموه؟","answer":"قد يقومون بالبناء والخدمة الحسية، لكن العمارة المعتبرة تجمع البناء والعبادة والتوحيد؛ وشهادتهم بالكفر تبطل القيمة الدينية لما يفعلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص742–745.","url":""}]},{"id":"s9-119","number":119,"surah":9,"verses":[17],"verseLabel":"التوبة: 17","question":"لماذا وصفهم بأنهم ﴿شاهدين على أنفسهم بالكفر﴾؟","answer":"حالهم وأقوالهم وعبادتهم للأوثان شهادة عملية وقولية على كفرهم، فلا يجتمع إقرارهم به مع أهلية عمارة مساجد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص744–747.","url":""}]},{"id":"s9-120","number":120,"surah":9,"verses":[17],"verseLabel":"التوبة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم﴾ مع وجود أعمال نافعة ظاهرًا؟","answer":"حبطت أعمالهم أي بطل ثوابها وآثارها الأخروية بسبب الكفر، وإن ظهر لبعضها نفع دنيوي؛ فالعمل لا يقبل دون أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص746–748.","url":""}]},{"id":"s9-121","number":121,"surah":9,"verses":[17],"verseLabel":"التوبة: 17","question":"لماذا انتقل من حبوط الأعمال إلى الخلود في النار؟","answer":"الحبوط يبين بطلان ما ظنوه رصيدًا من الأعمال، والخلود يبين العاقبة المقابلة؛ فلا ثواب لهم بل إقامة دائمة في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص748–751.","url":""}]},{"id":"s9-122","number":122,"surah":9,"verses":[18],"verseLabel":"التوبة: 18","question":"لماذا قصر عمارة المساجد بقوله: ﴿إنما يعمر مساجد الله من آمن بالله﴾؟","answer":"القصر يرد دعوى المشركين في استحقاق العمارة، ويثبتها لمن جمع الإيمان والعبادة والخشية؛ فليست العمارة مجرد خدمة مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص751–754.","url":""}]},{"id":"s9-123","number":123,"surah":9,"verses":[18],"verseLabel":"التوبة: 18","question":"لماذا جمع في عُمّار المساجد بين الإيمان والصلاة والزكاة والخشية؟","answer":"الإيمان أصل صحة العمل، والصلاة عمارة المسجد بالعبادة، والزكاة برهان البذل، والخشية تحفظ الإخلاص؛ فاجتمعت أصول الاعتقاد والعمل الباطن والظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص753–757.","url":""}]},{"id":"s9-124","number":124,"surah":9,"verses":[18],"verseLabel":"التوبة: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يخش إلا الله﴾ مع أن الخوف الطبيعي من الناس واقع؟","answer":"المنفي خشية العبادة والطاعة التي تحمل على مخالفة الله، لا الخوف الجبلي من ضرر محسوس؛ فالقصر متعلق بخشية التعظيم والانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص757–760.","url":""}]},{"id":"s9-125","number":125,"surah":9,"verses":[18],"verseLabel":"التوبة: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿فعسى أولئك أن يكونوا من المهتدين﴾ مع تحقق صفاتهم؟","answer":"﴿عسى﴾ من الله وعد، وجاءت بصيغة الرجاء لتبقي العامل بين الخوف والرجاء، فلا يغتر بعمله، ولتدل على أن الهداية فضل لا استحقاق ذاتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص760–764.","url":""}]},{"id":"s9-126","number":126,"surah":9,"verses":[19],"verseLabel":"التوبة: 19","question":"لماذا سأل: ﴿أجعلتم سقاية الحاج وعمارة المسجد الحرام كمن آمن بالله...﴾ مع أن الأعمال كلها خير؟","answer":"السقاية والعمارة خير إذا صدرتا عن إيمان، لكنهما مع الشرك لا تساويان الإيمان والجهاد؛ فالاستفهام ينكر التسوية بين ظاهر خدمة البيت وحقيقة عبادة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص764–767.","url":""}]},{"id":"s9-127","number":127,"surah":9,"verses":[19],"verseLabel":"التوبة: 19","question":"لماذا قورنت أعمال مادية بأشخاص مؤمنين، لا بأعمالهم؟","answer":"المقارنة على حذف مضاف: أجعلتم أهل السقاية والعمارة كمن آمن، أو جُعل المصدر بمعنى صاحبه؛ والمقصود مقارنة أصحاب العملين لا العمل المجرد بالشخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص766–769.","url":""}]},{"id":"s9-128","number":128,"surah":9,"verses":[19],"verseLabel":"التوبة: 19","question":"ما سرّ تقديم الإيمان بالله واليوم الآخر على الجهاد؟","answer":"قُدم الإيمان لأنه الأساس الذي يصحح الجهاد ويحدد غايته؛ فلا قيمة لبذل أو قتال منفصل عن الإيمان بالله والجزاء الأخروي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص768–771.","url":""}]},{"id":"s9-129","number":129,"surah":9,"verses":[19],"verseLabel":"التوبة: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يستوون عند الله﴾، دون أن يقال: «ليسوا سواء»؟","answer":"الفعل المضارع ﴿لا يستوون﴾ ينفي تجدد المساواة وثبوتها في ميزان الله، و﴿عند الله﴾ يحدد الميزان الحق لا مقاييس الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص770–772.","url":""}]},{"id":"s9-130","number":130,"surah":9,"verses":[19],"verseLabel":"التوبة: 19","question":"لماذا ختم بـ﴿والله لا يهدي القوم الظالمين﴾؟","answer":"من سوّى بين الشرك والإيمان ووضع العمل في غير منزلته فقد ظلم، وعدم هدايته جزاء إصراره ويؤكد بطلان هذه التسوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص771–773.","url":""}]},{"id":"s9-131","number":131,"surah":9,"verses":[20],"verseLabel":"التوبة: 20","question":"لماذا أعاد صفات الإيمان والهجرة والجهاد بعد ذكرها في الآية السابقة؟","answer":"الآية السابقة نفت المساواة إجمالًا، وهذه عينت أصحاب الدرجة الأعظم وقررت فوزهم؛ فالإعادة انتقال من المقارنة إلى الثناء والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص773–776.","url":""}]},{"id":"s9-132","number":132,"surah":9,"verses":[20],"verseLabel":"التوبة: 20","question":"ما سرّ تقديم الجهاد بالأموال على الأنفس؟","answer":"قُدم المال لأنه أيسر بذلًا وأكثر تكررًا وحاجة الجهاد إليه مستمرة، ثم ذكرت النفس وهي الغاية القصوى في التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص775–778.","url":""}]},{"id":"s9-133","number":133,"surah":9,"verses":[20],"verseLabel":"التوبة: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿أعظم درجة عند الله﴾ ولم يذكر الطرف الآخر؟","answer":"حذف الطرف الآخر لوضوحه من الآية السابقة، وللعناية بإثبات عظم درجة المؤمنين دون إعادة ذكر من لا يساويهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص777–780.","url":""}]},{"id":"s9-134","number":134,"surah":9,"verses":[20],"verseLabel":"التوبة: 20","question":"لماذا أفرد ﴿درجة﴾ مع تفاوت منازل المؤمنين؟","answer":"أُفردت ﴿درجة﴾ باعتبار جنس المنزلة أو الرتبة الجامعة لهم في مقابلة غيرهم، مع تفاوت درجاتهم داخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص779–782.","url":""}]},{"id":"s9-135","number":135,"surah":9,"verses":[20],"verseLabel":"التوبة: 20","question":"لماذا جاء القصر: ﴿وأولئك هم الفائزون﴾؟","answer":"اسم الإشارة وضمير الفصل يقصران الفوز الحقيقي عليهم؛ لأنهم جمعوا الإيمان والهجرة والجهاد، لا أصحاب المفاخر الظاهرة الخالية من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص781–784.","url":""}]},{"id":"s9-136","number":136,"surah":9,"verses":[72],"verseLabel":"التوبة: 20؛ الأنفال: 72","question":"ما سرّ التعبير في قوله تعالى في التوبة: ﴿وجاهدوا في سبيل الله بأموالهم وأنفسهم﴾، بينما قدم في الأنفال: ﴿بأموالهم وأنفسهم في سبيل الله﴾؟","answer":"قُدّم ﴿في سبيل الله﴾ في التوبة لأن ذكر الجهاد سبق فيها وتكرر، أما الأنفال فقد سبق فيها ذكر الفداء والغنيمة وعرض الدنيا، فقدم المال مراعاة لمحور السياق.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص132–133؛ والنص الرقمي المحقق: https://islamweb.net/ar/library/content/224/9/.","url":""}]},{"id":"s9-137","number":137,"surah":9,"verses":[21],"verseLabel":"التوبة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يبشرهم ربهم﴾، فاختار اسم الرب؟","answer":"اختير ﴿ربهم﴾ لاستحضار الرعاية والتربية والإنعام؛ فهو الذي تولى أمرهم حتى بلغهم منازل البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص784–787.","url":""}]},{"id":"s9-138","number":138,"surah":9,"verses":[21],"verseLabel":"التوبة: 21","question":"لماذا جمع في البشارة بين الرحمة والرضوان والجنات؟","answer":"الرحمة ترفع عنهم الضر، والرضوان غاية القبول والقرب، والجنات دار النعيم؛ فجمعت البشارة سلامة الحال ورضا المنعم ومكان الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص786–789.","url":""}]},{"id":"s9-139","number":139,"surah":9,"verses":[21],"verseLabel":"التوبة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿برحمة منه﴾ مع أن كل رحمة منه؟","answer":"﴿منه﴾ تؤكد أن الرحمة عطاء خاص صادر من عنده لا سبب مستقل عنه، وفيها تعظيم لقرب المنحة وشرف مصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص788–790.","url":""}]},{"id":"s9-140","number":140,"surah":9,"verses":[21],"verseLabel":"التوبة: 21","question":"لماذا نكّر ﴿رحمة﴾ و﴿رضوان﴾؟","answer":"نُكرتا للتعظيم والتفخيم: رحمة عظيمة لا يحيط بها الوصف، ورضوان كبير يفوق ما يتصوره المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص789–791.","url":""}]},{"id":"s9-141","number":141,"surah":9,"verses":[21],"verseLabel":"التوبة: 21","question":"لماذا وصف النعيم بأنه ﴿مقيم﴾؟","answer":"وُصف النعيم بالمقيم لأنه ثابت لا يزول ولا ينتقل عن صاحبه، خلاف نعيم الدنيا العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص790–793.","url":""}]},{"id":"s9-142","number":142,"surah":9,"verses":[22],"verseLabel":"التوبة: 22","question":"لماذا جمع بين ﴿خالدين فيها﴾ و﴿أبدًا﴾؟","answer":"﴿خالدين﴾ تثبت طول الإقامة، و﴿أبدًا﴾ تنفي أن يكون لها نهاية مهما امتد الزمن؛ فالثاني يقطع كل احتمال للانقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص792–795.","url":""}]},{"id":"s9-143","number":143,"surah":9,"verses":[22],"verseLabel":"التوبة: 22","question":"لماذا ختمت هذه الصفات بقوله: ﴿إن الله عنده أجر عظيم﴾؟","answer":"الخاتمة تعلل عظم ما بُشروا به؛ فما عند الله من الرحمة والرضوان والجنة أجر عظيم قدرًا ودوامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص794–799.","url":""}]},{"id":"s9-144","number":144,"surah":9,"verses":[23],"verseLabel":"التوبة: 23","question":"لماذا خُص الأبناء والإخوة بالنهي عن اتخاذهم أولياء إذا استحبوا الكفر؟","answer":"خُص الآباء والإخوان لأنهما من أقوى روابط النسب وأشدها تأثيرًا في الولاء، فإذا منع استحباب الكفر ولايتهما فمن دونهما أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص10–13.","url":""}]},{"id":"s9-145","number":145,"surah":9,"verses":[23],"verseLabel":"التوبة: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿استحبوا الكفر على الإيمان﴾، دون أن يقال: «اختاروا الكفر»؟","answer":"﴿استحبوا﴾ تفيد أنهم طلبوا محبة الكفر وآثروه عن رغبة، لا أنهم اختاروه اختيارًا عابرًا؛ وفيها تصوير رسوخ ميلهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص12–15.","url":""}]},{"id":"s9-146","number":146,"surah":9,"verses":[23],"verseLabel":"التوبة: 23","question":"لماذا عُدي ﴿استحبوا﴾ بـ﴿على﴾؟","answer":"عدي بـ﴿على﴾ لتضمين الاستحباب معنى الإيثار والتفضيل؛ أي قدموا الكفر ورفعوه فوق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص14–16.","url":""}]},{"id":"s9-147","number":147,"surah":9,"verses":[23],"verseLabel":"التوبة: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يتولهم منكم فأولئك هم الظالمون﴾، دون أن يقال: «فهو ظالم»؟","answer":"أفرد الشرط ﴿من﴾ ثم جمع الجزاء في ﴿فأولئك هم الظالمون﴾ لإدخال كل فرد يفعل ذلك في جماعة الظالمين، مع تقوية الحكم بالإشارة والفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص16–19.","url":""}]},{"id":"s9-148","number":148,"surah":9,"verses":[23],"verseLabel":"التوبة: 23","question":"لماذا وصفهم بالظلم لا بالكفر؟","answer":"وصفوا بالظلم لأن المؤمن الذي يواليهم يضع الولاء في غير موضعه ويظلم نفسه وجماعته؛ ولا يلزم أن تكون كل صورة من الموالاة كفرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص18–20.","url":""}]},{"id":"s9-149","number":149,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"لماذا عدّد الآباء والأبناء والإخوان والأزواج والعشيرة والأموال والتجارة والمساكن؟","answer":"عُددت لتستوعب أهم محبوبات الإنسان: أصوله وفروعه وإخوته وأزواجه وعشيرته وماله وكسبه ومسكنه، فلا يبقى محبوب يتذرع به لتقديمه على أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص21–25.","url":""}]},{"id":"s9-150","number":150,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"لماذا انتقل من القرابات إلى الأموال ثم التجارة ثم المساكن؟","answer":"انتقل من الروابط البشرية إلى المال المملوك، ثم إلى نمائه المتوقع في التجارة، ثم إلى محل الاستقرار؛ فتدرج في دوائر التعلق من الأشخاص إلى أسباب العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص24–27.","url":""}]},{"id":"s9-151","number":151,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"لماذا وصف الأموال بـ﴿اقترفتموها﴾؟","answer":"الاقتراف هو الاكتساب مع مباشرة وجهد، وقد يستعمل فيما يلابسه تبعة؛ فذكره يوقظ تعلق النفس بمال جمعته بنفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص26–28.","url":""}]},{"id":"s9-152","number":152,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿وتجارة تخشون كسادها﴾، فجعل الخشية من الكساد لا من الخسارة؟","answer":"الكساد بوار التجارة وتوقف رواجها، وهو الذي يخشاه التاجر قبل تحقق الخسارة؛ فالتعبير يلتقط موطن قلقه الدائم على حركة ماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص28–30.","url":""}]},{"id":"s9-153","number":153,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿ومساكن ترضونها﴾ لا «تحبونها»؟","answer":"الرضا بالمساكن يجمع محبتها وملاءمتها وسكون النفس إليها، فهو أدق في تصوير الاطمئنان بالمكان من مطلق الحب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29–31.","url":""}]},{"id":"s9-154","number":154,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"لماذا جمع بين محبة الله ومحبة الرسول والجهاد في سبيله؟","answer":"محبة الله أصل الإيمان، ومحبة الرسول تقتضي اتباعه، والجهاد برهان تقديم المحبتين على محبوبات النفس؛ فجمع المصدر والبلاغ ودليل الصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص30–32.","url":""}]},{"id":"s9-155","number":155,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿فتربصوا حتى يأتي الله بأمره﴾، ولم يصرح بالعقوبة؟","answer":"﴿فتربصوا﴾ تهديد يترك العقوبة مبهمة، فيذهب الوهم في صورها ويزيد هول انتظار أمر الله الذي لا يرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص32–34.","url":""}]},{"id":"s9-156","number":156,"surah":9,"verses":[24],"verseLabel":"التوبة: 24","question":"لماذا ختم بـ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"تقديم المحبوبات على الله ورسوله والجهاد خروج عن مقتضى الطاعة، فناسب وصف الفسق، وعدم الهداية نتيجة الإصرار عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص34–35.","url":""}]},{"id":"s9-157","number":157,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد نصركم الله في مواطن كثيرة﴾ قبل ذكر هزيمة أول المعركة في حنين؟","answer":"قُدمت المواطن الكثيرة لتذكيرهم بأن النصر عادة فضل من الله لا ثمرة العدد، ثم ذكرت عثرة حنين لتصحح لحظة الاغترار بالكثرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص36–38.","url":""}]},{"id":"s9-158","number":158,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"لماذا سُمّيت مواقع القتال ﴿مواطن﴾؟","answer":"المواطن هي أماكن الإقامة والوقوف، فسميت بها مواقع القتال لأن الجيوش تستقر فيها وتباشر مواقفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص37–39.","url":""}]},{"id":"s9-159","number":159,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"لماذا خُص يوم حنين بالذكر بعد إجمال المواطن الكثيرة؟","answer":"خُص حنين لأن بدايته كشفت عجز الكثرة حين أعجبتهم، ثم أظهر نهايته عودة النصر بإنزال السكينة؛ فهو شاهد عملي على المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص38–40.","url":""}]},{"id":"s9-160","number":160,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ أعجبتكم كثرتكم﴾، فنسب الإعجاب إليهم لا إلى الكثرة؟","answer":"نسب الإعجاب إليهم لأنه فعل قلبي صدر منهم تجاه الكثرة؛ فليست الكثرة في ذاتها مذمومة، وإنما الاعتماد النفسي عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص39–41.","url":""}]},{"id":"s9-161","number":161,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿فلم تغن عنكم شيئًا﴾، ونكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم أقل إغناء؛ فلم تدفع الكثرة عنهم ضررًا ولا حققت نصرًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص40–42.","url":""}]},{"id":"s9-162","number":162,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"ما الصورة في قوله: ﴿وضاقت عليكم الأرض بما رحبت﴾؟","answer":"صوّر شدة الحيرة والخوف بأن الأرض الواسعة ضاقت بهم فلم يجدوا مهربًا؛ فجمع بين حقيقة سعتها وشعورهم بانغلاقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص41–43.","url":""}]},{"id":"s9-163","number":163,"surah":9,"verses":[25],"verseLabel":"التوبة: 25","question":"لماذا جمع بين ﴿وليتم﴾ و﴿مدبرين﴾؟","answer":"﴿وليتم﴾ يثبت فعل الانصراف، و﴿مدبرين﴾ يصور هيئتهم وهم يعطون العدو أدبارهم؛ فالثاني يؤكد الأول ويجسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص43–44.","url":""}]},{"id":"s9-164","number":164,"surah":9,"verses":[26],"verseLabel":"التوبة: 26","question":"لماذا عبّر عن الطمأنينة بقوله: ﴿أنزل الله سكينته﴾؟","answer":"صُورت السكينة شيئًا منزلًا من عند الله يستقر في القلوب، لبيان مصدرها وكونها عطية فوق الأسباب البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص45–48.","url":""}]},{"id":"s9-165","number":165,"surah":9,"verses":[26],"verseLabel":"التوبة: 26","question":"لماذا خص الرسول والمؤمنين بالسكينة بعد أن كان الخطاب للجميع؟","answer":"خص الرسول ومن ثبت معه من المؤمنين؛ لأن السكينة نزلت على من كان في قلبه إيمان يقبلها، وفي التخصيص تمييز لهم ممن غلبه الاضطراب أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص47–49.","url":""}]},{"id":"s9-166","number":166,"surah":9,"verses":[26],"verseLabel":"التوبة: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنزل جنودًا لم تروها﴾ ولم يسم الملائكة؟","answer":"أبهم الجنود لتعظيمهم وتوسيع ما يدخل في جنود الله، والمقصود أثر القوة الغيبية التي لم تقع عليها أبصارهم، لا مجرد تسمية الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص49–51.","url":""}]},{"id":"s9-167","number":167,"surah":9,"verses":[26],"verseLabel":"التوبة: 26","question":"لماذا جمع بين إنزال السكينة وإنزال الجنود؟","answer":"السكينة مدد للقلوب من الداخل، والجنود مدد للموقف من الخارج؛ فجمع تثبيت النفس وتقوية الصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص50–52.","url":""}]},{"id":"s9-168","number":168,"surah":9,"verses":[26],"verseLabel":"التوبة: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿وعذب الذين كفروا﴾ بعد ذكر النصر؟","answer":"ذكر عذاب الكافرين يبين الوجه الآخر للنصر: لم يكن نجاة المؤمنين فقط، بل جزاءً للعدو على كفره وعدوانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص52–53.","url":""}]},{"id":"s9-169","number":169,"surah":9,"verses":[26],"verseLabel":"التوبة: 26","question":"لماذا ختم بـ﴿وذلك جزاء الكافرين﴾؟","answer":"اسم الإشارة يعظم العذاب المشاهد ويربطه بعلته، ثم يقرر أنه جزاء جنس الكافرين لا حادثة بلا حكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص53–54.","url":""}]},{"id":"s9-170","number":170,"surah":9,"verses":[27],"verseLabel":"التوبة: 27","question":"لماذا جاء بعد عذاب الكافرين مباشرة: ﴿ثم يتوب الله من بعد ذلك على من يشاء﴾؟","answer":"جاءت التوبة بعد العذاب لتبين أن الجزاء الدنيوي لا يغلق باب الهداية، وأن من بقي منهم قد يرجع فيقبله الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص55–58.","url":""}]},{"id":"s9-171","number":171,"surah":9,"verses":[27],"verseLabel":"التوبة: 27","question":"لماذا استُعملت ﴿ثم﴾ قبل التوبة؟","answer":"﴿ثم﴾ تفيد تراخي رتبة التوبة عن مشهد القتال والعذاب وانتقال السياق إلى طور جديد، وقد يقع أثر الهداية بعد انكشاف الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص57–59.","url":""}]},{"id":"s9-172","number":172,"surah":9,"verses":[27],"verseLabel":"التوبة: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ذلك﴾ مع دلالة ﴿ثم﴾ على التراخي؟","answer":"﴿من بعد ذلك﴾ يثبت أن التوبة ممكنة عقب تلك الأحداث الشديدة نفسها، ويستحضر المشار إليه كاملًا قبل فتح باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص59–61.","url":""}]},{"id":"s9-173","number":173,"surah":9,"verses":[27],"verseLabel":"التوبة: 27","question":"لماذا ختم بـ﴿والله غفور رحيم﴾؟","answer":"﴿غفور﴾ يمحو ما سبق من الكفر والعداء، و﴿رحيم﴾ يتفضل على التائب بعد المغفرة؛ فناسبا فتح الباب بعد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص61–63.","url":""}]},{"id":"s9-174","number":174,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"لماذا وصف المشركين بأنهم ﴿نجس﴾ بالمصدر المفرد، لا «أنجاس»؟","answer":"أخبر بالمصدر المفرد ﴿نجس﴾ للمبالغة، كأن حقيقتهم عين النجاسة المعنوية، والمصدر لا يثنى ولا يجمع فاستوى فيه الجمع والمفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص64–68.","url":""}]},{"id":"s9-175","number":175,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"لماذا رُتّب منعهم من المسجد الحرام على وصف النجاسة بالفاء؟","answer":"الفاء تفيد أن منعهم مترتب على وصف الشرك والنجاسة المعنوية، فالحكم ليس لمجرد جنس أو قومية بل لعلة مذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص67–70.","url":""}]},{"id":"s9-176","number":176,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا يقربوا المسجد الحرام﴾، دون أن يقال: «فلا يدخلوه»؟","answer":"النهي عن القرب أبلغ من النهي عن الدخول؛ لأنه يمنع مقدماته والاقتراب من حرم المسجد، لا مجرد تجاوز بابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص69–72.","url":""}]},{"id":"s9-177","number":177,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"لماذا قُيّد المنع بقوله: ﴿بعد عامهم هذا﴾؟","answer":"القيد أعطاهم مهلة العام الذي وقع فيه الإعلان، ليبلغهم الحكم وتستقر ترتيبات الحج، ثم يبدأ المنع بعده دون مباغتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص71–74.","url":""}]},{"id":"s9-178","number":178,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"لماذا واجه خوف الفقر صراحة: ﴿وإن خفتم عيلة﴾؟","answer":"صرح بالخوف لأنه كان شبهة واقعية: انقطاع تجارة المشركين قد يسبب الفقر؛ فواجهها الوحي بوعد يحرر الطاعة من ضغط المصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص74–77.","url":""}]},{"id":"s9-179","number":179,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿فسوف يغنيكم الله من فضله﴾، فأدخل السين وسوف؟","answer":"الفاء تربط الغنى بالطاعة، و﴿سوف﴾ تؤكد الوعد مع مهلة تقتضيها سنن الرزق؛ فلا يلزم أن يقع الإغناء في اللحظة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص77–80.","url":""}]},{"id":"s9-180","number":180,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"لماذا قيد الإغناء بقوله: ﴿إن شاء﴾؟","answer":"قُيد بالمشيئة لتبقى القلوب معلقة بالله لا بالوعد المادي وحده، ولأن كيفية الغنى وزمانه ومقداره تابعة لحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص80–82.","url":""}]},{"id":"s9-181","number":181,"surah":9,"verses":[28],"verseLabel":"التوبة: 28","question":"لماذا ختم بـ﴿إن الله عليم حكيم﴾ لا «غني كريم»؟","answer":"﴿عليم﴾ بحاجتهم ومصالحهم، و﴿حكيم﴾ في توقيت المنع والإغناء وتقديره؛ وهما أنسب بشرط المشيئة وتشريع الحكم من وصف الغنى وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص82–87.","url":""}]},{"id":"s9-182","number":182,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"لماذا فصّل أوصاف الذين يقاتلون: لا يؤمنون بالله ولا باليوم الآخر ولا يحرمون ما حرم الله ولا يدينون دين الحق؟","answer":"فصل الأوصاف لإظهار تعدد أصول مخالفتهم التي تبرر الحكم: خلل الاعتقاد بالبدء والمعاد، وخلل التشريع، وخلل الانقياد لدين الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص88–93.","url":""}]},{"id":"s9-183","number":183,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿ما حرم الله ورسوله﴾، فأعاد الرسول في التحريم؟","answer":"تحريم الرسول بيان وتبليغ لتحريم الله، فذكره يثبت حجية سنته في التشريع، مع كون المصدر الأعلى للحكم هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص92–95.","url":""}]},{"id":"s9-184","number":184,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"لماذا عبّر بـ﴿ولا يدينون دين الحق﴾، ولم يقل: «ولا يتبعون الإسلام»؟","answer":"الدين هنا الانقياد والطاعة، و﴿دين الحق﴾ أوسع من اسم علم؛ فهو يصف المنهج الذي يجب أن يخضع له الإنسان اعتقادًا وحكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص94–97.","url":""}]},{"id":"s9-185","number":185,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿من الذين أوتوا الكتاب﴾، دون أن يقال: «أهل الكتاب»؟","answer":"﴿الذين أوتوا الكتاب﴾ تذكرهم بالنعمة والحجة التي أعطوها ثم خالفوها، فتقيم التناقض بين إيتاء الوحي وعدم اتباع الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص96–99.","url":""}]},{"id":"s9-186","number":186,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يعطوا الجزية﴾، فجعل الغاية إعطاءها لا مجرد قبولها؟","answer":"جُعلت الغاية الإعطاء الفعلي لأن مجرد القبول القولي لا يثبت الدخول في النظام والوفاء بالتزامه؛ فالحكم ينتهي عند تحقق الأداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص99–102.","url":""}]},{"id":"s9-187","number":187,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"ما معنى الصورة في قوله: ﴿عن يد﴾، ولماذا لم يقل: «يدفعوا الجزية»؟","answer":"﴿عن يد﴾ تحتمل الدفع المباشر عن قدرة، أو عن انقياد والتزام، وتصور تسليم الجزية تسليمًا ظاهرًا لا وعدًا مؤجلًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص101–104.","url":""}]},{"id":"s9-188","number":188,"surah":9,"verses":[29],"verseLabel":"التوبة: 29","question":"لماذا ختم بـ﴿وهم صاغرون﴾؟","answer":"﴿وهم صاغرون﴾ تبين خضوعهم لحكم الدولة وامتناعهم عن محاربتها، فلا تكون الجزية مالًا بلا اعتراف بسلطان النظام العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص104–106.","url":""}]},{"id":"s9-189","number":189,"surah":9,"verses":[30],"verseLabel":"التوبة: 30","question":"لماذا عبّر عن قول طائفة من اليهود بصيغة الجنس: ﴿وقالت اليهود عزير ابن الله﴾؟","answer":"أسند قول بعضهم إلى اسم الجنس لأن الطائفة القائلة صدرت عن الجماعة وانتسب قولها إليها، ولأن بقية اليهود لم تتبرأ منه في المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص107–110.","url":""}]},{"id":"s9-190","number":190,"surah":9,"verses":[30],"verseLabel":"التوبة: 30","question":"لماذا وازن بين قول اليهود في عزير وقول النصارى في المسيح؟","answer":"وازن بينهما لأن القولين يشتركان في رفع بشر إلى البنوة الإلهية، مع اختلاف الشخص والطائفة؛ فجمعهما يكشف أصل الانحراف الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص109–112.","url":""}]},{"id":"s9-191","number":191,"surah":9,"verses":[30],"verseLabel":"التوبة: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك قولهم بأفواههم﴾ مع أن كل قول يكون بالفم؟","answer":"﴿بأفواههم﴾ يقرر أنه قول لا يقوم عليه برهان ولا حقيقة وراء الألفاظ، ويشعر بأنه مجرد جرأة لسانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص111–114.","url":""}]},{"id":"s9-192","number":192,"surah":9,"verses":[30],"verseLabel":"التوبة: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿يضاهئون قول الذين كفروا من قبل﴾؟","answer":"المضاهاة المشابهة؛ أي يشابه قولهم أقوال أمم كافرة سبقتهم في نسبة الولد أو تأليه البشر، فليست شبهتهم وحيًا من كتبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص113–116.","url":""}]},{"id":"s9-193","number":193,"surah":9,"verses":[30],"verseLabel":"التوبة: 30","question":"لماذا جاء الدعاء عليهم بصيغة الخبر: ﴿قاتلهم الله﴾؟","answer":"﴿قاتلهم الله﴾ دعاء عليهم في صورة خبر يفيد التعجب من شناعة قولهم والاستحقاق المؤكد للعقوبة، لا إخبارًا بقتال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص116–118.","url":""}]},{"id":"s9-194","number":194,"surah":9,"verses":[30],"verseLabel":"التوبة: 30","question":"لماذا ختم بالتعجب: ﴿أنى يؤفكون﴾؟","answer":"﴿أنى﴾ تستفهم تعجبًا وإنكارًا عن الجهة التي يصرفون إليها عن الحق مع وضوح بطلان قولهم؛ فصورت شدة انقلابهم عن الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص118–120.","url":""}]},{"id":"s9-195","number":195,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"كيف اتخذ أهل الكتاب أحبارهم ورهبانهم أربابًا مع أنهم لم يسجدوا لهم؟","answer":"اتخذوهم أربابًا بطاعتهم في تحليل الحرام وتحريم الحلال وتقديم أقوالهم على حكم الله، لا بالسجود لهم؛ فالربوبية هنا ربوبية تشريع وطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص121–124.","url":""}]},{"id":"s9-196","number":196,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"لماذا جمع بين ﴿أحبارهم ورهبانهم﴾؟","answer":"الأحبار علماء اليهود، والرهبان عباد النصارى؛ فالجمع يستوعب القيادات الدينية العلمية والتعبدية التي مُنحت حق التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص123–126.","url":""}]},{"id":"s9-197","number":197,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿أربابًا من دون الله﴾ بصيغة الجمع؟","answer":"جُمعت الأرباب لتعدد الأشخاص والمرجعيات التي أطاعوها استقلالًا من دون الله، فكل مطاع في مخالفة حكمه جُعل ربًا من هذه الجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص125–127.","url":""}]},{"id":"s9-198","number":198,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"لماذا عطف ﴿والمسيح ابن مريم﴾ على الأحبار والرهبان مع اختلاف طريقة اتخاذه ربًّا؟","answer":"عُطف المسيح لأنه اتخذ ربًا بالاعتقاد في ذاته وعبادته، بينما اتخذ الأحبار والرهبان أربابًا بالطاعة التشريعية؛ فجمع صورتي الانحراف مع اختلافهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص126–129.","url":""}]},{"id":"s9-199","number":199,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"لماذا وصف المسيح بـ﴿ابن مريم﴾ في مقام إنكار ألوهيته؟","answer":"﴿ابن مريم﴾ يذكر بنسبه البشري وولادته من أم، فينقض دعوى الألوهية من داخل الوصف ويؤكد عبوديته وبشريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص128–130.","url":""}]},{"id":"s9-200","number":200,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أمروا إلا ليعبدوا إلهًا واحدًا﴾؟","answer":"القصر بـ﴿ما... إلا﴾ يرد اتخاذ الأرباب المتعددة، ويقرر أن أصل الأمر المنزل عليهم عبادة معبود واحد لا شريك له؛ فناقض فعلهم حقيقة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص129–131.","url":""}]},{"id":"s9-201","number":201,"surah":9,"verses":[31],"verseLabel":"التوبة: 31","question":"لماذا ختم بـ﴿سبحانه عما يشركون﴾؟","answer":"التسبيح تنزيه لله عن الشركاء والبنوة وعن أن يشاركه بشر في حق التشريع والعبادة، فجاء خاتمة تبطل ما سبق من اتخاذ الأرباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص130–131.","url":""}]},{"id":"s9-202","number":202,"surah":9,"verses":[32],"verseLabel":"التوبة: 32","question":"لماذا صوّر محاربة الدين بأنها محاولة ﴿ليطفئوا نور الله بأفواههم﴾؟","answer":"شُبه الدين بالنور لما فيه من هداية وظهور، وشُبه طعنهم فيه بالنفخ لإطفائه؛ فالصورة تسخر من ضعف وسيلتهم أمام نور الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص132–136.","url":""}]},{"id":"s9-203","number":203,"surah":9,"verses":[32],"verseLabel":"التوبة: 32","question":"لماذا خص الأفواه وسيلةً لإطفاء النور؟","answer":"خُصت الأفواه لأن حربهم قائمة على الأقوال المفتراة والطعن والتكذيب، ولتصوير عجزها: أفواه تنفخ في نور لا تطفئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص134–138.","url":""}]},{"id":"s9-204","number":204,"surah":9,"verses":[32],"verseLabel":"التوبة: 32","question":"ما سرّ التعبير في قوله تعالى: ﴿ويأبى الله إلا أن يتم نوره﴾، مع أن الاستثناء بعد النفي؟","answer":"التركيب قصر بطريق النفي والاستثناء: لا يريد الله ولا يقضي إلا إتمام نوره؛ و﴿يأبى﴾ تصور امتناعًا قاطعًا لكل نتيجة سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص137–140.","url":""}]},{"id":"s9-205","number":205,"surah":9,"verses":[32],"verseLabel":"التوبة: 32","question":"لماذا اختير ﴿يتم نوره﴾ لا «يحفظ نوره»؟","answer":"الإتمام لا يقتصر على بقاء النور، بل يدل على بلوغه كمال ظهوره وانتشاره؛ فهو أقوى من مجرد الحفظ من الزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص139–142.","url":""}]},{"id":"s9-206","number":206,"surah":9,"verses":[32],"verseLabel":"التوبة: 32","question":"لماذا ختم بـ﴿ولو كره الكافرون﴾؟","answer":"الخاتمة تقرر أن كراهة الكافرين لا تغير وعد الله ولا تمنع إتمام نوره، وفيها مقابلة بين إرادتهم العاجزة وإرادته النافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص141–146.","url":""}]},{"id":"s9-207","number":207,"surah":9,"verses":[33],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿هو الذي أرسل رسوله﴾ بعد ذكر محاولة إطفاء النور؟","answer":"بعد تصوير محاولة الإطفاء، بين أن صاحب النور هو الذي أرسل رسوله بالهدى؛ فالإرسال الإلهي ضمان بقاء الرسالة وظهورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص147–150.","url":""}]},{"id":"s9-208","number":208,"surah":9,"verses":[33],"verseLabel":"التوبة: 33","question":"لماذا جمع بين ﴿الهدى ودين الحق﴾؟","answer":"الهدى ما جاء به الرسول من علم ودلالة، ودين الحق هو المنهج العملي والاعتقادي الثابت؛ فجمع نور المعرفة ونظام الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص149–152.","url":""}]},{"id":"s9-209","number":209,"surah":9,"verses":[33],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿ليظهره على الدين كله﴾، فأفرد الدين ثم أكده بـ﴿كله﴾؟","answer":"أُفرد الدين باعتبار جنس الملل كلها أو حقيقة الدين المخالف، وأكد بـ﴿كله﴾ لاستغراق كل ما عداه في حكم الظهور والغلبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص151–154.","url":""}]},{"id":"s9-210","number":210,"surah":9,"verses":[33],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿ولو كره المشركون﴾، وقال في الآية السابقة: ﴿ولو كره الكافرون﴾؟","answer":"ذكر الكافرين في إتمام النور لأنهم يقاومون الرسالة بالتكذيب عامة، وذكر المشركين عند إظهار الدين لأن الشرك هو النقيض المباشر للتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص153–158.","url":""}]},{"id":"s9-211","number":211,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"لماذا نادى المؤمنين قبل التحذير من الأحبار والرهبان؟","answer":"النداء بوصف الإيمان ينبههم إلى حماية عقيدتهم من استغلال القيادات الدينية، ويستنهض مقتضى الإيمان قبل كشف الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص159–162.","url":""}]},{"id":"s9-212","number":212,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿إن كثيرًا من الأحبار والرهبان﴾ ولم يعمم؟","answer":"قال ﴿كثيرًا﴾ إنصافًا ومنعًا لتعميم الذم على الجميع؛ فالفساد وقع من عدد كبير لا من كل حبر وراهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص161–164.","url":""}]},{"id":"s9-213","number":213,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"لماذا عبّر عن أخذ الأموال بالباطل بقوله: ﴿ليأكلون أموال الناس﴾؟","answer":"استعير الأكل للاستيلاء والانتفاع بالمال؛ لأنه أبرز غايات أخذه، وفيه تصوير لابتلاع حقوق الناس وإفنائها في مصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص163–166.","url":""}]},{"id":"s9-214","number":214,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"لماذا جمع بين أكل الأموال والصد عن سبيل الله؟","answer":"جمعا لأن فسادهم مزدوج: يستغلون الدين لتحصيل المال لأنفسهم، ثم يمنعون الناس من طريق الله حفاظًا على نفوذهم ومكاسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص165–168.","url":""}]},{"id":"s9-215","number":215,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"لماذا جمع الذهب والفضة ثم أعاد عليهما ضمير المفرد في ﴿ولا ينفقونها﴾؟","answer":"عاد الضمير المؤنث المفرد إلى الفضة لقربها، أو إلى الأموال والكنوز باعتبارها جماعة أو نفسًا واحدة، ودخل الذهب معها بحكم الاقتران.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص167–171.","url":""}]},{"id":"s9-216","number":216,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"لماذا سمّى ادخار المال ﴿كنزًا﴾ وربطه بعدم الإنفاق؟","answer":"الكنز جمع المال وضم بعضه إلى بعض، وذمه متعلق بحبس حق الله وعدم الإنفاق الواجب، لا بمجرد الادخار المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص170–173.","url":""}]},{"id":"s9-217","number":217,"surah":9,"verses":[34],"verseLabel":"التوبة: 34","question":"لماذا استعمل ﴿فبشرهم بعذاب أليم﴾ في مقام الوعيد؟","answer":"البشارة هنا تهكم يزيد الوعيد مرارة؛ إذ وُضع خبر العذاب موضع الخبر الذي يسر، فصار انتظارهم عكس ما يرجون من كنوزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص173–177.","url":""}]},{"id":"s9-218","number":218,"surah":9,"verses":[35],"verseLabel":"التوبة: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم يحمى عليها﴾، فاستعمل ﴿على﴾ لا «تحمى في النار»؟","answer":"﴿يحمى عليها﴾ تصور إيقاد النار فوق الكنوز وإحاطتها بالحرارة حتى تصير أداة كي، لا مجرد وجودها داخل النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص178–181.","url":""}]},{"id":"s9-219","number":219,"surah":9,"verses":[35],"verseLabel":"التوبة: 35","question":"لماذا خُصت الجباه والجنوب والظهور بالكي؟","answer":"خُصت الجباه والجنوب والظهور لأنها مواضع الإعراض والبخل والتقلب في النعيم؛ أو لاستيعاب جهات البدن أمامًا وجنبًا وخلفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص180–184.","url":""}]},{"id":"s9-220","number":220,"surah":9,"verses":[35],"verseLabel":"التوبة: 35","question":"لماذا تحولت الكنوز نفسها إلى أداة عذاب أصحابها؟","answer":"قلبت المجازاة جنس ما أحبوه إلى ما يؤلمهم؛ فالمال الذي منعوا حقه يحمى ويواجههم بعاقبة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص183–186.","url":""}]},{"id":"s9-221","number":221,"surah":9,"verses":[35],"verseLabel":"التوبة: 35","question":"ما سرّ التعبير بقوله تعالى: لهم: ﴿هذا ما كنزتم لأنفسكم﴾ مع أنهم ظنوا أنهم يدخرون لمصلحتها؟","answer":"اللام في ﴿لأنفسكم﴾ للتهكم: ظنوا الكنز مصلحة لها، فإذا هو مدخر عليها لا لها، وعذابه هو الحاصل الحقيقي الذي قدموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص185–188.","url":""}]},{"id":"s9-222","number":222,"surah":9,"verses":[35],"verseLabel":"التوبة: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا ما كنتم تكنزون﴾، فجعل المكنوز شيئًا يذاق؟","answer":"استعير الذوق لمباشرة ألم الجزاء، وجُعل المكنوز مذوقًا لأن عاقبة الكنز وعذابه صارت كأنها عين ما يذوقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص188–190.","url":""}]},{"id":"s9-223","number":223,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿إن عدة الشهور عند الله اثنا عشر شهرًا﴾ مع أن هذا معلوم بالحساب؟","answer":"ليس المقصود مجرد المعلومة الحسابية، بل تثبيت النظام الشرعي للشهور ورد عبث النسيء؛ فالعدد عند الله لا يتغير بأهواء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص191–194.","url":""}]},{"id":"s9-224","number":224,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"لماذا قيد العدد بقوله: ﴿في كتاب الله يوم خلق السماوات والأرض﴾؟","answer":"القيد يقرر أن نظام الاثني عشر ثابت في تقدير الله منذ خلق الكون ومكتوب في حكمه، فلا تملكه أعراف الجاهلية بالتبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص193–197.","url":""}]},{"id":"s9-225","number":225,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿منها أربعة حرم﴾ ولم يسمها؟","answer":"لم تسم لأنها معلومة متوارثة عند العرب، ولأن المقصود هنا تثبيت عددها وحرمتها لا تعليم أسمائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص196–199.","url":""}]},{"id":"s9-226","number":226,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"لماذا أشار إلى نظام الشهور بقوله: ﴿ذلك الدين القيم﴾؟","answer":"ذلك الحساب والتحريم هو النظام المستقيم الذي لا اعوجاج فيه، والالتزام به من الدين لأنه حكم الله في الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص198–202.","url":""}]},{"id":"s9-227","number":227,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تظلموا فيهن أنفسكم﴾ مع أن الظلم محرم في كل الشهور؟","answer":"الظلم محرم دائمًا، لكنه في الأشهر الحرم أشد حرمة وأعظم تبعة؛ والنهي يحفظ حرمتها من العدوان والتبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص201–204.","url":""}]},{"id":"s9-228","number":228,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"لماذا قابل ﴿يقاتلونكم كافة﴾ بـ﴿فقاتلوا المشركين كافة﴾؟","answer":"قوبلت الكافتان لإيجاب وحدة صف المؤمنين أمام اجتماع المشركين؛ فإن قاتلوكم مجتمعين فواجهوهم جميعًا بلا تفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص203–206.","url":""}]},{"id":"s9-229","number":229,"surah":9,"verses":[36],"verseLabel":"التوبة: 36","question":"لماذا ختم بـ﴿واعلموا أن الله مع المتقين﴾؟","answer":"معية الله للمتقين تثبتهم بعد أمر القتال، وتبين أن النصر مرتبط بالتقوى وحفظ حدود الله حتى مع العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص205–206.","url":""}]},{"id":"s9-230","number":230,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"لماذا وصف النسيء بأنه ﴿زيادة في الكفر﴾ لا كفر مستقل؟","answer":"النسيء أضيف إلى كفرهم الأصلي؛ فهو زيادة لأنهم لم يكتفوا بالشرك، بل بدلوا تشريع الله وأحلوا وحرموا بحسب المصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص207–210.","url":""}]},{"id":"s9-231","number":231,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿يضل به الذين كفروا﴾ بالبناء للمجهول في قراءة الجمهور؟","answer":"البناء للمجهول يركز على وقوع الضلال واستحكامه فيهم، مع إمكان كون المضلِّل شياطينهم أو رؤساءهم أو النسيء نفسه سببًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص209–212.","url":""}]},{"id":"s9-232","number":232,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"لماذا قابل ﴿يحلونه عامًا ويحرمونه عامًا﴾؟","answer":"المقابلة تصور اضطراب حكمهم من عام إلى عام؛ فالحرام عندهم ليس ثابتًا بل تابع للهوى والحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص211–215.","url":""}]},{"id":"s9-233","number":233,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿ليواطئوا عدة ما حرم الله﴾؟","answer":"المواطأة الموافقة؛ كانوا يبدلون أسماء الشهور ليحافظوا ظاهريًا على عدد أربعة حرم، مع انتهاك عين ما حرمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص214–218.","url":""}]},{"id":"s9-234","number":234,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"لماذا كرر نتيجة التحليل: ﴿فيحلوا ما حرم الله﴾؟","answer":"الأولى تصف طريقتهم في التبديل، والثانية تكشف نتيجتها الحقيقية: مهما وافقوا العدد فقد أحلوا ما حرم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص217–220.","url":""}]},{"id":"s9-235","number":235,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿زين لهم سوء أعمالهم﴾؟","answer":"قُلبت معاييرهم حتى رأوا العمل السيئ حسنًا؛ فالتزيين يفسر إصرارهم واطمئنانهم إلى التحايل على الشرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص219–223.","url":""}]},{"id":"s9-236","number":236,"surah":9,"verses":[37],"verseLabel":"التوبة: 37","question":"لماذا ختم بـ﴿والله لا يهدي القوم الكافرين﴾؟","answer":"الخاتمة تناسب من زُين له الكفر فأصر عليه؛ فحرمان الهداية جزاء اختيارهم وتبديلهم حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص223–230.","url":""}]},{"id":"s9-237","number":237,"surah":9,"verses":[38],"verseLabel":"التوبة: 38","question":"ما سرّ توجيه العتاب إلى المؤمنين في قوله تعالى: ﴿ما لكم إذا قيل لكم انفروا... اثاقلتم﴾؟","answer":"الاستفهام ينكر حالهم عند دعوة النفير: أي عذر لكم في التثاقل بعد وضوح الأمر والحاجة؟ وفيه عتاب محرك للهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص231–234.","url":""}]},{"id":"s9-238","number":238,"surah":9,"verses":[38],"verseLabel":"التوبة: 38","question":"لماذا اختيرت صيغة ﴿اثاقلتم﴾ الثقيلة صوتيًا؟","answer":"ثقل حروف ﴿اثاقلتم﴾ وتتابعها يحاكي بطء الحركة وثقل النفس، فجاء جرسها مصورًا لمعناها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص233–236.","url":""}]},{"id":"s9-239","number":239,"surah":9,"verses":[38],"verseLabel":"التوبة: 38","question":"ما الصورة في قوله: ﴿اثاقلتم إلى الأرض﴾؟","answer":"صوّرهم كأجسام ثقيلة لاصقة بالأرض لا تقوى على الارتفاع؛ وهو تمثيل لتعلقهم بالدنيا وكرههم النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص235–238.","url":""}]},{"id":"s9-240","number":240,"surah":9,"verses":[38],"verseLabel":"التوبة: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿أرضيتم بالحياة الدنيا من الآخرة﴾؟","answer":"ضمن ﴿رضيتم﴾ معنى الاستبدال، فعدي بـ﴿من﴾؛ أي أرضيتم بالدنيا بدل الآخرة، وفي السؤال إنكار لسوء المفاضلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص237–240.","url":""}]},{"id":"s9-241","number":241,"surah":9,"verses":[38],"verseLabel":"التوبة: 38","question":"لماذا وصف متاع الدنيا بأنه ﴿قليل﴾ لا «قصير»؟","answer":"وصفه بالقلة لأن المقارنة في القيمة والمتاع، لا في طول الزمن وحده؛ فكل الدنيا قليلة بجانب نعيم الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص239–242.","url":""}]},{"id":"s9-242","number":242,"surah":9,"verses":[39],"verseLabel":"التوبة: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا تنفروا يعذبكم عذابًا أليمًا ويستبدل قومًا غيركم﴾؟","answer":"رتبت ثلاثة آثار للتخلف: عذاب يصيبهم، واستبدال يرفع شرف التكليف عنهم، ثم تقرير أنهم لا يضرون الله ولا دينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص243–247.","url":""}]},{"id":"s9-243","number":243,"surah":9,"verses":[39],"verseLabel":"التوبة: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تضروه شيئًا﴾، فنكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم أقل ضرر؛ فتخلفهم يعود عليهم وحدهم ولا ينقص ملك الله أو يتم رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص247–250.","url":""}]},{"id":"s9-244","number":244,"surah":9,"verses":[39],"verseLabel":"التوبة: 39","question":"لماذا ختم بـ﴿والله على كل شيء قدير﴾؟","answer":"القدرة العامة تعلل تنفيذ الوعيد والاستبدال ونصر الدين بغيرهم؛ فلا يتوقف أمره على جماعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص250–252.","url":""}]},{"id":"s9-245","number":245,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا تنصروه فقد نصره الله﴾، فجاء جواب الشرط بحدث ماض؟","answer":"جاء الماضي دليلًا واقعًا على كفايته سبحانه: إن تركتم نصره فقد نصره الله في أشد الظروف من قبل، فلا تتوقف حمايته عليكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص253–256.","url":""}]},{"id":"s9-246","number":246,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"لماذا وصف النبي ﷺ بقوله: ﴿ثاني اثنين﴾ ولم يذكر اسم صاحبه؟","answer":"﴿ثاني اثنين﴾ يصور قلة العدد وشدة الانفراد لإظهار عظم النصر، وأغنى مقام الصحبة المشهور عن تسمية أبي بكر رضي الله عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص255–258.","url":""}]},{"id":"s9-247","number":247,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"لماذا كرر ﴿إذ﴾ ثلاث مرات في قصة الغار؟","answer":"كل ﴿إذ﴾ تستحضر مرحلة من المشهد: الإخراج، والوجود في الغار، وكلامه لصاحبه؛ فتفصل اللقطات وتحييها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص257–261.","url":""}]},{"id":"s9-248","number":248,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ هما في الغار﴾، ولم يسم غار ثور؟","answer":"لم يسم الغار لأن العبرة بالحال لا بالمكان الجغرافي، ولأنه كان معهودًا في القصة عند المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص260–262.","url":""}]},{"id":"s9-249","number":249,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"ما دلالة قول النبي: لصاحبه: ﴿لا تحزن﴾، ولم يقل: «لا تخف»؟","answer":"الحزن ألم على مكروه واقع أو متوقع، وكان المقام مقام أسى وقلق على الرسول والدعوة، أما الخوف فأخص بتوقع الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص261–264.","url":""}]},{"id":"s9-250","number":250,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"لماذا علل النهي عن الحزن بقوله: ﴿إن الله معنا﴾؟","answer":"المعية الإلهية معية حفظ ونصر وعلم، وهي أقوى سبب لزوال الحزن؛ فمن كان الله معه لا تضره قلة العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص263–266.","url":""}]},{"id":"s9-251","number":251,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنزل الله سكينته عليه﴾، وعلى من يعود الضمير؟","answer":"الأقرب عود الضمير إلى النبي ﷺ لاتساق الضمائر في ﴿نصره، أخرجه، لصاحبه، أيده﴾، وقيل إلى أبي بكر؛ وفي الحال السكينة من الله في موقف الغار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص265–268.","url":""}]},{"id":"s9-252","number":252,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿وأيده بجنود لم تروها﴾ كما قال في حنين: ﴿وأنزل جنودًا لم تروها﴾؟","answer":"في الغار قيل ﴿أيده﴾ لأن الكلام عن تأييد الرسول ﷺ، وفي حنين قيل ﴿أنزل جنودًا﴾ ضمن تعداد ما نزل على الرسول والمؤمنين؛ واتحد وصف خفاء الجنود.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص267–270.","url":""}]},{"id":"s9-253","number":253,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿وجعل كلمة الذين كفروا السفلى وكلمة الله هي العليا﴾؟","answer":"جعل كلمة الكفر سفلى حادثة بفعل الله، أما كلمة الله فهي العليا في ذاتها؛ وضمير الفصل يؤكد اختصاصها بالعلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص269–271.","url":""}]},{"id":"s9-254","number":254,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"لماذا جاءت ﴿كلمة الله هي العليا﴾ جملة اسمية، بخلاف ﴿جعل كلمة الذين كفروا السفلى﴾؟","answer":"الجملة الاسمية تثبت دوام علو كلمة الله وأصالته، بينما الفعل ﴿جعل﴾ يصور إحداث خفض كلمة الكفر بعد محاولة ارتفاعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص270–272.","url":""}]},{"id":"s9-255","number":255,"surah":9,"verses":[40],"verseLabel":"التوبة: 40","question":"لماذا ختم بـ﴿والله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ غالب ينصر رسوله ويخفض الكفر، و﴿حكيم﴾ يدبر ذلك بأسباب ظاهرة وخفية في أوقاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص271–272.","url":""}]},{"id":"s9-256","number":256,"surah":9,"verses":[41],"verseLabel":"التوبة: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿انفروا خفافًا وثقالًا﴾، وجمع بين الضدين؟","answer":"الجمع بين الضدين يعم أحوال المكلفين: نشاطًا وثقلًا، شبابًا وشيوخًا، غنى وفقرًا؛ فلا يتخذ اختلاف الحال ذريعة للتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص273–277.","url":""}]},{"id":"s9-257","number":257,"surah":9,"verses":[41],"verseLabel":"التوبة: 41","question":"ما المقصود بـ﴿خفافًا وثقالًا﴾، ولماذا تُرك اللفظ محتملًا؟","answer":"تُرك اللفظ محتملًا ليستوعب كل خفة وثقل معتبرين، فيتجدد معناه بتجدد أحوال الناس ووسائل النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص275–280.","url":""}]},{"id":"s9-258","number":258,"surah":9,"verses":[41],"verseLabel":"التوبة: 41","question":"ما سرّ تقديم الجهاد بالأموال على الأنفس مرة أخرى؟","answer":"قُدم المال لكثرة الحاجة إليه وإمكان الجهاد به قبل المباشرة بالنفس، ثم ذكرت النفس بوصفها غاية البذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص279–282.","url":""}]},{"id":"s9-259","number":259,"surah":9,"verses":[41],"verseLabel":"التوبة: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكم خير لكم﴾ مع أن الجهاد قد يكون شاقًا؟","answer":"خير الجهاد في ثوابه وعاقبته ونصر الجماعة، وإن شق في الحال؛ فالمعيار هو المآل لا الراحة العاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص281–284.","url":""}]},{"id":"s9-260","number":260,"surah":9,"verses":[41],"verseLabel":"التوبة: 41","question":"لماذا علق إدراك الخير بقوله: ﴿إن كنتم تعلمون﴾؟","answer":"التعليق يحثهم على إدراك حقيقة الموازنة؛ فلو علموا علمًا نافعًا لقدموا الخير الباقي على مشقة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص283–288.","url":""}]},{"id":"s9-261","number":261,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿لو كان عرضًا قريبًا وسفرًا قاصدًا لاتبعوك﴾؟","answer":"تكشف الجملة معيار المنافقين: لو كانت منفعة سهلة وسفرًا معتدلًا لاتبعوا، لكنهم تخلفوا حين بعدت المسافة وشقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص289–293.","url":""}]},{"id":"s9-262","number":262,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"لماذا سمّى الغنيمة ﴿عرضًا﴾؟","answer":"العرض متاع زائل يعرض ثم يختفي، فناسب الغنيمة الدنيوية القريبة التي كانت تحركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص291–294.","url":""}]},{"id":"s9-263","number":263,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"لماذا وصف السفر بـ﴿قاصدًا﴾ لا «قصيرًا»؟","answer":"القاصد هو المتوسط المعتدل الذي لا مشقة شديدة فيه، وهو أدق من «قصير»؛ فقد يكون السفر غير قصير لكنه سهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص293–296.","url":""}]},{"id":"s9-264","number":264,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن بعدت عليهم الشقة﴾؟","answer":"الشقة المسافة التي يشق قطعها، وإسناد البعد إليها يجمع طول الطريق وما يصحبه من مشقة في نفس واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص295–298.","url":""}]},{"id":"s9-265","number":265,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"لماذا أخبر أنهم سيحلفون بالله قبل أن يقع حلفهم؟","answer":"الإخبار السابق يكشفهم ويحقق صدق الوحي، ويهيئ النبي ﷺ والمؤمنين لأعذارهم المصنوعة عند العودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص297–300.","url":""}]},{"id":"s9-266","number":266,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"ما دلالة قولهم: ﴿لو استطعنا لخرجنا معكم﴾، مع أن الله كذبهم؟","answer":"قالوا ذلك ليوهموا أن التخلف لعجز لا لفساد إرادة، وكذبهم الله لأنهم لو أرادوا الخروج لأعدوا عدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص299–302.","url":""}]},{"id":"s9-267","number":267,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"ما معنى ﴿يهلكون أنفسهم﴾ مع أنهم أرادوا بالحلف النجاة؟","answer":"حلفهم الكاذب يوقعهم في الإثم والنفاق والعقوبة، فوسيلة النجاة الظاهرة صارت سبب هلاك النفس الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص301–304.","url":""}]},{"id":"s9-268","number":268,"surah":9,"verses":[42],"verseLabel":"التوبة: 42","question":"لماذا ختم بـ﴿والله يعلم إنهم لكاذبون﴾ مع ظهور كذبهم؟","answer":"ختم بعلمه لتأكيد أن حلفهم لا يستر الحقيقة، ولتسجيل الكذب عليهم بحكم من يعلم سرائرهم قبل أقوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص303–304.","url":""}]},{"id":"s9-269","number":269,"surah":9,"verses":[43],"verseLabel":"التوبة: 43","question":"لماذا بدأ عتاب النبي ﷺ بالدعاء: ﴿عفا الله عنك﴾؟","answer":"سبق العفو العتاب تلطفًا وتشريفًا للنبي ﷺ، وتطمينًا إلى أن المقصود التعليم وبيان الأولى لا المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص305–307.","url":""}]},{"id":"s9-270","number":270,"surah":9,"verses":[43],"verseLabel":"التوبة: 43","question":"ما سرّ التعبير بقوله تعالى: ﴿لم أذنت لهم﴾، ولم يصرح بالفعل الذي أذن لهم في تركه؟","answer":"حُذف متعلق الإذن للعلم به من السياق، أي الإذن في التخلف، فركز التعبير على أصل المبادرة بالإذن قبل التبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص306–308.","url":""}]},{"id":"s9-271","number":271,"surah":9,"verses":[43],"verseLabel":"التوبة: 43","question":"لماذا جعل الغاية: ﴿حتى يتبين لك الذين صدقوا وتعلم الكاذبين﴾ مع أن الله يعلمهم؟","answer":"المقصود أن يتبين الصادق والكاذب للنبي ﷺ في عالم الشهادة بحسب علاماتهما، أما علم الله السابق فلا يطرأ عليه جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص308–309.","url":""}]},{"id":"s9-272","number":272,"surah":9,"verses":[44],"verseLabel":"التوبة: 44","question":"لماذا نفى عن المؤمنين أن يستأذنوا في الجهاد بأنفسهم وأموالهم؟","answer":"الإيمان الصادق يدفع إلى الجهاد ولا يحمل صاحبه على طلب الإذن في ترك بذل المال والنفس بلا عذر؛ فالاستئذان علامة على خلل الدافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص310–312.","url":""}]},{"id":"s9-273","number":273,"surah":9,"verses":[44],"verseLabel":"التوبة: 44","question":"لماذا أعاد الإيمان بالله واليوم الآخر هنا؟","answer":"أعيد الإيمان بالبدء والمعاد لأنهما أصل البذل: الثقة بالله والرجاء في جزاء الآخرة يمنعان الاستئذان في التخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص311–313.","url":""}]},{"id":"s9-274","number":274,"surah":9,"verses":[44],"verseLabel":"التوبة: 44","question":"لماذا ختم بـ﴿والله عليم بالمتقين﴾؟","answer":"علمه بالمتقين يميز صدقهم من أعذار غيرهم، ويقرر أن عدم الاستئذان أثر تقوى باطنة لا مجرد اندفاع ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص313–314.","url":""}]},{"id":"s9-275","number":275,"surah":9,"verses":[45],"verseLabel":"التوبة: 45","question":"لماذا حصر الاستئذان في الذين لا يؤمنون وارتابت قلوبهم؟","answer":"القصر بـ﴿إنما﴾ يجعل الاستئذان بلا عذر علامة لمن ضعف إيمانه وامتلأ قلبه بالشك، فيقابل حال المتقين السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص315–317.","url":""}]},{"id":"s9-276","number":276,"surah":9,"verses":[45],"verseLabel":"التوبة: 45","question":"لماذا أسند الارتياب إلى القلوب؟","answer":"أُسند الارتياب إلى القلوب لأنها محل الاعتقاد واليقين، فدل على أن التردد نابع من أصل باطن لا عارض سلوكي فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص316–318.","url":""}]},{"id":"s9-277","number":277,"surah":9,"verses":[45],"verseLabel":"التوبة: 45","question":"ما الصورة في قوله: ﴿فهم في ريبهم يترددون﴾؟","answer":"صُور الريب كحيز يدورون داخله ذهابًا وإيابًا بلا مخرج؛ فالتردد حركة مضطربة لا تنتهي إلى قرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص318–321.","url":""}]},{"id":"s9-278","number":278,"surah":9,"verses":[45],"verseLabel":"التوبة: 45","question":"لماذا جمع بين الاسم ﴿في ريبهم﴾ والمضارع ﴿يترددون﴾؟","answer":"﴿في ريبهم﴾ يثبت إحاطة الشك واستقراره، و﴿يترددون﴾ يصور تجدد الحيرة والحركة؛ فجمع ثبات السبب واستمرار أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص320–321.","url":""}]},{"id":"s9-279","number":279,"surah":9,"verses":[46],"verseLabel":"التوبة: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو أرادوا الخروج لأعدوا له عدة﴾؟","answer":"جعل إعداد العدة دليل الإرادة الصادقة؛ فالإرادة التي لا تسبقها أسباب الخروج دعوى يكذبها الواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص322–324.","url":""}]},{"id":"s9-280","number":280,"surah":9,"verses":[46],"verseLabel":"التوبة: 46","question":"لماذا كرر الجذر في ﴿لأعدوا له عدة﴾؟","answer":"اشتق المفعول من فعله للتوكيد والتصوير: لو أرادوا لأوجدوا إعدادًا كاملًا ظاهرًا، لا نية مبهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص323–325.","url":""}]},{"id":"s9-281","number":281,"surah":9,"verses":[46],"verseLabel":"التوبة: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن كره الله انبعاثهم فثبطهم﴾؟","answer":"كره الله خروجهم لما فيه من الإفساد، فسلبهم التوفيق وثبط عزائمهم جزاءً على نفاقهم، فوافق تخلفهم مصلحة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص325–327.","url":""}]},{"id":"s9-282","number":282,"surah":9,"verses":[46],"verseLabel":"التوبة: 46","question":"لماذا عبّر عن خروجهم بـ﴿انبعاثهم﴾؟","answer":"الانبعاث نهوض سريع بدافع قوي بعد سكون، فاختياره يصور الخروج الذي لم تصدق دوافعهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص326–328.","url":""}]},{"id":"s9-283","number":283,"surah":9,"verses":[46],"verseLabel":"التوبة: 46","question":"لماذا بُني ﴿وقيل اقعدوا مع القاعدين﴾ للمجهول؟","answer":"بُني للمجهول لأن المقصود وقوع الحكم عليهم بالقعود، سواء كان القائل لسان القدر أو داعي الكسل والنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص327–328.","url":""}]},{"id":"s9-284","number":284,"surah":9,"verses":[47],"verseLabel":"التوبة: 47","question":"كيف كان عدم خروج المنافقين خيرًا للمؤمنين؟","answer":"لو خرجوا لنشروا الاضطراب وسعوا بالوشاية والفتنة بين الصفوف؛ فكان حبسهم عن الجيش حماية له من شرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص329–331.","url":""}]},{"id":"s9-285","number":285,"surah":9,"verses":[47],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿ما زادوكم إلا خبالًا﴾ بصيغة القصر؟","answer":"القصر ينفي كل زيادة خير منهم؛ فلم يكن أثرهم المتوقع إلا الخبال والفساد، دون نفع يوازن ضررهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص330–332.","url":""}]},{"id":"s9-286","number":286,"surah":9,"verses":[47],"verseLabel":"التوبة: 47","question":"ما الصورة في قوله: ﴿ولأوضعوا خلالكم﴾؟","answer":"الإيضاع إسراع شديد، و﴿خلالكم﴾ بين صفوفكم؛ فالصورة تعرضهم يسرعون داخل الجيش بالنميمة والتحريض لتفكيكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص331–333.","url":""}]},{"id":"s9-287","number":287,"surah":9,"verses":[47],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿يبغونكم الفتنة﴾، وعدّى البغي إلى المؤمنين؟","answer":"ضمن ﴿يبغونكم﴾ معنى يطلبون لكم أو يريدون إصابتكم، فعدي إلى المؤمنين لتصويرهم هدفًا مقصودًا بالفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص332–334.","url":""}]},{"id":"s9-288","number":288,"surah":9,"verses":[47],"verseLabel":"التوبة: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وفيكم سماعون لهم﴾؟","answer":"السماعون إما مستجيبون لأقوالهم أو عيون ينقلون لهم الأخبار؛ وفي الحال يكشف التعبير منافذ تأثيرهم داخل الصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص334–336.","url":""}]},{"id":"s9-289","number":289,"surah":9,"verses":[47],"verseLabel":"التوبة: 47","question":"لماذا ختم بـ﴿والله عليم بالظالمين﴾؟","answer":"العلم بالظالمين يحيط بنفاقهم ومن يستجيب لهم، ويهدد بأن تدبيرهم لا يخفى ولا يفلت من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص335–336.","url":""}]},{"id":"s9-290","number":290,"surah":9,"verses":[48],"verseLabel":"التوبة: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد ابتغوا الفتنة من قبل﴾؟","answer":"﴿لقد﴾ توكد أن طلبهم الفتنة قديم مجرب، فلا ينبغي الاغترار بأعذارهم الجديدة؛ فهذا امتداد لسلوك سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص337–339.","url":""}]},{"id":"s9-291","number":291,"surah":9,"verses":[48],"verseLabel":"التوبة: 48","question":"ما الصورة في قوله: ﴿وقلبوا لك الأمور﴾؟","answer":"صُور تدبيرهم كمن يقلب وجوه الأمر بحثًا عن حيلة تفسده، فيغير الحقائق ويقدم ويؤخر حتى يحقق غرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص339–342.","url":""}]},{"id":"s9-292","number":292,"surah":9,"verses":[48],"verseLabel":"التوبة: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى جاء الحق وظهر أمر الله وهم كارهون﴾؟","answer":"استمر تقليبهم إلى غاية حاسمة: جاء الحق وظهر أمر الله رغم كراهتهم؛ فالجملة تقابل طول مكرهم بنهاية غلبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص341–344.","url":""}]},{"id":"s9-293","number":293,"surah":9,"verses":[48],"verseLabel":"التوبة: 48","question":"لماذا فرّق بين ﴿جاء الحق﴾ و﴿ظهر أمر الله﴾؟","answer":"مجيء الحق ظهور الدليل والوحي، وظهور أمر الله غلبة حكمه ودينه في الواقع؛ فالأول بيان والثاني تمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص343–347.","url":""}]},{"id":"s9-294","number":294,"surah":9,"verses":[49],"verseLabel":"التوبة: 49","question":"ما دلالة قول المنافق: ﴿ائذن لي ولا تفتني﴾، فجعل الخروج فتنة؟","answer":"جعل الخروج فتنة يتعرض فيها للنساء أو المشقة ذريعة لطلب الإذن، فسمى الطاعة فتنة ليهرب من امتحان أصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص348–351.","url":""}]}]);
